-- NEET UG previous-year questions (official NTA papers), 2024.
-- Question text is the exam's; answers are solved and cross-checked independently by UG Prep
-- (not the official key); one-liners and explanations are original. Idempotent by id.
INSERT INTO public.questions (id, exam, subject, topic, stem, options, correct_option_id, one_liner,
  explanation, distractors, high_yield, difficulty, is_pyq, pyq_year, repeat_count, source, image_url)
VALUES
('74ed9f98-b6e5-50ed-9ade-68ee96f3ea04', 'neet_ug', 'Physics', 'Moving Charges and Magnetism', 'A tightly wound 100 turns coil of radius 10 cm carries a current of 7 A. The magnitude of the magnetic field at the centre of the coil is (Take permeability of free space as 4π×10⁻⁷ SI units):', '[{"id": "a", "text": "4.4 mT"}, {"id": "b", "text": "44 T"}, {"id": "c", "text": "44 mT"}, {"id": "d", "text": "4.4 T"}]'::jsonb, 'a', 'Field at the centre of an N-turn circular coil is B = μ₀NI/2R.', 'B = μ₀NI/(2R) = (4π×10⁻⁷ × 100 × 7)/(2 × 0.1) = 4π×10⁻⁷ × 3500 ≈ 4.4×10⁻³ T. So the field is 4.4 mT.', '{"b": "Off by a factor of 10⁴; forgets the 10⁻⁷ factor partly.", "c": "Ten times too large; radius probably not converted to metres correctly.", "d": "Answer in tesla ignores the 10⁻³ factor."}'::jsonb, 'Magnetic field at the centre of a circular loop: B = μ₀NI/2R, directed along the axis.', 'easy', true, 2024, NULL, 'NEET UG 2024 (NTA) · answer verified by UG Prep', NULL),
('0feb6574-96d4-58ee-8030-e268cbc6c4d0', 'neet_ug', 'Physics', 'Magnetism and Matter', 'Match List-I with List-II.
List-I (Material) | List-II (Susceptibility (χ))
(A) Diamagnetic | (I) χ = 0
(B) Ferromagnetic | (II) 0 > χ ≥ −1
(C) Paramagnetic | (III) χ >> 1
(D) Non-magnetic | (IV) 0 < χ < ε (a small positive number)
Choose the correct answer from the options given below:', '[{"id": "a", "text": "A-III, B-II, C-I, D-IV"}, {"id": "b", "text": "A-IV, B-III, C-II, D-I"}, {"id": "c", "text": "A-II, B-III, C-IV, D-I"}, {"id": "d", "text": "C-II, B-I, C-III, D-IV"}]'::jsonb, 'c', 'Diamagnets have small negative χ, paramagnets small positive χ, ferromagnets very large χ.', 'Diamagnetic substances have −1 ≤ χ < 0 (II), ferromagnetic χ >> 1 (III), paramagnetic a small positive χ (IV), and a non-magnetic material χ = 0 (I). This is A-II, B-III, C-IV, D-I.', '{"a": "Gives diamagnets a huge χ, which is the ferromagnetic signature.", "b": "Swaps diamagnetic and paramagnetic signs.", "d": "Repeats C and gives ferromagnets χ = 0."}'::jsonb, 'Superconductors are perfect diamagnets with χ = −1.', 'easy', true, 2024, NULL, 'NEET UG 2024 (NTA) · answer verified by UG Prep', NULL),
('6b9695ff-a2a4-55f3-99c6-fcca8b30d2ee', 'neet_ug', 'Physics', 'Thermodynamics', 'A thermodynamic system is taken through the cycle abcda. The work done by the gas along the path bc is:', '[{"id": "a", "text": "−90 J"}, {"id": "b", "text": "−60 J"}, {"id": "c", "text": "zero"}, {"id": "d", "text": "30 J"}]'::jsonb, 'c', 'Path bc is vertical on the P–V diagram, so ΔV = 0 and no work is done.', 'Along bc the volume stays at 400 cm³ while pressure rises from 100 kPa to 300 kPa. Work W = ∫P dV = 0 for an isochoric step. The −60 J figure is the work of the whole cycle (area 200 kPa × 300 cm³, traversed anticlockwise), not of bc.', '{"a": "Not any segment''s work here; arithmetic slip.", "b": "This is the net work of the full anticlockwise cycle, not path bc.", "d": "Work on ab is 100 kPa × 300 cm³ = 30 J; that is path ab, not bc."}'::jsonb, 'Work in a process equals the area under the P–V curve; isochoric work is zero.', 'easy', true, 2024, NULL, 'NEET UG 2024 (NTA) · answer verified by UG Prep', '/pyq/ug/2024/3.webp'),
('2045464e-979a-5bae-86e2-5cc46c6f570a', 'neet_ug', 'Physics', 'Wave Optics', 'An unpolarised light beam strikes a glass surface at Brewster''s angle. Then', '[{"id": "a", "text": "both the reflected and refracted light will be completely polarised."}, {"id": "b", "text": "the reflected light will be completely polarised but the refracted light will be partially polarised."}, {"id": "c", "text": "the reflected light will be partially polarised."}, {"id": "d", "text": "the refracted light will be completely polarised."}]'::jsonb, 'b', 'At Brewster''s angle only the reflected beam is fully plane polarised.', 'At the polarising angle the reflected and refracted rays are perpendicular, and the component vibrating in the plane of incidence is not reflected at all. The reflected light therefore has only the perpendicular component (completely polarised), while the refracted beam carries the rest and is only partially polarised.', '{"a": "Refracted light still contains both components, so it is not fully polarised.", "c": "At exactly Brewster''s angle reflection is completely, not partially, polarised.", "d": "It is the reflected beam, not the refracted one, that is fully polarised."}'::jsonb, 'Brewster''s law: tan i_B = μ, and reflected ⟂ refracted ray at this angle.', 'easy', true, 2024, NULL, 'NEET UG 2024 (NTA) · answer verified by UG Prep', NULL),
('b3bafcd2-42dc-5829-a472-5b3945120827', 'neet_ug', 'Physics', 'Alternating Current', 'In an ideal transformer, the turns ratio is Nₚ/Nₛ = 1/2. The ratio Vₛ : Vₚ is equal to (the symbols carry their usual meaning):', '[{"id": "a", "text": "1 : 1"}, {"id": "b", "text": "1 : 4"}, {"id": "c", "text": "1 : 2"}, {"id": "d", "text": "2 : 1"}]'::jsonb, 'd', 'For an ideal transformer Vₛ/Vₚ = Nₛ/Nₚ.', 'Nₛ/Nₚ = 2, so Vₛ/Vₚ = 2, i.e. Vₛ : Vₚ = 2 : 1 (a step-up transformer).', '{"a": "Would need equal turns.", "b": "Squares the turns ratio, which applies to impedance, not voltage.", "c": "Inverts the ratio; that is Vₚ : Vₛ."}'::jsonb, 'Ideal transformer: Vₛ/Vₚ = Nₛ/Nₚ = Iₚ/Iₛ.', 'easy', true, 2024, NULL, 'NEET UG 2024 (NTA) · answer verified by UG Prep', NULL),
('7c30b9cc-3d84-5165-a6c6-34492c0aac09', 'neet_ug', 'Physics', 'Semiconductor Electronics: Materials, Devices and Simple Circuits', 'A logic circuit provides the output Y as per the following truth table:
A | B | Y
0 | 0 | 1
0 | 1 | 0
1 | 0 | 1
1 | 1 | 0', '[{"id": "a", "text": "B̄"}, {"id": "b", "text": "B"}, {"id": "c", "text": "A·B + Ā"}, {"id": "d", "text": "A·B̄ + Ā"}]'::jsonb, 'a', 'Y is 1 exactly when B = 0, independent of A, so Y = B̄.', 'Reading the table, Y = 1 for B = 0 and Y = 0 for B = 1 whatever A is, hence Y = B̄. Checking (3): for A = 0, B = 1 it gives Ā = 1, but Y = 0, so it fails; (4) fails on the same row.', '{"b": "Y is the complement of B, not B itself.", "c": "Gives Y = 1 for A = 0, B = 1, contradicting the table.", "d": "Also gives Y = 1 for A = 0, B = 1."}'::jsonb, 'A NOT gate output is the complement of its input: Y = Ā.', 'easy', true, 2024, NULL, 'NEET UG 2024 (NTA) · answer verified by UG Prep', NULL),
('5bb5a815-ab0a-57bc-aeb0-0d9e623ec2c2', 'neet_ug', 'Physics', 'Units and Measurements', 'In a vernier calipers, (N + 1) divisions of vernier scale coincide with N divisions of main scale. If 1 MSD represents 0.1 mm, the vernier constant (in cm) is:', '[{"id": "a", "text": "100 N"}, {"id": "b", "text": "10 (N + 1)"}, {"id": "c", "text": "1/(10N)"}, {"id": "d", "text": "1/(100(N + 1))"}]'::jsonb, 'd', 'Vernier constant = 1 MSD − 1 VSD = MSD/(N + 1).', '(N + 1) VSD = N MSD, so 1 VSD = N/(N + 1) MSD. VC = 1 MSD − 1 VSD = MSD/(N + 1) = 0.1 mm/(N + 1) = 0.01 cm/(N + 1) = 1/(100(N + 1)) cm.', '{"a": "Dimensionally absurd; least count cannot grow with N.", "b": "Inverts the correct result.", "c": "Uses N instead of N + 1 and the wrong unit conversion."}'::jsonb, 'Least count of vernier = 1 MSD − 1 VSD = value of 1 MSD / number of VSDs.', 'med', true, 2024, NULL, 'NEET UG 2024 (NTA) · answer verified by UG Prep', NULL),
('db285786-d538-5738-9a70-b128a4b60dc9', 'neet_ug', 'Physics', 'Mechanical Properties of Solids', 'The maximum elongation of a steel wire of 1 m length if the elastic limit of steel and its Young''s modulus, respectively, are 8 × 10⁸ N m⁻² and 2 × 10¹¹ N m⁻², is:', '[{"id": "a", "text": "40 mm"}, {"id": "b", "text": "8 mm"}, {"id": "c", "text": "4 mm"}, {"id": "d", "text": "0.4 mm"}]'::jsonb, 'c', 'Maximum strain = elastic-limit stress / Y.', 'Strain = 8×10⁸ / 2×10¹¹ = 4×10⁻³. Elongation ΔL = strain × L = 4×10⁻³ × 1 m = 4 mm.', '{"a": "Ten times too large.", "b": "Doubles the strain.", "d": "Ten times too small."}'::jsonb, 'Young''s modulus Y = (F/A)/(ΔL/L); steel has Y ≈ 2×10¹¹ N m⁻².', 'easy', true, 2024, NULL, 'NEET UG 2024 (NTA) · answer verified by UG Prep', NULL),
('b757f43d-449d-583a-bfcd-14938d8fd7f4', 'neet_ug', 'Physics', 'Laws of Motion', 'A horizontal force 10 N is applied to a block A as shown in figure. The mass of blocks A and B are 2 kg and 3 kg, respectively. The blocks slide over a frictionless surface. The force exerted by block A on block B is:', '[{"id": "a", "text": "6 N"}, {"id": "b", "text": "10 N"}, {"id": "c", "text": "zero"}, {"id": "d", "text": "4 N"}]'::jsonb, 'a', 'The contact force must accelerate B alone.', 'Common acceleration a = 10/(2 + 3) = 2 m s⁻². The force A exerts on B gives B its acceleration: N = m_B a = 3 × 2 = 6 N.', '{"b": "That is the applied force on the pair, not the contact force.", "c": "Blocks in contact pushed together do exert a force on each other.", "d": "m_A a = 4 N is the net force on A, not the contact force."}'::jsonb, 'For blocks pushed together, contact force = (mass ahead) × common acceleration.', 'easy', true, 2024, NULL, 'NEET UG 2024 (NTA) · answer verified by UG Prep', '/pyq/ug/2024/9.webp'),
('792222c0-86d5-5497-8895-77b2dbb5b4a2', 'neet_ug', 'Physics', 'Wave Optics', 'If the monochromatic source in Young''s double slit experiment is replaced by white light, then', '[{"id": "a", "text": "there will be a central bright white fringe surrounded by a few coloured fringes."}, {"id": "b", "text": "all bright fringes will be of equal width."}, {"id": "c", "text": "interference pattern will disappear."}, {"id": "d", "text": "there will be a central dark fringe surrounded by a few coloured fringes."}]'::jsonb, 'a', 'With white light every colour has a maximum at the centre, giving a white central fringe and coloured fringes beside it.', 'At the central point the path difference is zero for all wavelengths, so every colour interferes constructively and the centre is white. Fringe width β = λD/d differs by colour, so nearby fringes become coloured (blue nearer the centre) and after a few orders they overlap into uniform illumination.', '{"b": "Fringe width depends on λ, so the colours give different widths.", "c": "A few coloured fringes remain visible near the centre.", "d": "The centre has zero path difference for all colours, so it is bright, not dark."}'::jsonb, 'Fringe width β = λD/d; red fringes are wider than blue.', 'easy', true, 2024, NULL, 'NEET UG 2024 (NTA) · answer verified by UG Prep', NULL),
('9fc2f28f-884c-59f7-b4ef-8fdc8e2161ca', 'neet_ug', 'Physics', 'Dual Nature of Radiation and Matter', 'The graph which shows the variation of (1/λ²) and its kinetic energy, E is (where λ is de Broglie wavelength of a free particle):', '[{"id": "a", "text": "Option (1) in figure"}, {"id": "b", "text": "Option (2) in figure"}, {"id": "c", "text": "Option (3) in figure"}, {"id": "d", "text": "Option (4) in figure"}]'::jsonb, 'b', 'Since λ = h/√(2mE), 1/λ² = 2mE/h², a straight line through the origin.', 'For a free particle p = √(2mE) and λ = h/p, so 1/λ² = (2m/h²)E. The plot of 1/λ² against E is a straight line through the origin, which is graph (2).', '{"a": "A curve concave down would mean 1/λ² ∝ √E or similar.", "c": "A concave-up curve would mean 1/λ² ∝ E² or similar.", "d": "A falling curve would mean λ increases with E, which is opposite to the truth."}'::jsonb, 'de Broglie wavelength λ = h/√(2mK); for an electron accelerated through V, λ = 1.227/√V nm.', 'easy', true, 2024, NULL, 'NEET UG 2024 (NTA) · answer verified by UG Prep', '/pyq/ug/2024/11.webp'),
('ddb5728a-3d2c-5ec5-8dbc-b95926ebe5b7', 'neet_ug', 'Physics', 'Electrostatic Potential and Capacitance', 'In the following circuit, the equivalent capacitance between terminal A and terminal B is:', '[{"id": "a", "text": "0.5 μF"}, {"id": "b", "text": "4 μF"}, {"id": "c", "text": "2 μF"}, {"id": "d", "text": "1 μF"}]'::jsonb, 'c', 'The network is a balanced bridge, so the middle capacitor carries no charge.', 'Each branch has two 2 μF capacitors in series and the middle capacitor joins two points at the same potential (2/2 = 2/2), so it can be removed. Each branch is 1 μF and the two branches in parallel give 2 μF.', '{"a": "Treats all four as being in series.", "b": "Ignores the series combination in each branch.", "d": "Takes only one branch."}'::jsonb, 'A capacitor or resistor bridge is balanced when the arm ratios are equal, and then the bridge element can be removed.', 'easy', true, 2024, NULL, 'NEET UG 2024 (NTA) · answer verified by UG Prep', '/pyq/ug/2024/12.webp'),
('007d3c59-c4da-5825-b02b-ce51b0865421', 'neet_ug', 'Physics', 'Electromagnetic Induction', 'In the above diagram, a strong bar magnet is moving towards solenoid-2 from solenoid-1. The direction of induced current in solenoid-1 and that in solenoid-2, respectively, are through the directions:', '[{"id": "a", "text": "AB and CD"}, {"id": "b", "text": "BA and DC"}, {"id": "c", "text": "AB and DC"}, {"id": "d", "text": "BA and CD"}]'::jsonb, 'c', 'By Lenz''s law, solenoid-1 attracts the receding N pole and solenoid-2 repels the approaching S pole.', 'The magnet''s N end recedes from solenoid-1, so the near (B) end of solenoid-1 must become an S pole; with the winding shown this needs current from A to B. The S end approaches solenoid-2, so its near (C) end must become an S pole; with the same winding this needs current from D to C. Hence AB and DC.', '{"a": "Gives solenoid-2 an N pole facing the approaching S pole, which would attract it.", "b": "Reverses solenoid-1, making it repel the receding magnet.", "d": "Reverses both, against Lenz''s law in each coil."}'::jsonb, 'Lenz''s law: the induced current opposes the change in flux that produces it.', 'hard', true, 2024, NULL, 'NEET UG 2024 (NTA) · answer verified by UG Prep', '/pyq/ug/2024/13.webp'),
('e35022d6-5433-5c19-bac9-575946912042', 'neet_ug', 'Physics', 'Semiconductor Electronics: Materials, Devices and Simple Circuits', 'Consider the following statements A and B and identify the correct answer:
A. For a solar-cell, the I-V characteristics lies in the IV quadrant of the given graph.
B. In a reverse biased pn junction diode, the current measured in (μA), is due to majority charge carriers.', '[{"id": "a", "text": "Both A and B are correct."}, {"id": "b", "text": "Both A and B are incorrect."}, {"id": "c", "text": "A is correct but B is incorrect."}, {"id": "d", "text": "A is incorrect but B is correct."}]'::jsonb, 'c', 'A solar cell works in the fourth quadrant, and reverse current comes from minority carriers.', 'A solar cell supplies power, so its I-V curve lies in the fourth quadrant (positive V, negative I), and A is correct. The small μA reverse current of a diode is due to minority carriers drifting across the junction, so B is incorrect.', '{"a": "B wrongly credits majority carriers.", "b": "A is a standard NCERT fact.", "d": "It reverses the truth of both statements."}'::jsonb, 'Solar cell I-V curve is drawn in the fourth quadrant; key points are V_oc and I_sc.', 'easy', true, 2024, NULL, 'NEET UG 2024 (NTA) · answer verified by UG Prep', '/pyq/ug/2024/14.webp'),
('04977d2d-1b86-549f-a437-32e3b34f7d40', 'neet_ug', 'Physics', 'Ray Optics and Optical Instruments', 'A light ray enters through a right angled prism at point P with the angle of incidence 30° as shown in figure. It travels through the prism parallel to its base BC and emerges along the face AC. The refractive index of the prism is:', '[{"id": "a", "text": "√3/4"}, {"id": "b", "text": "√3/2"}, {"id": "c", "text": "√5/4"}, {"id": "d", "text": "√5/2"}]'::jsonb, 'd', 'Grazing emergence at AC means the angle there is critical, and r₁ + r₂ = A = 90°.', 'At P: sin 30° = μ sin r₁, so sin r₁ = 1/(2μ). Since A = 90°, r₂ = 90° − r₁, and grazing emergence gives sin r₂ = cos r₁ = 1/μ. Then sin²r₁ + cos²r₁ = 1/(4μ²) + 1/μ² = 5/(4μ²) = 1, so μ = √5/2.', '{"a": "μ less than 1 is impossible for a prism in air.", "b": "Also less than 1; not physical here.", "c": "Below 1 as well; misses the factor of 2."}'::jsonb, 'For a prism, r₁ + r₂ = A; grazing emergence means r₂ = critical angle C, sin C = 1/μ.', 'hard', true, 2024, NULL, 'NEET UG 2024 (NTA) · answer verified by UG Prep', '/pyq/ug/2024/15.webp'),
('471b09c0-d52e-5ac1-8f7e-f5c3d9aa7542', 'neet_ug', 'Physics', 'Electric Charges and Fields', 'Given below are two statements: one is labelled as Assertion A and the other is labelled as Reason R.
Assertion A: The potential (V) at any axial point, at 2 m distance (r) from the centre of the dipole of dipole moment vector P⃗ of magnitude, 4×10⁻⁶ C m, is ±9×10³ V.
(Take 1/4πε₀ = 9×10⁹ SI units)
Reason R: V = ±2P/(4πε₀r²), where r is the distance of any axial point, situated at 2 m from the centre of the dipole.
In the light of the above statements, choose the correct answer from the options given below:', '[{"id": "a", "text": "A is true but R is false."}, {"id": "b", "text": "A is false but R is true."}, {"id": "c", "text": "Both A and R are true and R is the correct explanation of A."}, {"id": "d", "text": "Both A and R are true and R is NOT the correct explanation of A."}]'::jsonb, 'a', 'Axial potential of a short dipole is V = P/(4πε₀r²), with no factor of 2.', 'V = kP/r² = 9×10⁹ × 4×10⁻⁶ / 4 = 9×10³ V, sign depending on which side, so A is true. R puts a factor 2 in the formula, which belongs in the axial field (2kP/r³), not in the potential, so R is false.', '{"b": "A is numerically correct.", "c": "R''s formula would give 1.8×10⁴ V, so it cannot explain A.", "d": "R is not a true statement."}'::jsonb, 'Dipole: axial V = kp/r², equatorial V = 0; axial E = 2kp/r³, equatorial E = kp/r³.', 'med', true, 2024, NULL, 'NEET UG 2024 (NTA) · answer verified by UG Prep', NULL),
('9d19fee8-624d-5784-a108-6f0296bd569c', 'neet_ug', 'Physics', 'System of Particles and Rotational Motion', 'The moment of inertia of a thin rod about an axis passing through its mid point and perpendicular to the rod, is 2400 g cm². The length of the 400 g rod is nearly:', '[{"id": "a", "text": "20.7 cm"}, {"id": "b", "text": "72.0 cm"}, {"id": "c", "text": "8.5 cm"}, {"id": "d", "text": "17.5 cm"}]'::jsonb, 'c', 'Use I = ML²/12 and solve for L.', 'L² = 12I/M = 12 × 2400 / 400 = 72 cm², so L = √72 ≈ 8.5 cm.', '{"a": "Not from either the centre or the end formula.", "b": "This is L², not L.", "d": "Roughly twice the true value; mixes up formulas."}'::jsonb, 'Thin rod: I_centre = ML²/12, I_end = ML²/3.', 'easy', true, 2024, NULL, 'NEET UG 2024 (NTA) · answer verified by UG Prep', NULL),
('4d592b71-64aa-5339-86d4-32ff35cae917', 'neet_ug', 'Physics', 'Current Electricity', 'The terminal voltage of the battery, whose emf is 10 V and internal resistance 1 Ω, when connected through an external resistance of 4 Ω as shown in the figure is:', '[{"id": "a", "text": "8 V"}, {"id": "b", "text": "10 V"}, {"id": "c", "text": "4 V"}, {"id": "d", "text": "6 V"}]'::jsonb, 'a', 'Terminal voltage V = E − Ir.', 'I = E/(R + r) = 10/(4 + 1) = 2 A. V = E − Ir = 10 − 2 × 1 = 8 V (equivalently IR = 2 × 4 = 8 V).', '{"b": "That is the emf, valid only with no current.", "c": "Uses the wrong resistance.", "d": "Subtracts twice the internal drop."}'::jsonb, 'While a cell is discharging V = E − Ir; while charging V = E + Ir.', 'easy', true, 2024, NULL, 'NEET UG 2024 (NTA) · answer verified by UG Prep', '/pyq/ug/2024/18.webp'),
('fcc45383-5dba-5e4e-8478-6519f88f76dc', 'neet_ug', 'Physics', 'Atoms', 'Match the List-I with List-II.
List-I (Spectral Lines of Hydrogen for transitions from) | List-II (Wavelengths (nm))
(A) n₂ = 3 to n₁ = 2 | I. 410.2
(B) n₂ = 4 to n₁ = 2 | II. 434.1
(C) n₂ = 5 to n₁ = 2 | III. 656.3
(D) n₂ = 6 to n₁ = 2 | IV. 486.1
Choose the correct answer from the options given below:', '[{"id": "a", "text": "A-IV, B-III, C-I, D-II"}, {"id": "b", "text": "A-I, B-II, C-III, D-IV"}, {"id": "c", "text": "A-II, B-I, C-IV, D-III"}, {"id": "d", "text": "A-III, B-IV, C-II, D-I"}]'::jsonb, 'd', 'In the Balmer series a larger energy gap gives a shorter wavelength.', '3→2 has the smallest energy, so it is the longest line, Hα = 656.3 nm. Then 4→2 = 486.1 nm, 5→2 = 434.1 nm and 6→2 = 410.2 nm. The match is A-III, B-IV, C-II, D-I.', '{"a": "Not monotonic in wavelength.", "b": "Reverses the order: assigns the shortest λ to the smallest gap.", "c": "Random ordering."}'::jsonb, 'Balmer series lies in the visible region; Hα (3→2) = 656.3 nm is red.', 'easy', true, 2024, NULL, 'NEET UG 2024 (NTA) · answer verified by UG Prep', NULL),
('3cbb700c-e444-5c74-bf2e-fd2c6fd5ed61', 'neet_ug', 'Physics', 'Dual Nature of Radiation and Matter', 'If c is the velocity of light in free space, the correct statements about photon among the following are:
A. The energy of a photon is E = hν.
B. The velocity of a photon is c.
C. The momentum of a photon, p = hν/c.
D. In a photon-electron collision, both total energy and total momentum are conserved.
E. Photon possesses positive charge.
Choose the correct answer from the options given below:', '[{"id": "a", "text": "A, C and D only"}, {"id": "b", "text": "A, B, D and E only"}, {"id": "c", "text": "A and B only"}, {"id": "d", "text": "A, B, C and D only"}]'::jsonb, 'd', 'Photons have E = hν, speed c, p = hν/c, take part in conserving collisions, and are neutral.', 'A, B and C are the standard photon relations, and D holds because energy and momentum are conserved in photon–electron (Compton-type) collisions. E is false because photons are electrically neutral. So A, B, C and D.', '{"a": "Leaves out B, which is true.", "b": "Includes E, but photons carry no charge.", "c": "Leaves out the true statements C and D."}'::jsonb, 'Photons are neutral, have zero rest mass, and are not deflected by electric or magnetic fields.', 'easy', true, 2024, NULL, 'NEET UG 2024 (NTA) · answer verified by UG Prep', NULL),
('488055f8-7b70-54a3-b6ab-905f7b944451', 'neet_ug', 'Physics', 'Work, Energy and Power', 'At any instant of time t, the displacement of any particle is given by 2t − 1 (SI unit) under the influence of force of 5N. The value of instantaneous power is (in SI unit):', '[{"id": "a", "text": "7"}, {"id": "b", "text": "6"}, {"id": "c", "text": "10"}, {"id": "d", "text": "5"}]'::jsonb, 'c', 'Instantaneous power P = F·v with v = dx/dt.', 'v = d(2t − 1)/dt = 2 m s⁻¹. P = Fv = 5 × 2 = 10 W.', '{"a": "Adds F and v.", "b": "No consistent calculation gives 6.", "d": "Uses only the force."}'::jsonb, 'Power P = F·v; its SI unit is the watt (J s⁻¹).', 'easy', true, 2024, NULL, 'NEET UG 2024 (NTA) · answer verified by UG Prep', NULL),
('d4748750-7c75-5438-83d8-bed5b2f08cfd', 'neet_ug', 'Physics', 'Semiconductor Electronics: Materials, Devices and Simple Circuits', 'The output (Y) of the given logic gate is similar to the output of an/a:', '[{"id": "a", "text": "OR gate"}, {"id": "b", "text": "AND gate"}, {"id": "c", "text": "NAND gate"}, {"id": "d", "text": "NOR gate"}]'::jsonb, 'b', 'Inverting both inputs and then NOR-ing them gives AND (De Morgan).', 'The NAND gate with tied inputs gives Ā, and the NOR gate with tied inputs gives B̄. The final NOR gives Y = (Ā + B̄)′ = A·B by De Morgan''s theorem, which is an AND gate.', '{"a": "Would need NAND applied to inverted inputs.", "c": "NAND would need an OR of the inverted inputs without the final bubble.", "d": "NOR would need an AND of the inverted inputs."}'::jsonb, 'De Morgan: (A + B)′ = Ā·B̄ and (A·B)′ = Ā + B̄.', 'med', true, 2024, NULL, 'NEET UG 2024 (NTA) · answer verified by UG Prep', '/pyq/ug/2024/23.webp'),
('f3a36a19-6161-5bf5-9347-b98408c1342d', 'neet_ug', 'Physics', 'Gravitation', 'The mass of a planet is 1/10 th that of the earth and its diameter is half that of the earth. The acceleration due to gravity on that planet is:', '[{"id": "a", "text": "4.9 m s⁻²"}, {"id": "b", "text": "3.92 m s⁻²"}, {"id": "c", "text": "19.6 m s⁻²"}, {"id": "d", "text": "9.8 m s⁻²"}]'::jsonb, 'b', 'g ∝ M/R², so g′ = g × (1/10)/(1/2)².', 'g′/g = (M′/M)(R/R′)² = (1/10)(2)² = 0.4. g′ = 0.4 × 9.8 = 3.92 m s⁻².', '{"a": "Uses factor 1/2 instead of 0.4.", "c": "Twice g; inverts the mass ratio effect.", "d": "Ignores the change in M and R."}'::jsonb, 'g = GM/R²; for the same density, g ∝ R.', 'easy', true, 2024, NULL, 'NEET UG 2024 (NTA) · answer verified by UG Prep', NULL),
('1a42b862-ec95-5028-964e-4ede8b33f61f', 'neet_ug', 'Physics', 'Atoms', 'Given below are two statements:
Statement I: Atoms are electrically neutral as they contain equal number of positive and negative charges.
Statement II: Atoms of each element are stable and emit their characteristic spectrum.
In the light of the above statements, choose the most appropriate answer from the options given below:', '[{"id": "a", "text": "Statement I is correct but Statement II is incorrect."}, {"id": "b", "text": "Statement I is incorrect but Statement II is correct."}, {"id": "c", "text": "Both Statement I and Statement II are correct."}, {"id": "d", "text": "Both Statement I and Statement II are incorrect."}]'::jsonb, 'c', 'Both are basic facts that any atomic model must explain, as NCERT notes.', 'Atoms carry equal positive (nuclear) and negative (electronic) charge, so they are neutral. Atoms of each element are stable and, when excited, emit a line spectrum characteristic of that element. Both statements are correct.', '{"a": "Statement II is also a standard NCERT fact.", "b": "Statement I is plainly true.", "d": "Both are true."}'::jsonb, 'Each element has a unique line emission spectrum, used to identify it.', 'easy', true, 2024, NULL, 'NEET UG 2024 (NTA) · answer verified by UG Prep', NULL),
('98f59a1b-da52-5627-af5a-fb0255a392c4', 'neet_ug', 'Physics', 'System of Particles and Rotational Motion', 'A wheel of a bullock cart is rolling on a level road as shown in the figure below. If its linear speed is v in the direction shown, which one of the following options is correct (P and Q are any highest and lowest points on the wheel respectively)?', '[{"id": "a", "text": "Both the points P and Q move with equal speed."}, {"id": "b", "text": "Point P has zero speed."}, {"id": "c", "text": "Point P moves slower than point Q."}, {"id": "d", "text": "Point P moves faster than point Q."}]'::jsonb, 'd', 'In pure rolling the top moves at 2v and the contact point is at rest.', 'Velocity of a point = v_cm + ω × r. At the top P the two add, v + ωR = 2v; at the bottom Q they cancel, v − ωR = 0. So P moves faster than Q.', '{"a": "Speeds are 2v and 0, not equal.", "b": "It is the contact point Q that is momentarily at rest.", "c": "Reverses the true relation."}'::jsonb, 'Rolling without slipping: v_cm = ωR, v_top = 2v_cm, v_contact = 0.', 'easy', true, 2024, NULL, 'NEET UG 2024 (NTA) · answer verified by UG Prep', '/pyq/ug/2024/26.webp'),
('e2f3caea-ece6-5ae8-9356-e902708c94d1', 'neet_ug', 'Physics', 'Motion in a Plane', 'A particle moving with uniform speed in a circular path maintains:', '[{"id": "a", "text": "constant velocity but varying acceleration."}, {"id": "b", "text": "varying velocity and varying acceleration."}, {"id": "c", "text": "constant velocity."}, {"id": "d", "text": "constant acceleration."}]'::jsonb, 'b', 'In uniform circular motion both velocity and acceleration change direction continuously.', 'The speed is constant but the direction of velocity keeps changing, so velocity varies. The centripetal acceleration has constant magnitude v²/r but always points to the centre, so its direction, and hence the acceleration vector, also varies.', '{"a": "Velocity changes direction, so it is not constant.", "c": "Same error as (a).", "d": "Acceleration direction rotates, so it is not constant."}'::jsonb, 'Centripetal acceleration a = v²/r = ω²r, always directed toward the centre.', 'easy', true, 2024, NULL, 'NEET UG 2024 (NTA) · answer verified by UG Prep', NULL),
('a45c4a72-f808-58bf-9036-e2514a604f28', 'neet_ug', 'Physics', 'Mechanical Properties of Fluids', 'A thin flat circular disc of radius 4.5 cm is placed gently over the surface of water. If surface tension of water is 0.07 N m⁻¹, then the excess force required to take it away from the surface is:', '[{"id": "a", "text": "1.98 mN"}, {"id": "b", "text": "99 N"}, {"id": "c", "text": "19.8 mN"}, {"id": "d", "text": "198 N"}]'::jsonb, 'c', 'Surface tension acts along the disc''s rim: F = T × 2πr.', 'F = 2πrT = 2 × 3.14 × 0.045 × 0.07 ≈ 1.98×10⁻² N = 19.8 mN.', '{"a": "Ten times too small.", "b": "Wrong by orders of magnitude; cm not converted.", "d": "Wrong by orders of magnitude."}'::jsonb, 'Force due to surface tension = T × length of contact line.', 'med', true, 2024, NULL, 'NEET UG 2024 (NTA) · answer verified by UG Prep', NULL),
('07d1ecd6-168e-5036-8f0b-3b5b88378802', 'neet_ug', 'Physics', 'Magnetism and Matter', 'In a uniform magnetic field of 0.049 T, a magnetic needle performs 20 complete oscillations in 5 seconds as shown. The moment of inertia of the needle is 9.8 × 10⁻⁶ kg m². If the magnitude of magnetic moment of the needle is x × 10⁻⁵ A m², then the value of ''x'' is:', '[{"id": "a", "text": "50 π²"}, {"id": "b", "text": "1280 π²"}, {"id": "c", "text": "5 π²"}, {"id": "d", "text": "128 π²"}]'::jsonb, 'b', 'Use T = 2π√(I/mB) and solve for m.', 'T = 5/20 = 0.25 s. m = 4π²I/(T²B) = 4π² × 9.8×10⁻⁶ / (0.0625 × 0.049) = 4π² × 3.2×10⁻³ = 1.28×10⁻²π² = 1280π² × 10⁻⁵ A m². So x = 1280π².', '{"a": "Arithmetic error in T².", "c": "Off by a large factor.", "d": "Off by a factor of 10 in the power of ten."}'::jsonb, 'Oscillating magnetic dipole: T = 2π√(I/mB).', 'med', true, 2024, NULL, 'NEET UG 2024 (NTA) · answer verified by UG Prep', '/pyq/ug/2024/29.webp'),
('0e68e08d-e617-54a5-b434-7b8630f8a03d', 'neet_ug', 'Physics', 'Work, Energy and Power', 'Two bodies A and B of same mass undergo completely inelastic one dimensional collision. The body A moves with velocity v₁ while body B is at rest before collision. The velocity of the system after collision is v₂. The ratio v₁ : v₂ is:', '[{"id": "a", "text": "4 : 1"}, {"id": "b", "text": "1 : 4"}, {"id": "c", "text": "1 : 2"}, {"id": "d", "text": "2 : 1"}]'::jsonb, 'd', 'Momentum conservation with the masses stuck together: mv₁ = 2mv₂.', 'mv₁ + 0 = (m + m)v₂, so v₂ = v₁/2 and v₁ : v₂ = 2 : 1.', '{"a": "Squares the ratio, mixing in kinetic energy.", "b": "Inverted and squared.", "c": "Inverts the ratio."}'::jsonb, 'In a perfectly inelastic collision momentum is conserved but kinetic energy is not.', 'easy', true, 2024, NULL, 'NEET UG 2024 (NTA) · answer verified by UG Prep', NULL),
('04907248-271c-5319-a460-a5872f954ac2', 'neet_ug', 'Physics', 'Oscillations', 'If x = 5 sin(πt + π/3) m represents the motion of a particle executing simple harmonic motion, the amplitude and time period of motion, respectively, are:', '[{"id": "a", "text": "5 cm, 1 s"}, {"id": "b", "text": "5 m, 1 s"}, {"id": "c", "text": "5 cm, 2 s"}, {"id": "d", "text": "5 m, 2 s"}]'::jsonb, 'd', 'Compare with x = A sin(ωt + φ): A = 5 m, ω = π rad s⁻¹.', 'Amplitude A = 5 m (x is in metres). ω = π, so T = 2π/ω = 2 s.', '{"a": "Wrong unit and wrong period.", "b": "Period is 2π/π = 2 s, not 1 s.", "c": "The displacement is in metres, not cm."}'::jsonb, 'SHM: x = A sin(ωt + φ), T = 2π/ω.', 'easy', true, 2024, NULL, 'NEET UG 2024 (NTA) · answer verified by UG Prep', NULL),
('bd3aa727-e90c-5d68-8638-1ea0f844d547', 'neet_ug', 'Physics', 'Units and Measurements', 'The quantities which have the same dimensions as those of solid angle are:', '[{"id": "a", "text": "strain and arc"}, {"id": "b", "text": "angular speed and stress"}, {"id": "c", "text": "strain and angle"}, {"id": "d", "text": "stress and angle"}]'::jsonb, 'c', 'Solid angle is dimensionless, as are strain and plane angle.', 'Solid angle = area/r², a dimensionless ratio. Strain (ΔL/L) and plane angle (arc/radius) are also dimensionless, so they match.', '{"a": "Arc is a length, [L].", "b": "Angular speed is [T⁻¹], stress is [ML⁻¹T⁻²].", "d": "Stress has dimensions [ML⁻¹T⁻²]."}'::jsonb, 'Plane angle (radian) and solid angle (steradian) are dimensionless supplementary units.', 'easy', true, 2024, NULL, 'NEET UG 2024 (NTA) · answer verified by UG Prep', NULL),
('512b0c6b-015f-59fb-bb51-3def1816b5ce', 'neet_ug', 'Physics', 'Electrostatic Potential and Capacitance', 'A thin spherical shell is charged by some source. The potential difference between the two points C and P (in V) shown in the figure is:
(Take 1/4πε₀ = 9×10⁹ SI units)', '[{"id": "a", "text": "0.5 × 10⁵"}, {"id": "b", "text": "zero"}, {"id": "c", "text": "3 × 10⁵"}, {"id": "d", "text": "1 × 10⁵"}]'::jsonb, 'b', 'Inside and on a charged conducting shell the potential is the same everywhere.', 'The field inside a uniformly charged thin shell is zero, so the potential is constant from the centre C up to the surface, equal to kq/R. P lies on the shell, so V_C − V_P = 0.', '{"a": "Half of kq/R; no point here has that difference.", "c": "This is kq/R = 3×10⁵ V, the potential itself, not the difference.", "d": "No physical basis."}'::jsonb, 'For a charged spherical shell: E = 0 inside, V = kq/R throughout the inside.', 'easy', true, 2024, NULL, 'NEET UG 2024 (NTA) · answer verified by UG Prep', '/pyq/ug/2024/33.webp'),
('4edf3d7c-021d-5f05-8631-25203e768992', 'neet_ug', 'Physics', 'Laws of Motion', 'A bob is whirled in a horizontal plane by means of a string with an initial speed of ω rpm. The tension in the string is T. If speed becomes 2ω while keeping the same radius, the tension in the string becomes:', '[{"id": "a", "text": "T/4"}, {"id": "b", "text": "√2 T"}, {"id": "c", "text": "T"}, {"id": "d", "text": "4T"}]'::jsonb, 'd', 'Tension provides centripetal force mω²r, so it scales with ω².', 'T = mω²r. Doubling ω at the same r gives T′ = m(2ω)²r = 4T.', '{"a": "Inverts the dependence.", "b": "Uses a √ dependence.", "c": "Ignores the change in speed."}'::jsonb, 'Centripetal force F = mv²/r = mω²r.', 'easy', true, 2024, NULL, 'NEET UG 2024 (NTA) · answer verified by UG Prep', NULL),
('852e9bf2-72e5-5d59-8f8b-d344336d9ceb', 'neet_ug', 'Physics', 'Current Electricity', 'A wire of length ''l'' and resistance 100 Ω is divided into 10 equal parts. The first 5 parts are connected in series while the next 5 parts are connected in parallel. The two combinations are again connected in series. The resistance of this final combination is:', '[{"id": "a", "text": "55 Ω"}, {"id": "b", "text": "60 Ω"}, {"id": "c", "text": "26 Ω"}, {"id": "d", "text": "52 Ω"}]'::jsonb, 'd', 'Each piece is 10 Ω: 5 in series = 50 Ω, 5 in parallel = 2 Ω.', 'Each part has R = 100/10 = 10 Ω. Five in series give 50 Ω and five in parallel give 10/5 = 2 Ω. In series, 50 + 2 = 52 Ω.', '{"a": "Uses 5 Ω for the parallel set.", "b": "Uses 10 Ω for the parallel set.", "c": "Halves the series value."}'::jsonb, 'n equal resistors R: series nR, parallel R/n.', 'easy', true, 2024, NULL, 'NEET UG 2024 (NTA) · answer verified by UG Prep', NULL),
('8a820a95-f05e-5ed6-bf6f-e6769272ed3d', 'neet_ug', 'Physics', 'Thermal Properties of Matter', 'The following graph represents the T-V curves of an ideal gas (where T is the temperature and V the volume) at three pressures P₁, P₂ and P₃ compared with those of Charles''s law represented as dotted lines.', '[{"id": "a", "text": "P₂ > P₁ > P₃"}, {"id": "b", "text": "P₁ > P₂ > P₃"}, {"id": "c", "text": "P₃ > P₂ > P₁"}, {"id": "d", "text": "P₁ > P₃ > P₂"}]'::jsonb, 'b', 'At constant pressure T = (P/nR)V, so a steeper T–V line means a higher pressure.', 'For an ideal gas PV = nRT, so at fixed P the slope dT/dV = P/nR. The curve labelled P₁ is steepest, then P₂, then P₃, so P₁ > P₂ > P₃.', '{"a": "P₁ has the largest slope, so it cannot be below P₂.", "c": "Reverses the order of slopes.", "d": "P₃ is the least steep."}'::jsonb, 'Charles''s law: V ∝ T at constant P; the slope of V–T is nR/P.', 'med', true, 2024, NULL, 'NEET UG 2024 (NTA) · answer verified by UG Prep', '/pyq/ug/2024/36.webp'),
('f2152182-1491-5e4f-934f-ef9b01e34296', 'neet_ug', 'Physics', 'Electromagnetic Waves', 'A parallel plate capacitor is charged by connecting it to a battery through a resistor. If I is the current in the circuit, then in the gap between the plates:', '[{"id": "a", "text": "displacement current of magnitude equal to I flows in a direction opposite to that of I."}, {"id": "b", "text": "displacement current of magnitude greater than I flows but can be in any direction."}, {"id": "c", "text": "there is no current."}, {"id": "d", "text": "displacement current of magnitude equal to I flows in the same direction as I."}]'::jsonb, 'd', 'Displacement current in the gap equals the conduction current and continues it.', 'i_d = ε₀ dΦ_E/dt equals dq/dt = I, and it points the same way as the conduction current, so total current is continuous through the gap.', '{"a": "The direction matches I; it does not oppose it.", "b": "The magnitude equals I exactly.", "c": "There is no conduction current, but there is displacement current."}'::jsonb, 'Ampère–Maxwell law: ∮B·dl = μ₀(i_c + i_d), with i_d = ε₀ dΦ_E/dt.', 'easy', true, 2024, NULL, 'NEET UG 2024 (NTA) · answer verified by UG Prep', NULL),
('9dadd8c1-3542-5505-96dd-bf4f5a6a1981', 'neet_ug', 'Physics', 'Electromagnetic Waves', 'The property which is not of an electromagnetic wave travelling in free space is that:', '[{"id": "a", "text": "they travel with a speed equal to 1/√(μ₀ε₀)"}, {"id": "b", "text": "they originate from charges moving with uniform speed."}, {"id": "c", "text": "they are transverse in nature."}, {"id": "d", "text": "the energy density in electric field is equal to energy density in magnetic field."}]'::jsonb, 'b', 'EM waves are produced by accelerated charges, not by charges in uniform motion.', 'A charge moving at constant velocity produces steady fields only and does not radiate. EM waves come from accelerating or oscillating charges. The other three are true properties: speed c = 1/√(μ₀ε₀), transverse E and B, and equal electric and magnetic energy densities.', '{"a": "True: c = 1/√(μ₀ε₀) in vacuum.", "c": "True: E, B and the propagation direction are mutually perpendicular.", "d": "True: ½ε₀E² = B²/2μ₀ on average."}'::jsonb, 'Accelerated charges radiate EM waves; frequency of the wave equals frequency of oscillation of the charge.', 'easy', true, 2024, NULL, 'NEET UG 2024 (NTA) · answer verified by UG Prep', NULL),
('9f52ff6c-1a86-5e52-9bf9-ae24abc2504d', 'neet_ug', 'Physics', 'Electrostatic Potential and Capacitance', 'If the plates of a parallel plate capacitor connected to a battery are moved close to each other, then
A. the charge stored in it, increases.
B. the energy stored in it, decreases.
C. its capacitance increases.
D. the ratio of charge to its potential remains the same.
E. the product of charge and voltage increases.
Choose the most appropriate answer from the options given below:', '[{"id": "a", "text": "B, D and E only"}, {"id": "b", "text": "A, B and C only"}, {"id": "c", "text": "A, B and E only"}, {"id": "d", "text": "A, C and E only"}]'::jsonb, 'd', 'With V fixed, reducing d raises C = ε₀A/d, so Q = CV, U = ½CV² and QV all increase.', 'V is held by the battery. C = ε₀A/d increases (C true), so Q = CV increases (A true) and QV = CV² increases (E true). Energy ½CV² increases, so B is false, and Q/V = C changes, so D is false. Answer: A, C and E.', '{"a": "B and D are false at constant V.", "b": "B is false; energy increases.", "c": "B is false; energy increases."}'::jsonb, 'Battery connected → V constant; battery disconnected → Q constant.', 'med', true, 2024, NULL, 'NEET UG 2024 (NTA) · answer verified by UG Prep', NULL),
('4a43a53d-60cc-519e-a010-37f55376aed4', 'neet_ug', 'Physics', 'Units and Measurements', 'A force defined by F = αt² + βt acts on a particle at a given time t. The factor which is dimensionless, if α and β are constants, is:', '[{"id": "a", "text": "αβt"}, {"id": "b", "text": "αβ/t"}, {"id": "c", "text": "βt/α"}, {"id": "d", "text": "αt/β"}]'::jsonb, 'd', 'Terms added together share dimensions: [αt²] = [βt] gives [α t/β] = 1.', '[αt²] = [βt] gives [α]/[β] = [T⁻¹], so αt/β is dimensionless.', '{"a": "Has dimensions of force² × time⁻² etc., not dimensionless.", "b": "Not dimensionless.", "c": "βt/α has dimensions [T²]."}'::jsonb, 'Principle of homogeneity: only like dimensions can be added or subtracted.', 'easy', true, 2024, NULL, 'NEET UG 2024 (NTA) · answer verified by UG Prep', NULL),
('72dc1559-9756-5ac9-84f2-853de401cf93', 'neet_ug', 'Physics', 'Thermal Properties of Matter', 'A metallic bar of Young''s modulus, 0.5 × 10¹¹ N m⁻² and coefficient of linear thermal expansion 10⁻⁵ °C⁻¹ length 1 m and area of cross-section 10⁻³ m² is heated from 0°C to 100°C without expansion or bending. The compressive force developed in it is:', '[{"id": "a", "text": "100 × 10³ N"}, {"id": "b", "text": "2 × 10³ N"}, {"id": "c", "text": "52 × 10³ N"}, {"id": "d", "text": "50 × 10³ N"}]'::jsonb, 'd', 'Thermal stress = YαΔT, so force F = YAαΔT.', 'F = YAαΔT = 0.5×10¹¹ × 10⁻³ × 10⁻⁵ × 100 = 5×10⁴ N = 50 × 10³ N.', '{"a": "Twice the correct value.", "b": "Wrong by a factor of 25.", "c": "Arbitrary near-miss."}'::jsonb, 'Thermal stress in a clamped rod = YαΔT, independent of its length.', 'easy', true, 2024, NULL, 'NEET UG 2024 (NTA) · answer verified by UG Prep', NULL),
('76dc0f16-9d66-5590-8a64-2ce4bfdc5a2e', 'neet_ug', 'Physics', 'Ray Optics and Optical Instruments', 'A small telescope has an objective of focal length 140 cm and an eye piece of focal length 5.0 cm. The magnifying power of telescope for viewing a distant object is:', '[{"id": "a", "text": "17"}, {"id": "b", "text": "32"}, {"id": "c", "text": "34"}, {"id": "d", "text": "28"}]'::jsonb, 'd', 'Normal-adjustment magnifying power m = f₀/fₑ.', 'm = 140/5 = 28 for a distant object in normal adjustment.', '{"a": "No standard formula gives this.", "b": "No standard formula gives this.", "c": "Using f₀/fₑ(1 + fₑ/D) gives ≈ 33.6 for final image at near point; question says normal viewing of distant object."}'::jsonb, 'Astronomical telescope (normal adjustment): m = f₀/fₑ, tube length = f₀ + fₑ.', 'easy', true, 2024, NULL, 'NEET UG 2024 (NTA) · answer verified by UG Prep', NULL),
('44e0ea24-4eb0-5537-8064-4e4902ee6bbe', 'neet_ug', 'Physics', 'Magnetism and Matter', 'An iron bar of length L has magnetic moment M. It is bent at the middle of its length such that the two arms make an angle 60° with each other. The magnetic moment of this new magnet is:', '[{"id": "a", "text": "2 M"}, {"id": "b", "text": "M/√3"}, {"id": "c", "text": "M"}, {"id": "d", "text": "M/2"}]'::jsonb, 'd', 'Pole strength is unchanged; the effective length becomes the distance between the ends.', 'M = mL. After bending, arms of L/2 at 60° form an equilateral triangle, so the poles are L/2 apart. M′ = m(L/2) = M/2.', '{"a": "The moment cannot increase by bending.", "b": "Uses a wrong geometric factor.", "c": "Ignores the reduced separation of the poles."}'::jsonb, 'Magnetic moment = pole strength × effective (straight-line) length between poles.', 'med', true, 2024, NULL, 'NEET UG 2024 (NTA) · answer verified by UG Prep', NULL),
('448e0cff-2865-58ce-acd3-cfa3845a19ee', 'neet_ug', 'Physics', 'Alternating Current', 'A 10 μF capacitor is connected to a 210 V, 50 Hz source as shown in figure. The peak current in the circuit is nearly (π = 3.14):', '[{"id": "a", "text": "1.20 A"}, {"id": "b", "text": "0.35 A"}, {"id": "c", "text": "0.58 A"}, {"id": "d", "text": "0.93 A"}]'::jsonb, 'd', 'I₀ = √2 V_rms × ωC.', 'X_C = 1/(2πfC) = 1/(2 × 3.14 × 50 × 10⁻⁵) ≈ 318.5 Ω. I_rms = 210/318.5 ≈ 0.66 A, so I₀ = √2 × 0.66 ≈ 0.93 A.', '{"a": "Overestimates.", "b": "Too low.", "c": "No consistent calculation gives this."}'::jsonb, 'Capacitive reactance X_C = 1/ωC; current leads voltage by π/2.', 'med', true, 2024, NULL, 'NEET UG 2024 (NTA) · answer verified by UG Prep', '/pyq/ug/2024/45.webp'),
('c99bef38-6833-5ae8-9b76-71e32eaf491a', 'neet_ug', 'Physics', 'Current Electricity', 'Two heaters A and B have power rating of 1 kW and 2 kW, respectively. Those two are first connected in series and then in parallel to a fixed power source. The ratio of power outputs for these two cases is:', '[{"id": "a", "text": "1 : 2"}, {"id": "b", "text": "2 : 3"}, {"id": "c", "text": "1 : 1"}, {"id": "d", "text": "2 : 9"}]'::jsonb, 'd', 'Series: 1/P = 1/P₁ + 1/P₂; parallel: P = P₁ + P₂.', 'Series: P_s = (1 × 2)/(1 + 2) = 2/3 kW. Parallel: P_p = 1 + 2 = 3 kW. Ratio = (2/3)/3 = 2 : 9.', '{"a": "Just the ratio of ratings.", "b": "Ratio of series power to one heater.", "c": "Ignores the change in combination."}'::jsonb, 'At the same voltage, series power 1/P = Σ1/Pᵢ and parallel power P = ΣPᵢ.', 'med', true, 2024, NULL, 'NEET UG 2024 (NTA) · answer verified by UG Prep', NULL),
('20bb5791-2ded-5211-8647-0bc5eebd68ec', 'neet_ug', 'Physics', 'Motion in a Straight Line', 'The velocity (v) – time (t) plot of the motion of a body is shown below:
The acceleration (a) – time (t) graph that best suits this motion is:', '[{"id": "a", "text": "Option (1) in figure"}, {"id": "b", "text": "Option (2) in figure"}, {"id": "c", "text": "Option (3) in figure"}, {"id": "d", "text": "Option (4) in figure"}]'::jsonb, 'a', 'Slope of v–t gives a: positive constant, then zero, then negative constant.', 'The v–t plot rises linearly (constant positive a), stays flat (a = 0), then falls linearly (constant negative a). Graph (1) shows a positive step, zero, and a negative step.', '{"b": "Shows negative acceleration first and a rising ramp, unlike the motion.", "c": "This has the shape of v–t, not its slope.", "d": "Shows acceleration increasing and staying positive, which would keep v rising."}'::jsonb, 'Acceleration is the slope of v–t; displacement is the area under v–t.', 'easy', true, 2024, NULL, 'NEET UG 2024 (NTA) · answer verified by UG Prep', '/pyq/ug/2024/47.webp'),
('7d53e1d6-3fe4-56bf-a83d-31b727a1b8c5', 'neet_ug', 'Physics', 'Oscillations', 'If the mass of the bob in simple pendulum is increased to thrice its original mass and its length is made half its original length, then the new time period of oscillation is x/2 times its original time period. Then the value of x is:', '[{"id": "a", "text": "2√3"}, {"id": "b", "text": "4"}, {"id": "c", "text": "√3"}, {"id": "d", "text": "√2"}]'::jsonb, 'd', 'T = 2π√(l/g) is independent of mass.', 'Halving l gives T′ = T/√2 = (√2/2)T. So x/2 = √2/2 and x = √2.', '{"a": "Wrongly includes a mass dependence.", "b": "No basis.", "c": "Uses the mass factor √3 instead of the length factor."}'::jsonb, 'Simple pendulum T = 2π√(l/g), independent of the bob''s mass and of amplitude (small).', 'easy', true, 2024, NULL, 'NEET UG 2024 (NTA) · answer verified by UG Prep', NULL),
('d23afd47-988e-54cc-bd86-36eb3bd231a9', 'neet_ug', 'Physics', 'Gravitation', 'The minimum energy required to launch a satellite of mass m from the surface of earth of mass M and radius R in a circular orbit at an altitude of 2R from the surface of the earth is:', '[{"id": "a", "text": "GmM/2R"}, {"id": "b", "text": "GmM/3R"}, {"id": "c", "text": "5GmM/6R"}, {"id": "d", "text": "2GmM/3R"}]'::jsonb, 'c', 'Energy needed = orbital total energy − surface potential energy.', 'Orbit radius r = R + 2R = 3R, total energy there = −GMm/(2 × 3R) = −GMm/6R. Initial energy on the surface (ignoring rotation) = −GMm/R. Required energy = −GMm/6R + GMm/R = 5GMm/6R.', '{"a": "Not matched to r = 3R.", "b": "Only accounts for potential at 3R without kinetic energy correctly.", "d": "Change in potential energy only, ignoring the orbital kinetic energy."}'::jsonb, 'Orbital energy E = −GMm/2r; kinetic energy = GMm/2r.', 'med', true, 2024, NULL, 'NEET UG 2024 (NTA) · answer verified by UG Prep', NULL),
('f8cf70e5-463b-5c99-9814-dd0ad2b0cb5b', 'neet_ug', 'Physics', 'Electromagnetic Induction', 'A sheet is placed on a horizontal surface in front of a strong magnetic pole. A force is needed to:
A. hold the sheet there if it is magnetic.
B. hold the sheet there if it is non-magnetic.
C. move the sheet away from the pole with uniform velocity if it is conducting.
D. move the sheet away from the pole with uniform velocity if it is both, non-conducting and non-polar.
Choose the correct statement(s) from the options given below:', '[{"id": "a", "text": "A, C and D only"}, {"id": "b", "text": "C only"}, {"id": "c", "text": "B and D only"}, {"id": "d", "text": "A and C only"}]'::jsonb, 'd', 'A magnetic sheet is attracted, and a moving conductor feels an eddy-current drag.', 'A magnetic sheet is pulled toward the pole, so a force is needed to hold it (A). A non-magnetic sheet feels no such pull (B false). Moving a conducting sheet through the non-uniform field induces eddy currents that oppose the motion, so a force is needed even at uniform velocity (C). A non-conducting, non-polar sheet has neither effect (D false).', '{"a": "D is false; such a sheet experiences no magnetic or eddy force.", "b": "Misses A, since a magnetic sheet is attracted.", "c": "B and D are both false."}'::jsonb, 'Eddy currents oppose relative motion (Lenz''s law): basis of magnetic braking and damping.', 'med', true, 2024, NULL, 'NEET UG 2024 (NTA) · answer verified by UG Prep', NULL),
('ee97b685-f9fb-5c26-8dd2-b2004b9b31c2', 'neet_ug', 'Chemistry', 'Electrochemistry', 'Match List-I with List-II.
List-I (Conversion) | List-II (Number of Faraday required)
(A) 1 mol of H₂O to O₂ | (I) 3F
(B) 1 mol of MnO₄⁻ to Mn²⁺ | (II) 2F
(C) 1.5 mol of Ca from molten CaCl₂ | (III) 1F
(D) 1 mol of FeO to Fe₂O₃ | (IV) 5F
Choose the correct answer from the options given below:', '[{"id": "a", "text": "A-II, B-III, C-I, D-IV"}, {"id": "b", "text": "A-III, B-IV, C-II, D-I"}, {"id": "c", "text": "A-II, B-IV, C-I, D-III"}, {"id": "d", "text": "A-III, B-IV, C-I, D-II"}]'::jsonb, 'c', 'Faradays needed equal moles of electrons transferred: 2, 5, 3 and 1 respectively.', 'H₂O → ½O₂ + 2H⁺ + 2e⁻, so 1 mol H₂O needs 2F. MnO₄⁻ (Mn +7) → Mn²⁺ needs 5e⁻, so 5F. Ca²⁺ + 2e⁻ → Ca, so 1.5 mol Ca needs 3F. Fe²⁺ → Fe³⁺ is a 1e⁻ change per Fe, so 1 mol FeO needs 1F.', '{"a": "Gives MnO₄⁻ 1F and FeO 5F, ignoring the 5-electron change of Mn(+7→+2).", "b": "Treats oxidation of water as a 1e⁻ process and Ca deposition as 2F.", "d": "Assigns 1F to water oxidation and 2F to FeO, both wrong."}'::jsonb, 'Charge needed = n × F, where n is the moles of electrons transferred (1F = 96487 C).', 'med', true, 2024, NULL, 'NEET UG 2024 (NTA) · answer verified by UG Prep', NULL),
('7318bea6-dcfd-5997-94b3-459239347034', 'neet_ug', 'Chemistry', 'Redox Reactions', 'Which reaction is NOT a redox reaction?', '[{"id": "a", "text": "H₂ + Cl₂ → 2HCl"}, {"id": "b", "text": "BaCl₂ + Na₂SO₄ → BaSO₄ + 2NaCl"}, {"id": "c", "text": "Zn + CuSO₄ → ZnSO₄ + Cu"}, {"id": "d", "text": "2KClO₃ + I₂ → 2KIO₃ + Cl₂"}]'::jsonb, 'b', 'Precipitation of BaSO₄ is a double displacement with no change in oxidation states.', 'In BaCl₂ + Na₂SO₄ every element keeps its oxidation state (Ba +2, S +6, Na +1, Cl −1); ions only swap partners. The other three each involve electron transfer.', '{"a": "H goes 0→+1 and Cl 0→−1: a redox combination.", "c": "Zn 0→+2 and Cu +2→0: a redox displacement.", "d": "I 0→+5 and Cl +5→0: a redox displacement."}'::jsonb, 'Double decomposition (metathesis) reactions are not redox reactions.', 'easy', true, 2024, NULL, 'NEET UG 2024 (NTA) · answer verified by UG Prep', NULL),
('906015cd-efe7-5714-ab9b-1cd2082498cb', 'neet_ug', 'Chemistry', 'Chemical Bonding and Molecular Structure', 'Intramolecular hydrogen bonding is present in', '[{"id": "a", "text": "Option (1) in figure"}, {"id": "b", "text": "HF"}, {"id": "c", "text": "Option (3) in figure"}, {"id": "d", "text": "Option (4) in figure"}]'::jsonb, 'c', 'o-Nitrophenol has –OH and –NO₂ adjacent, allowing an H-bond within the same molecule.', 'Intramolecular H-bonding needs the donor (–OH) and acceptor (–NO₂ oxygen) close enough to form a six-membered chelate ring, which is possible only in the ortho isomer (option 3). In m- and p-nitrophenol the groups are too far apart, so they H-bond between molecules.', '{"a": "m-Nitrophenol: groups too far apart, only intermolecular H-bonding.", "b": "HF forms intermolecular H-bonded zig-zag chains.", "d": "p-Nitrophenol: only intermolecular H-bonding."}'::jsonb, 'o-Nitrophenol is steam volatile because of intramolecular H-bonding; the p-isomer is not.', 'easy', true, 2024, NULL, 'NEET UG 2024 (NTA) · answer verified by UG Prep', '/pyq/ug/2024/53.webp'),
('27369064-a10a-5ceb-8c88-e1b153537fb0', 'neet_ug', 'Chemistry', 'Aldehydes, Ketones and Carboxylic Acids', 'Fehling''s solution ''A'' is', '[{"id": "a", "text": "alkaline solution of sodium potassium tartrate (Rochelle''s salt)"}, {"id": "b", "text": "aqueous sodium citrate"}, {"id": "c", "text": "aqueous copper sulphate"}, {"id": "d", "text": "alkaline copper sulphate"}]'::jsonb, 'c', 'Fehling''s A is aqueous CuSO₄; Fehling''s B is alkaline Rochelle salt.', 'Fehling''s reagent is made just before use by mixing Fehling A (aqueous copper sulphate) with Fehling B (alkaline sodium potassium tartrate). The tartrate complexes Cu²⁺ so it does not precipitate as Cu(OH)₂ in alkali.', '{"a": "This is Fehling''s solution B.", "b": "Sodium citrate is used in Benedict''s reagent.", "d": "Copper sulphate is not made alkaline in solution A; alkali is in solution B."}'::jsonb, 'Aldehydes reduce Fehling''s reagent to a red-brown precipitate of Cu₂O.', 'easy', true, 2024, NULL, 'NEET UG 2024 (NTA) · answer verified by UG Prep', NULL),
('c556446d-b2d7-5443-ac91-90a69995ed9a', 'neet_ug', 'Chemistry', 'Some Basic Concepts of Chemistry', '1 gram of sodium hydroxide was treated with 25 mL of 0.75 M HCl solution, the mass of sodium hydroxide left unreacted is equal to', '[{"id": "a", "text": "Zero mg"}, {"id": "b", "text": "200 mg"}, {"id": "c", "text": "750 mg"}, {"id": "d", "text": "250 mg"}]'::jsonb, 'd', 'NaOH is in excess by 0.00625 mol, i.e. 250 mg.', 'n(NaOH) = 1/40 = 0.025 mol; n(HCl) = 0.025 L × 0.75 M = 0.01875 mol. They react 1:1, so NaOH left = 0.025 − 0.01875 = 0.00625 mol = 0.00625 × 40 = 0.25 g = 250 mg.', '{"a": "HCl is the limiting reagent, so some NaOH remains.", "b": "Arithmetic slip; 0.005 mol would be needed.", "c": "0.75 g is the mass that reacted, not the mass left."}'::jsonb, 'In a limiting-reagent problem, excess left = moles of excess reagent − moles consumed.', 'easy', true, 2024, NULL, 'NEET UG 2024 (NTA) · answer verified by UG Prep', NULL),
('30d14945-e8fe-54a1-bf09-d479c872969d', 'neet_ug', 'Chemistry', 'Chemical Bonding and Molecular Structure', 'Match List-I with List-II.
List-I (Compound) | List-II (Shape/geometry)
(A) NH₃ | (I) Trigonal Pyramidal
(B) BrF₅ | (II) Square Planar
(C) XeF₄ | (III) Octahedral
(D) SF₆ | (IV) Square Pyramidal
Choose the correct answer from the options given below:', '[{"id": "a", "text": "A-III, B-IV, C-I, D-II"}, {"id": "b", "text": "A-II, B-III, C-IV, D-I"}, {"id": "c", "text": "A-I, B-IV, C-II, D-III"}, {"id": "d", "text": "A-II, B-IV, C-III, D-I"}]'::jsonb, 'c', 'VSEPR: NH₃ pyramidal, BrF₅ square pyramidal, XeF₄ square planar, SF₆ octahedral.', 'NH₃ has 3 bp + 1 lp (trigonal pyramidal). BrF₅ has 5 bp + 1 lp around Br (square pyramidal). XeF₄ has 4 bp + 2 lp placed trans (square planar). SF₆ has 6 bp and no lone pair (octahedral).', '{"a": "Calls NH₃ octahedral and SF₆ square planar.", "b": "Calls NH₃ square planar.", "d": "Calls XeF₄ octahedral; its two lone pairs make it square planar."}'::jsonb, 'AB₄E₂ is square planar and AB₅E is square pyramidal.', 'easy', true, 2024, NULL, 'NEET UG 2024 (NTA) · answer verified by UG Prep', NULL),
('8e622d44-deba-5a25-b738-30946a8c21ab', 'neet_ug', 'Chemistry', 'The d- and f-Block Elements', 'The E° value for the Mn³⁺/Mn²⁺ couple is more positive than that of Cr³⁺/Cr²⁺ or Fe³⁺/Fe²⁺ due to change of', '[{"id": "a", "text": "d⁴ to d⁵ configuration"}, {"id": "b", "text": "d³ to d⁵ configuration"}, {"id": "c", "text": "d⁵ to d⁴ configuration"}, {"id": "d", "text": "d⁵ to d² configuration"}]'::jsonb, 'a', 'Reducing Mn³⁺ (d⁴) gives the extra-stable half-filled d⁵ Mn²⁺.', 'Mn³⁺ is 3d⁴ and Mn²⁺ is 3d⁵. Gaining an electron gives a half-filled d⁵ shell with high exchange energy, so Mn³⁺ is easily reduced and E°(Mn³⁺/Mn²⁺) is large and positive (about +1.57 V).', '{"b": "No d³ ion is involved; Cr³⁺ → Cr²⁺ is d³ → d⁴.", "c": "That is the reverse (oxidation) of the couple.", "d": "No such configuration change occurs."}'::jsonb, 'Mn²⁺ (d⁵) and Fe³⁺ (d⁵) are especially stable because of their half-filled d subshell.', 'easy', true, 2024, NULL, 'NEET UG 2024 (NTA) · answer verified by UG Prep', NULL),
('ea88bc27-067a-5c51-b248-40ff8bac7b06', 'neet_ug', 'Chemistry', 'Thermodynamics', 'Match List-I with List-II.
List-I (Process) | List-II (Conditions)
(A) Isothermal process | (I) No heat exchange
(B) Isochoric process | (II) Carried out at constant temperature
(C) Isobaric process | (III) Carried out at constant volume
(D) Adiabatic process | (IV) Carried out at constant pressure
Choose the correct answer from the options given below:', '[{"id": "a", "text": "A-I, B-II, C-III, D-IV"}, {"id": "b", "text": "A-II, B-III, C-IV, D-I"}, {"id": "c", "text": "A-IV, B-III, C-II, D-I"}, {"id": "d", "text": "A-IV, B-II, C-III, D-I"}]'::jsonb, 'b', 'Isothermal = constant T, isochoric = constant V, isobaric = constant P, adiabatic = q = 0.', 'The prefixes give the meaning: iso-thermal (same temperature), iso-choric (same volume), iso-baric (same pressure). An adiabatic process allows no heat exchange with the surroundings (q = 0).', '{"a": "Swaps isothermal with adiabatic and mislabels the rest.", "c": "Calls isothermal constant pressure and isobaric constant temperature.", "d": "Calls isothermal constant pressure and isochoric constant temperature."}'::jsonb, 'For an adiabatic process ΔU = w, and for an isochoric process ΔU = q_v.', 'easy', true, 2024, NULL, 'NEET UG 2024 (NTA) · answer verified by UG Prep', NULL),
('1c0b69d9-cb3a-5d4a-b120-e01a3438d78d', 'neet_ug', 'Chemistry', 'Chemical Kinetics', 'Activation energy of any chemical reaction can be calculated if one knows the value of', '[{"id": "a", "text": "orientation of reactant molecules during collision."}, {"id": "b", "text": "rate constant at two different temperatures."}, {"id": "c", "text": "rate constant at standard temperature."}, {"id": "d", "text": "probability of collision."}]'::jsonb, 'b', 'The two-temperature Arrhenius equation gives Eₐ from k₁ and k₂.', 'log(k₂/k₁) = (Eₐ/2.303R)(1/T₁ − 1/T₂). Knowing k at two temperatures gives Eₐ directly. A single k value is not enough, because A is also unknown.', '{"a": "Orientation affects the steric factor, not Eₐ.", "c": "One rate constant leaves both A and Eₐ unknown.", "d": "Collision probability relates to Z/A, not to Eₐ."}'::jsonb, 'A plot of ln k vs 1/T has slope −Eₐ/R.', 'easy', true, 2024, NULL, 'NEET UG 2024 (NTA) · answer verified by UG Prep', NULL),
('0697e3bf-0616-5131-823e-2a51df59b3f4', 'neet_ug', 'Chemistry', 'Organic Chemistry – Some Basic Principles and Techniques', 'A compound with a molecular formula of C₆H₁₄ has two tertiary carbons. Its IUPAC name is:', '[{"id": "a", "text": "2,3-dimethylbutane"}, {"id": "b", "text": "2,2-dimethylbutane"}, {"id": "c", "text": "n-hexane"}, {"id": "d", "text": "2-methylpentane"}]'::jsonb, 'a', '(CH₃)₂CH–CH(CH₃)₂ has two CH carbons, each bonded to three carbons.', 'A tertiary carbon is bonded to three other carbons. In 2,3-dimethylbutane, C-2 and C-3 are both tertiary. 2,2-Dimethylbutane has one quaternary carbon, 2-methylpentane has one tertiary carbon, and n-hexane has none.', '{"b": "Has a quaternary C-2 and no tertiary carbon.", "c": "Straight chain: only primary and secondary carbons.", "d": "Only C-2 is tertiary."}'::jsonb, '1°, 2°, 3° and 4° carbons are bonded to 1, 2, 3 and 4 other carbons.', 'easy', true, 2024, NULL, 'NEET UG 2024 (NTA) · answer verified by UG Prep', NULL),
('544e9c05-aa36-5fad-b2cc-04630bcebe82', 'neet_ug', 'Chemistry', 'The d- and f-Block Elements', '''Spin only'' magnetic moment is same for which of the following ions?
A. Ti³⁺
B. Cr²⁺
C. Mn²⁺
D. Fe²⁺
E. Sc³⁺
Choose the most appropriate answer from the options given below:', '[{"id": "a", "text": "B and C only"}, {"id": "b", "text": "A and D only"}, {"id": "c", "text": "B and D only"}, {"id": "d", "text": "A and E only"}]'::jsonb, 'c', 'Cr²⁺ (d⁴) and Fe²⁺ (d⁶) both have 4 unpaired electrons, so μ = 4.90 BM.', 'Unpaired electrons: Ti³⁺ d¹ (1), Cr²⁺ d⁴ (4), Mn²⁺ d⁵ (5), Fe²⁺ d⁶ (4), Sc³⁺ d⁰ (0). μ = √(n(n+2)), so Cr²⁺ and Fe²⁺ share √24 ≈ 4.90 BM.', '{"a": "Cr²⁺ has 4 and Mn²⁺ has 5 unpaired electrons.", "b": "Ti³⁺ has 1 and Fe²⁺ has 4.", "d": "Ti³⁺ has 1 and Sc³⁺ has 0."}'::jsonb, 'Spin-only μ = √(n(n+2)) BM; d⁴ and d⁶ (high spin) both give 4.90 BM.', 'easy', true, 2024, NULL, 'NEET UG 2024 (NTA) · answer verified by UG Prep', NULL),
('869a33c9-a475-59d2-80dd-bf409b25f017', 'neet_ug', 'Chemistry', 'Classification of Elements and Periodicity in Properties', 'Arrange the following elements in increasing order of electronegativity:
N, O, F, C, Si
Choose the correct answer from the options given below:', '[{"id": "a", "text": "O < F < N < C < Si"}, {"id": "b", "text": "F < O < N < C < Si"}, {"id": "c", "text": "Si < C < N < O < F"}, {"id": "d", "text": "Si < C < O < N < F"}]'::jsonb, 'c', 'EN rises across a period (C < N < O < F) and falls down a group (Si < C).', 'Pauling values: Si 1.8, C 2.5, N 3.0, O 3.5, F 4.0. So Si < C < N < O < F.', '{"a": "Places O and F below Si, which is reversed.", "b": "Fully reversed order.", "d": "Swaps N and O; O is more electronegative than N."}'::jsonb, 'Fluorine is the most electronegative element (4.0 on the Pauling scale).', 'easy', true, 2024, NULL, 'NEET UG 2024 (NTA) · answer verified by UG Prep', NULL),
('7a4c94ba-6adc-5dc8-a9dd-2c33cddb6389', 'neet_ug', 'Chemistry', 'Alcohols, Phenols and Ethers', 'Which one of the following alcohols reacts instantaneously with Lucas reagent?', '[{"id": "a", "text": "CH₃–CH(CH₃)–CH₂OH"}, {"id": "b", "text": "(CH₃)₃C–OH"}, {"id": "c", "text": "CH₃–CH₂–CH₂–CH₂OH"}, {"id": "d", "text": "CH₃–CH₂–CH(CH₃)–OH"}]'::jsonb, 'b', 'Tertiary alcohols turn Lucas reagent turbid at once because they form a stable 3° carbocation.', 'Lucas reagent (conc. HCl + anhydrous ZnCl₂) reacts by an SN1-type path. tert-Butyl alcohol gives a 3° carbocation at once, so turbidity appears immediately. Secondary alcohols take about 5 minutes, and primary alcohols show no turbidity at room temperature.', '{"a": "Isobutyl alcohol is primary, so no turbidity forms at room temperature.", "c": "n-Butanol is primary, so it gives no immediate turbidity.", "d": "Butan-2-ol is secondary, so turbidity appears only after a few minutes."}'::jsonb, 'Lucas test order of reactivity: 3° > 2° > 1° alcohols.', 'easy', true, 2024, NULL, 'NEET UG 2024 (NTA) · answer verified by UG Prep', NULL),
('95add95c-c3d2-51b9-8630-459ba7a2fb58', 'neet_ug', 'Chemistry', 'Coordination Compounds', 'Given below are two statements:
Statement I: Both [Co(NH₃)₆]³⁺ and [CoF₆]³⁻ complexes are octahedral but differ in their magnetic behaviour.
Statement II: [Co(NH₃)₆]³⁺ is diamagnetic whereas [CoF₆]³⁻ is paramagnetic.
In the light of the above statements, choose the correct answer from the options given below:', '[{"id": "a", "text": "Statement I is true but Statement II is false."}, {"id": "b", "text": "Statement I is false but Statement II is true."}, {"id": "c", "text": "Both Statement I and Statement II are true."}, {"id": "d", "text": "Both Statement I and Statement II are false."}]'::jsonb, 'c', 'Co³⁺ (d⁶) is low spin with NH₃ (diamagnetic) and high spin with F⁻ (paramagnetic).', 'Both are octahedral Co³⁺ (3d⁶) complexes. NH₃ is a strong-field ligand: t₂g⁶ with d²sp³ (inner orbital) hybridisation and no unpaired electrons. F⁻ is weak-field: t₂g⁴e_g² with sp³d² (outer orbital) hybridisation and 4 unpaired electrons. So both statements are true.', '{"a": "Statement II is also true.", "b": "Statement I is true: both are octahedral and differ magnetically.", "d": "Both statements are correct."}'::jsonb, '[CoF₆]³⁻ is an outer-orbital high-spin complex; [Co(NH₃)₆]³⁺ is inner-orbital low spin.', 'easy', true, 2024, NULL, 'NEET UG 2024 (NTA) · answer verified by UG Prep', NULL),
('1feec087-f6af-5817-b24a-766568b3c9d1', 'neet_ug', 'Chemistry', 'The p-Block Elements', 'Given below are two statements:
Statement I: The boiling point of hydrides of Group 16 elements follow the order H₂O > H₂Te > H₂Se > H₂S.
Statement II: On the basis of molecular mass, H₂O is expected to have lower boiling point than the other members of the group but due to the presence of extensive H-bonding in H₂O, it has higher boiling point.
In the light of the above statements, choose the correct answer from the options given below:', '[{"id": "a", "text": "Statement I is true but Statement II is false."}, {"id": "b", "text": "Statement I is false but Statement II is true."}, {"id": "c", "text": "Both Statement I and Statement II are true."}, {"id": "d", "text": "Both Statement I and Statement II are false."}]'::jsonb, 'c', 'Water''s H-bonding raises its boiling point above the trend set by molar mass.', 'Boiling points: H₂O 373 K > H₂Te 271 K > H₂Se 232 K > H₂S 213 K, so Statement I holds. From H₂S to H₂Te the boiling point rises with molar mass (stronger van der Waals forces). H₂O should be lowest by mass, but extensive hydrogen bonding makes it highest, so Statement II holds.', '{"a": "Statement II correctly explains the anomaly.", "b": "Statement I''s order is correct.", "d": "Both statements are correct."}'::jsonb, 'Volatility order of Group 16 hydrides: H₂S > H₂Se > H₂Te > H₂O.', 'easy', true, 2024, NULL, 'NEET UG 2024 (NTA) · answer verified by UG Prep', NULL),
('16d5ed6a-6421-51cd-b70d-680ea4738ef4', 'neet_ug', 'Chemistry', 'Structure of Atom', 'Match List I with List II.
List I (Quantum Number) | List II (Information provided)
(A) mₗ | (I) shape of orbital
(B) mₛ | (II) size of orbital
(C) l | (III) orientation of orbital
(D) n | (IV) orientation of spin of electron
Choose the correct answer from the options given below:', '[{"id": "a", "text": "A-III, B-IV, C-II, D-I"}, {"id": "b", "text": "A-II, B-I, C-IV, D-III"}, {"id": "c", "text": "A-I, B-III, C-II, D-IV"}, {"id": "d", "text": "A-III, B-IV, C-I, D-II"}]'::jsonb, 'd', 'n gives size, l gives shape, mₗ gives orientation, and mₛ gives spin orientation.', 'The principal quantum number n fixes the shell, and so the orbital''s size and energy. The azimuthal number l fixes the subshell shape (s, p, d…). The magnetic number mₗ gives the orbital''s spatial orientation, and mₛ (±½) gives the orientation of electron spin.', '{"a": "Swaps l and n: l gives shape, not size.", "b": "Wrong for all four.", "c": "Gives mₗ as shape and n as spin."}'::jsonb, 'The number of orbitals in a subshell is 2l + 1, the number of allowed mₗ values.', 'easy', true, 2024, NULL, 'NEET UG 2024 (NTA) · answer verified by UG Prep', NULL),
('3bbcbd71-c480-5827-991d-5826be3037ab', 'neet_ug', 'Chemistry', 'Aldehydes, Ketones and Carboxylic Acids', 'Match List I with List II.
List I (Reaction) | List II (Reagents/Condition)
(A) Cyclohexylidenecyclohexane → 2 cyclohexanone | (I) Benzoyl chloride (C₆H₅COCl)/anhyd. AlCl₃
(B) Benzene → benzophenone | (II) CrO₃
(C) Cyclohexanol → cyclohexanone | (III) KMnO₄/KOH, Δ
(D) Ethylbenzene → potassium benzoate | (IV) (i) O₃ (ii) Zn-H₂O
Choose the correct answer from the options given below:', '[{"id": "a", "text": "A-IV, B-I, C-II, D-III"}, {"id": "b", "text": "A-I, B-IV, C-II, D-III"}, {"id": "c", "text": "A-IV, B-I, C-III, D-II"}, {"id": "d", "text": "A-III, B-I, C-II, D-IV"}]'::jsonb, 'a', 'Ozonolysis cleaves the C=C, FC acylation gives benzophenone, CrO₃ oxidises 2° alcohol, and hot alkaline KMnO₄ oxidises the side chain.', 'A: reductive ozonolysis (O₃ then Zn/H₂O) splits the tetrasubstituted alkene into two cyclohexanones. B: Friedel–Crafts acylation of benzene with C₆H₅COCl/AlCl₃ gives benzophenone. C: CrO₃ oxidises a secondary alcohol to a ketone. D: hot KMnO₄/KOH oxidises the whole ethyl side chain to –COOK.', '{"b": "Benzoyl chloride cannot cleave an alkene, and ozonolysis does not acylate benzene.", "c": "KMnO₄/KOH on ethylbenzene gives benzoate, and CrO₃ is not used for side-chain oxidation here.", "d": "KMnO₄/KOH, Δ would not give just two ketones cleanly; ozonolysis is the expected reagent for A."}'::jsonb, 'Any alkyl side chain with a benzylic H is oxidised to –COOH by hot alkaline KMnO₄.', 'med', true, 2024, NULL, 'NEET UG 2024 (NTA) · answer verified by UG Prep', '/pyq/ug/2024/67.webp'),
('5ee701fb-4db1-5c70-9314-708b47244788', 'neet_ug', 'Chemistry', 'Aldehydes, Ketones and Carboxylic Acids', 'Identify the correct reagents that would bring about the following transformation.
C₆H₁₁–CH₂–CH=CH₂ → C₆H₁₁–CH₂–CH₂–CHO (C₆H₁₁ = cyclohexyl)', '[{"id": "a", "text": "(i) BH₃ (ii) H₂O₂/OH⁻ (iii) alk. KMnO₄ (iv) H₃O⁺"}, {"id": "b", "text": "(i) H₂O/H⁺ (ii) PCC"}, {"id": "c", "text": "(i) H₂O/H⁺ (ii) CrO₃"}, {"id": "d", "text": "(i) BH₃ (ii) H₂O₂/OH⁻ (iii) PCC"}]'::jsonb, 'd', 'Hydroboration–oxidation gives the anti-Markovnikov 1° alcohol, and PCC stops oxidation at the aldehyde.', 'BH₃ then H₂O₂/OH⁻ adds water anti-Markovnikov to give C₆H₁₁CH₂CH₂CH₂OH. PCC is a mild oxidant that converts a primary alcohol to the aldehyde C₆H₁₁CH₂CH₂CHO without over-oxidation.', '{"a": "Alkaline KMnO₄ oxidises the 1° alcohol all the way to the carboxylic acid.", "b": "Acid-catalysed hydration is Markovnikov and gives a 2° alcohol, which PCC turns into a ketone.", "c": "Markovnikov hydration then CrO₃ gives a ketone, not the aldehyde."}'::jsonb, 'Hydroboration–oxidation adds H₂O anti-Markovnikov with no carbocation rearrangement.', 'med', true, 2024, NULL, 'NEET UG 2024 (NTA) · answer verified by UG Prep', NULL),
('bbf32c15-6d34-5b5c-a8b9-0b453f0516ff', 'neet_ug', 'Chemistry', 'Biomolecules', 'The reagents with which glucose does not react to give the corresponding tests/products are
A. Tollen''s reagent
B. Schiff''s reagent
C. HCN
D. NH₂OH
E. NaHSO₃
Choose the correct options from the given below:', '[{"id": "a", "text": "B and E"}, {"id": "b", "text": "E and D"}, {"id": "c", "text": "B and C"}, {"id": "d", "text": "A and D"}]'::jsonb, 'a', 'Glucose fails the Schiff''s test and forms no NaHSO₃ adduct because its –CHO is mostly tied up in the cyclic hemiacetal.', 'Glucose mainly exists as cyclic α/β-pyranose forms, so it gives no Schiff''s test and no bisulphite addition product. These failures were evidence for the ring structure. It still reduces Tollens'' reagent and forms an oxime with NH₂OH and a cyanohydrin with HCN.', '{"b": "Glucose does form an oxime with NH₂OH.", "c": "Glucose does form a cyanohydrin with HCN.", "d": "Glucose reduces Tollens'' reagent and reacts with NH₂OH."}'::jsonb, 'Glucose pentaacetate does not react with NH₂OH, which shows that no free –CHO is present.', 'med', true, 2024, NULL, 'NEET UG 2024 (NTA) · answer verified by UG Prep', NULL),
('3ddb7dc0-34b6-52d7-af6a-ca5f17e902c9', 'neet_ug', 'Chemistry', 'Chemical Bonding and Molecular Structure', 'Match List I with List II.
List-I (Molecule) | List-II (Number and types of bond/s between two carbon atoms)
(A) ethane | (I) one σ-bond and two π-bonds
(B) ethene | (II) two π-bonds
(C) carbon molecule, C₂ | (III) one σ-bond
(D) ethyne | (IV) one σ-bond and one π-bond
Choose the correct answer from the options given below:', '[{"id": "a", "text": "A-III, B-IV, C-II, D-I"}, {"id": "b", "text": "A-III, B-IV, C-I, D-II"}, {"id": "c", "text": "A-I, B-IV, C-II, D-III"}, {"id": "d", "text": "A-IV, B-III, C-II, D-I"}]'::jsonb, 'a', 'C–C is σ, C=C is σ+π, C≡C is σ+2π, and C₂ by MO theory has two π bonds.', 'Ethane has a single σ C–C bond, ethene has σ + π, and ethyne has σ + 2π. In C₂ (12 electrons) the MO configuration ends at (π2p_x)²(π2p_y)² with σ2p_z empty, so its bond order of 2 comes from two π bonds.', '{"b": "Swaps C₂ and ethyne.", "c": "Gives ethane a triple bond.", "d": "Gives ethane a double and ethene a single bond."}'::jsonb, 'C₂ is unusual: both its bonds are π bonds, according to MO theory.', 'med', true, 2024, NULL, 'NEET UG 2024 (NTA) · answer verified by UG Prep', NULL),
('ba432074-e043-587b-aef4-af753b25b835', 'neet_ug', 'Chemistry', 'The p-Block Elements', 'Among Group 16 elements, which one does NOT show –2 oxidation state?', '[{"id": "a", "text": "Te"}, {"id": "b", "text": "Po"}, {"id": "c", "text": "O"}, {"id": "d", "text": "Se"}]'::jsonb, 'b', 'Polonium, metallic and at the bottom of the group, hardly shows the −2 state.', 'Down Group 16, electronegativity falls and metallic character rises, so the stability of the −2 state drops. Polonium is a metal and essentially does not show −2; its common states are +2 and +4.', '{"a": "Te shows −2, for example in H₂Te and tellurides.", "c": "Oxygen shows −2 in most of its compounds.", "d": "Se shows −2 in H₂Se and selenides."}'::jsonb, 'Stability of the −2 state in Group 16 falls down the group; Po hardly shows it.', 'easy', true, 2024, NULL, 'NEET UG 2024 (NTA) · answer verified by UG Prep', NULL),
('67e6bfbb-00fe-5071-8f50-d382ff7f35f4', 'neet_ug', 'Chemistry', 'Equilibrium', 'For the reaction 2A ⇌ B + C, Kc = 4 × 10⁻³. At a given time, the composition of reaction mixture is: [A] = [B] = [C] = 2 × 10⁻³ M.
Then, which of the following is correct?', '[{"id": "a", "text": "Reaction has a tendency to go in backward direction."}, {"id": "b", "text": "Reaction has gone to completion in forward direction."}, {"id": "c", "text": "Reaction is at equilibrium."}, {"id": "d", "text": "Reaction has a tendency to go in forward direction."}]'::jsonb, 'a', 'Qc = 1 is greater than Kc = 4 × 10⁻³, so the reaction shifts backward.', 'Qc = [B][C]/[A]² = (2×10⁻³)(2×10⁻³)/(2×10⁻³)² = 1. Since Qc (1) > Kc (0.004), there are too many products, and the reaction moves in the reverse direction to reach equilibrium.', '{"b": "Completion would mean [A] ≈ 0, which is not the case.", "c": "At equilibrium Qc would equal Kc.", "d": "The forward shift happens only when Qc < Kc."}'::jsonb, 'Qc < Kc means a forward shift; Qc > Kc means a backward shift; Qc = Kc means equilibrium.', 'easy', true, 2024, NULL, 'NEET UG 2024 (NTA) · answer verified by UG Prep', NULL),
('287fdf54-cd9b-5609-99dd-7a6456ccd199', 'neet_ug', 'Chemistry', 'Chemical Kinetics', 'Which plot of ln k vs 1/T is consistent with Arrhenius equation?', '[{"id": "a", "text": "Option (1) in figure"}, {"id": "b", "text": "Option (2) in figure"}, {"id": "c", "text": "Option (3) in figure"}, {"id": "d", "text": "Option (4) in figure"}]'::jsonb, 'b', 'ln k = ln A − Eₐ/RT, a straight line of negative slope with a positive intercept ln A.', 'Taking logs of k = Ae^(−Eₐ/RT) gives ln k = ln A − (Eₐ/R)(1/T). A plot of ln k against 1/T is linear with slope −Eₐ/R (negative) and intercept ln A on the ln k axis, which is graph (2).', '{"a": "Positive slope would imply negative Eₐ.", "c": "Positive slope, inconsistent with the equation.", "d": "Positive slope with intercept; slope must be negative."}'::jsonb, 'The slope of an ln k vs 1/T plot is −Eₐ/R; for log k it is −Eₐ/2.303R.', 'easy', true, 2024, NULL, 'NEET UG 2024 (NTA) · answer verified by UG Prep', '/pyq/ug/2024/73.webp'),
('71ea23a6-24c3-5d23-9573-95f6bf289c6e', 'neet_ug', 'Chemistry', 'Equilibrium', 'In which of the following equilibria, Kp and Kc are NOT equal?', '[{"id": "a", "text": "CO(g) + H₂O(g) ⇌ CO₂(g) + H₂(g)"}, {"id": "b", "text": "2BrCl(g) ⇌ Br₂(g) + Cl₂(g)"}, {"id": "c", "text": "PCl₅(g) ⇌ PCl₃(g) + Cl₂(g)"}, {"id": "d", "text": "H₂(g) + I₂(g) ⇌ 2HI(g)"}]'::jsonb, 'c', 'Kp = Kc(RT)^Δn, and only PCl₅ dissociation has Δn ≠ 0 (Δn = +1).', 'Δn(g) is 2−2 = 0 for options (1), (2) and (4), so Kp = Kc for them. For PCl₅ ⇌ PCl₃ + Cl₂, Δn = 2 − 1 = 1, so Kp = Kc(RT).', '{"a": "Δn = 0.", "b": "Δn = 0.", "d": "Δn = 0."}'::jsonb, 'Kp = Kc(RT)^Δn, where Δn = moles of gaseous products − moles of gaseous reactants.', 'easy', true, 2024, NULL, 'NEET UG 2024 (NTA) · answer verified by UG Prep', NULL),
('fb0d5a20-190b-59fa-80f3-c41160fee8d7', 'neet_ug', 'Chemistry', 'Hydrocarbons', 'Given below are two statements:
Statement I: The boiling point of three isomeric pentanes follows the order n-pentane > isopentane > neopentane
Statement II: When branching increases, the molecule attains a shape of sphere. This results in smaller surface area for contact, due to which the intermolecular forces between the spherical molecules are weak, thereby lowering the boiling point.
In the light of the above statements, choose the most appropriate answer from the options given below:', '[{"id": "a", "text": "Statement I is correct but Statement II is incorrect."}, {"id": "b", "text": "Statement I is incorrect but Statement II is correct."}, {"id": "c", "text": "Both Statement I and Statement II are correct."}, {"id": "d", "text": "Both Statement I and Statement II are incorrect."}]'::jsonb, 'c', 'More branching gives a smaller surface area, weaker dispersion forces and a lower boiling point.', 'The boiling points are n-pentane 309 K > isopentane 301 K > neopentane 282.5 K. Branching makes the molecule more compact and nearly spherical, which reduces the contact area and so the van der Waals forces. Both statements are correct, and II explains I.', '{"a": "Statement II is also correct.", "b": "Statement I''s order is correct.", "d": "Both statements are correct."}'::jsonb, 'Among isomeric alkanes, boiling point decreases as branching increases.', 'easy', true, 2024, NULL, 'NEET UG 2024 (NTA) · answer verified by UG Prep', NULL),
('a421156b-fb77-5e3e-9bcc-5b0f998ee83b', 'neet_ug', 'Chemistry', 'Haloalkanes and Haloarenes', 'The compound that will undergo SN1 reaction with the fastest rate is', '[{"id": "a", "text": "Option (1) in figure"}, {"id": "b", "text": "Option (2) in figure"}, {"id": "c", "text": "Option (3) in figure"}, {"id": "d", "text": "Option (4) in figure"}]'::jsonb, 'b', '1-Bromo-1-phenylethane ionises to a resonance-stabilised secondary benzylic carbocation.', 'SN1 rate depends on how stable the carbocation is. Option (2) gives C₆H₅CH⁺CH₃, which is secondary and delocalised into the ring, so it forms fastest. Bromobenzene cannot ionise (partial C–Br double bond, unstable phenyl cation). Options (3) and (4) give unstabilised 1° and 2° alkyl cations.', '{"a": "Aryl halides do not undergo SN1; the phenyl cation is very unstable.", "c": "Cyclohexylmethyl bromide would give a primary carbocation.", "d": "Bromocyclohexane gives a plain secondary cation with no resonance."}'::jsonb, 'Benzylic and allylic halides are highly reactive in SN1 because of resonance stabilisation.', 'easy', true, 2024, NULL, 'NEET UG 2024 (NTA) · answer verified by UG Prep', '/pyq/ug/2024/76.webp'),
('6a2bb94f-7285-5693-a1b0-1f561387d8bb', 'neet_ug', 'Chemistry', 'Structure of Atom', 'The energy of an electron in the ground state (n = 1) for He⁺ ion is –x J, then that for an electron in n = 2 state for Be³⁺ ion in J is:', '[{"id": "a", "text": "–4x"}, {"id": "b", "text": "−(4/9)x"}, {"id": "c", "text": "–x"}, {"id": "d", "text": "−x/9"}]'::jsonb, 'c', 'E ∝ Z²/n²: He⁺ (Z = 2, n = 1) and Be³⁺ (Z = 4, n = 2) both give Z²/n² = 4.', 'For hydrogen-like species Eₙ = −k Z²/n². He⁺, n = 1: −k(4/1) = −4k = −x. Be³⁺, n = 2: −k(16/4) = −4k = −x. The energies are equal.', '{"a": "Uses Z² = 16 but forgets to divide by n² = 4.", "b": "Uses the wrong Z or n.", "d": "Divides by 9, which corresponds to n = 3."}'::jsonb, 'For hydrogen-like ions Eₙ = −13.6 Z²/n² eV (−2.18 × 10⁻¹⁸ Z²/n² J).', 'easy', true, 2024, NULL, 'NEET UG 2024 (NTA) · answer verified by UG Prep', NULL),
('d51ccd1b-fd41-548d-ad0b-a5c11e1e4e9f', 'neet_ug', 'Chemistry', 'Thermodynamics', 'In which of the following processes entropy increases?
A. A liquid evaporates to vapour.
B. Temperature of a crystalline solid lowered from 130 K to 0 K.
C. 2NaHCO₃(s) → Na₂CO₃(s) + CO₂(g) + H₂O(g)
D. Cl₂(g) → 2Cl(g)
Choose the correct answer from the options given below:', '[{"id": "a", "text": "A, C and D"}, {"id": "b", "text": "C and D"}, {"id": "c", "text": "A and C"}, {"id": "d", "text": "A, B and D"}]'::jsonb, 'a', 'Vaporisation, gas-forming decomposition and dissociation all raise disorder; cooling a solid lowers it.', 'A: gas is far more disordered than liquid, so ΔS > 0. B: cooling to 0 K reduces thermal motion, so S falls (to zero for a perfect crystal). C: a solid gives two gaseous products, so ΔS > 0. D: one gas molecule gives two atoms, so ΔS > 0.', '{"b": "Misses process A, evaporation.", "c": "Misses D, where the number of gas particles doubles.", "d": "Includes B, where entropy decreases."}'::jsonb, 'Entropy increases when Δn(gas) > 0, on melting or vaporisation, and on heating.', 'easy', true, 2024, NULL, 'NEET UG 2024 (NTA) · answer verified by UG Prep', NULL),
('49385f39-8ef6-5477-be1c-d868127b0d65', 'neet_ug', 'Chemistry', 'Organic Chemistry – Some Basic Principles and Techniques', 'On heating some solid substance change from solid to vapour state without passing through liquid state. The technique used for the purification of such solid substances based on the above principle is known as:', '[{"id": "a", "text": "Distillation"}, {"id": "b", "text": "Chromatography"}, {"id": "c", "text": "Crystallization"}, {"id": "d", "text": "Sublimation"}]'::jsonb, 'd', 'Direct solid → vapour conversion is sublimation, used to purify camphor, naphthalene and similar solids.', 'Sublimable solids are heated so they vaporise without melting. The vapour then condenses back to pure solid, leaving non-volatile impurities behind.', '{"a": "Distillation separates liquids by boiling point.", "b": "Chromatography separates by differential adsorption or partition.", "c": "Crystallisation uses differences in solubility."}'::jsonb, 'Camphor, naphthalene, anthracene, benzoic acid and NH₄Cl can be purified by sublimation.', 'easy', true, 2024, NULL, 'NEET UG 2024 (NTA) · answer verified by UG Prep', NULL),
('180e5bd1-2407-5098-870f-009de1c68926', 'neet_ug', 'Chemistry', 'Coordination Compounds', 'Match List-I with List-II
List-I (Complex) | List-II (Type of isomerism)
(A) [Co(NH₃)₅(NO₂)]Cl₂ | (I) Solvate isomerism
(B) [Co(NH₃)₅(SO₄)]Br | (II) Linkage isomerism
(C) [Co(NH₃)₆][Cr(CN)₆] | (III) Ionization isomerism
(D) [Co(H₂O)₆]Cl₃ | (IV) Coordination isomerism
Choose the correct answer from the options given below:', '[{"id": "a", "text": "A-I, B-IV, C-III, D-II"}, {"id": "b", "text": "A-II, B-IV, C-III, D-I"}, {"id": "c", "text": "A-II, B-III, C-IV, D-I"}, {"id": "d", "text": "A-I, B-III, C-IV, D-II"}]'::jsonb, 'c', 'NO₂⁻ is ambidentate (linkage), SO₄²⁻/Br⁻ exchange (ionisation), cation–anion ligand swap (coordination), and H₂O in/out of sphere (solvate).', 'NO₂⁻ can bind through N or O, giving linkage isomers. [Co(NH₃)₅SO₄]Br and [Co(NH₃)₅Br]SO₄ are ionisation isomers. Ligands can swap between the complex cation and anion in [Co(NH₃)₆][Cr(CN)₆], giving coordination isomerism. [Co(H₂O)₆]Cl₃ vs [Co(H₂O)₅Cl]Cl₂·H₂O is solvate (hydrate) isomerism.', '{"a": "Calls the nitro complex a solvate isomer and the cation–anion pair ionisation.", "b": "Puts B and C the wrong way round.", "d": "Swaps linkage and solvate."}'::jsonb, 'Hydrate isomers of CrCl₃·6H₂O differ in colour (violet, light green, dark green).', 'easy', true, 2024, NULL, 'NEET UG 2024 (NTA) · answer verified by UG Prep', NULL),
('84b15815-ec20-5626-9ede-7a837c2b7d85', 'neet_ug', 'Chemistry', 'Amines', 'Given below are two statements:
Statement I: Aniline does not undergo Friedel-Crafts alkylation reaction.
Statement II: Aniline cannot be prepared through Gabriel synthesis.
In the light of the above statements, choose the correct answer from the options given below:', '[{"id": "a", "text": "Statement I is true but Statement II is false."}, {"id": "b", "text": "Statement I is false but Statement II is true."}, {"id": "c", "text": "Both Statement I and Statement II are true."}, {"id": "d", "text": "Both Statement I and Statement II are false."}]'::jsonb, 'c', 'Aniline complexes AlCl₃, and aryl halides do not undergo SN2 with phthalimide.', 'Aniline, a Lewis base, forms a salt with the Lewis acid AlCl₃. This puts a positive charge on N and deactivates the ring, so Friedel–Crafts reactions fail. Gabriel synthesis needs SN2 attack of the phthalimide anion on an alkyl halide, which aryl halides do not undergo, so aniline cannot be made this way. Both statements are true.', '{"a": "Statement II is also true.", "b": "Statement I is true.", "d": "Both statements are true."}'::jsonb, 'Gabriel phthalimide synthesis gives only primary aliphatic amines.', 'easy', true, 2024, NULL, 'NEET UG 2024 (NTA) · answer verified by UG Prep', NULL),
('747525f0-c289-5230-aca7-c014c5c78b7e', 'neet_ug', 'Chemistry', 'Classification of Elements and Periodicity in Properties', 'Arrange the following elements in increasing order of first ionization enthalpy:
Li, Be, B, C, N
Choose the correct answer from options given below:', '[{"id": "a", "text": "Li < Be < C < B < N"}, {"id": "b", "text": "Li < Be < N < B < C"}, {"id": "c", "text": "Li < Be < B < C < N"}, {"id": "d", "text": "Li < B < Be < C < N"}]'::jsonb, 'd', 'B is below Be because B''s 2p electron is easier to remove than Be''s 2s electron.', 'Ionisation enthalpy generally rises across period 2. Be (2s²) has a fully filled, more penetrating 2s subshell, while B loses a less penetrating 2p electron, so IE(B) < IE(Be). Values: Li 520, B 801, Be 899, C 1086, N 1402 kJ/mol.', '{"a": "Places C below B.", "b": "Places N below B and C.", "c": "Ignores the Be > B anomaly."}'::jsonb, 'Period-2 IE anomalies: Be > B and N > O.', 'easy', true, 2024, NULL, 'NEET UG 2024 (NTA) · answer verified by UG Prep', NULL),
('f5fa91dc-84a6-579b-9187-315f8110c8a4', 'neet_ug', 'Chemistry', 'Some Basic Concepts of Chemistry', 'The highest number of helium atoms is in', '[{"id": "a", "text": "4 g of helium"}, {"id": "b", "text": "2.271098 L of helium at STP"}, {"id": "c", "text": "4 mol of helium"}, {"id": "d", "text": "4 u of helium"}]'::jsonb, 'c', '4 mol of He contains 4Nₐ atoms, more than any other option.', '4 g He = 1 mol = Nₐ atoms. 2.271098 L at STP (22.7 L/mol) = 0.1 mol. 4 mol = 4Nₐ atoms. 4 u is the mass of one He atom. So 4 mol is the largest.', '{"a": "Only 1 mol.", "b": "Only 0.1 mol, since the molar volume at STP is 22.7 L.", "d": "4 u is a single atom."}'::jsonb, 'Molar volume at STP (1 bar, 273.15 K) is 22.7 L mol⁻¹.', 'easy', true, 2024, NULL, 'NEET UG 2024 (NTA) · answer verified by UG Prep', NULL),
('46635626-07c3-5dd4-812c-4d23ed8a4b5d', 'neet_ug', 'Chemistry', 'Organic Chemistry – Some Basic Principles and Techniques', 'The most stable carbocation among the following is:', '[{"id": "a", "text": "Option (1) in figure"}, {"id": "b", "text": "Option (2) in figure"}, {"id": "c", "text": "Option (3) in figure"}, {"id": "d", "text": "Option (4) in figure"}]'::jsonb, 'b', 'The 1-methylcyclohexyl cation is tertiary and has the most hyperconjugating α-hydrogens.', 'Option (1) is primary, and options (3) and (4) are secondary. Option (2) is a tertiary carbocation stabilised by +I effects and hyperconjugation from 7 α-H atoms (CH₃ plus two ring CH₂ groups), so it is the most stable.', '{"a": "Primary carbocation: the least stable.", "c": "Secondary, with only 3 α-H.", "d": "Secondary, with 5 α-H; still less stable than tertiary."}'::jsonb, 'Carbocation stability: 3° > 2° > 1° > CH₃⁺ (hyperconjugation and +I effect).', 'easy', true, 2024, NULL, 'NEET UG 2024 (NTA) · answer verified by UG Prep', '/pyq/ug/2024/84.webp'),
('af38b7e2-f05e-5a82-97a2-d301783c48f1', 'neet_ug', 'Chemistry', 'Solutions', 'The Henry''s law constant (K_H) values of three gases (A, B, C) in water are 145, 2 × 10⁻⁵ and 35 kbar, respectively. The solubility of these gases in water follow the order:', '[{"id": "a", "text": "A > C > B"}, {"id": "b", "text": "A > B > C"}, {"id": "c", "text": "B > A > C"}, {"id": "d", "text": "B > C > A"}]'::jsonb, 'd', 'Solubility varies inversely with K_H, so B (smallest K_H) > C > A.', 'p = K_H·x gives x = p/K_H. At the same partial pressure, a lower K_H means a higher mole fraction dissolved. Since K_H(B) = 2×10⁻⁵ < K_H(C) = 35 < K_H(A) = 145 kbar, solubility is B > C > A.', '{"a": "This is the order of K_H, not solubility.", "b": "Mixes up the inverse relation.", "c": "Places A above C, though A has the larger K_H."}'::jsonb, 'The higher the K_H at a given pressure, the lower the solubility of the gas.', 'easy', true, 2024, NULL, 'NEET UG 2024 (NTA) · answer verified by UG Prep', NULL),
('0075fe13-71ec-5af2-9e4a-4fd7420c5de3', 'neet_ug', 'Chemistry', 'Some Basic Concepts of Chemistry', 'A compound X contains 32% of A, 20% of B and remaining percentage of C. Then, the empirical formula of X is:
(Given atomic masses of A = 64; B = 40; C = 32u)', '[{"id": "a", "text": "AB₂C₂"}, {"id": "b", "text": "ABC₄"}, {"id": "c", "text": "A₂BC₂"}, {"id": "d", "text": "ABC₃"}]'::jsonb, 'd', 'Mole ratio A : B : C = 0.5 : 0.5 : 1.5 = 1 : 1 : 3.', 'In 100 g: A = 32/64 = 0.5 mol, B = 20/40 = 0.5 mol, C = (100−52)/32 = 48/32 = 1.5 mol. Dividing by 0.5 gives 1 : 1 : 3, so the formula is ABC₃.', '{"a": "Ratio 1:2:2 does not match 0.5:0.5:1.5.", "b": "Overcounts C.", "c": "Doubles A wrongly."}'::jsonb, 'Empirical formula: % ÷ atomic mass, then divide by the smallest value.', 'easy', true, 2024, NULL, 'NEET UG 2024 (NTA) · answer verified by UG Prep', NULL),
('80e0edad-0b36-5f6c-a661-52cb9882c069', 'neet_ug', 'Chemistry', 'Haloalkanes and Haloarenes', 'The products A and B obtained in the following reactions, respectively, are
3ROH + PCl₃ → 3RCl + A
ROH + PCl₅ → RCl + HCl + B', '[{"id": "a", "text": "H₃PO₄ and POCl₃"}, {"id": "b", "text": "H₃PO₃ and POCl₃"}, {"id": "c", "text": "POCl₃ and H₃PO₃"}, {"id": "d", "text": "POCl₃ and H₃PO₄"}]'::jsonb, 'b', 'PCl₃ gives phosphorous acid (H₃PO₃); PCl₅ gives phosphoryl chloride (POCl₃).', 'Three –OH groups replace the three Cl of PCl₃, giving P(OH)₃ = H₃PO₃. With PCl₅, one Cl goes to R and one Cl takes the H as HCl, while P picks up the oxygen as POCl₃.', '{"a": "PCl₃ (P +3) gives H₃PO₃, not H₃PO₄ (P +5).", "c": "The products are reversed.", "d": "Reversed, and the wrong acid as well."}'::jsonb, 'With alcohols, PCl₃ gives H₃PO₃ and PCl₅ gives POCl₃ + HCl; SOCl₂ gives SO₂ + HCl.', 'easy', true, 2024, NULL, 'NEET UG 2024 (NTA) · answer verified by UG Prep', NULL),
('ca1397df-a7e2-597a-bdca-e668a589547d', 'neet_ug', 'Chemistry', 'Solutions', 'The plot of osmotic pressure (Π) vs concentration (mol L⁻¹) for a solution gives a straight line with slope 25.73 L bar mol⁻¹. The temperature at which the osmotic pressure measurement is done is:
(Use R = 0.083 L bar mol⁻¹ K⁻¹)', '[{"id": "a", "text": "25.73ºC"}, {"id": "b", "text": "12.05ºC"}, {"id": "c", "text": "37ºC"}, {"id": "d", "text": "310ºC"}]'::jsonb, 'c', 'Slope = RT, so T = 25.73/0.083 = 310 K = 37 °C.', 'Π = CRT, so the Π vs C slope is RT. T = 25.73 / 0.083 = 310 K. Converting, 310 − 273 = 37 °C.', '{"a": "Uses the slope value directly as the temperature.", "b": "Arithmetic error.", "d": "310 is in kelvin, not °C."}'::jsonb, 'Van''t Hoff osmotic equation: Π = CRT (×i for electrolytes).', 'easy', true, 2024, NULL, 'NEET UG 2024 (NTA) · answer verified by UG Prep', NULL),
('81b27ab2-dbab-5e1b-9e6c-cfa33d1ad2bb', 'neet_ug', 'Chemistry', 'Aldehydes, Ketones and Carboxylic Acids', 'For the given reaction:
C₆H₁₁–CH=CH–C₆H₁₁ (1,2-dicyclohexylethene) —KMnO₄/H⁺→ ''P'' (major product)
''P'' is', '[{"id": "a", "text": "Option (1) in figure"}, {"id": "b", "text": "Option (2) in figure"}, {"id": "c", "text": "Option (3) in figure"}, {"id": "d", "text": "Option (4) in figure"}]'::jsonb, 'd', 'Hot acidic KMnO₄ cleaves the C=C and oxidises each =CH– to –COOH, giving cyclohexanecarboxylic acid.', 'Acidified permanganate cleaves the double bond oxidatively. Each CH fragment carrying a cyclohexyl group becomes a carboxylic acid, so two molecules of cyclohexanecarboxylic acid form. The aldehyde is not isolated under these strong conditions.', '{"a": "The diol forms with cold dilute alkaline KMnO₄ (Baeyer''s reagent), not acidic KMnO₄.", "b": "The diketone would need both carbons to stay joined; C=C cleavage happens instead.", "c": "The aldehyde is over-oxidised to the acid by KMnO₄/H⁺."}'::jsonb, 'Acidic KMnO₄ cleavage: RCH= gives RCOOH, R₂C= gives a ketone, and CH₂= gives CO₂.', 'med', true, 2024, NULL, 'NEET UG 2024 (NTA) · answer verified by UG Prep', '/pyq/ug/2024/89.webp'),
('48e87967-1c76-565e-893a-59a13cde40e8', 'neet_ug', 'Chemistry', 'Coordination Compounds', 'Given below are two statements:
Statement I: [Co(NH₃)₆]³⁺ is a homoleptic complex whereas [Co(NH₃)₄Cl₂]⁺ is a heteroleptic complex.
Statement II: Complex [Co(NH₃)₆]³⁺ has only one kind of ligands but [Co(NH₃)₄Cl₂]⁺ has more than one kind of ligands.
In the light of the above statements, choose the correct answer from the options given below:', '[{"id": "a", "text": "Statement I is true but Statement II is false."}, {"id": "b", "text": "Statement I is false but Statement II is true."}, {"id": "c", "text": "Both Statement I and Statement II are true."}, {"id": "d", "text": "Both Statement I and Statement II are false."}]'::jsonb, 'c', 'Homoleptic means one kind of ligand and heteroleptic means more than one, so both statements are true.', '[Co(NH₃)₆]³⁺ has only NH₃ ligands, so it is homoleptic. [Co(NH₃)₄Cl₂]⁺ has NH₃ and Cl⁻, so it is heteroleptic. Statement II gives exactly this definition.', '{"a": "Statement II is also true.", "b": "Statement I is true.", "d": "Both are true."}'::jsonb, 'Homoleptic: one type of donor ligand only; heteroleptic: more than one type.', 'easy', true, 2024, NULL, 'NEET UG 2024 (NTA) · answer verified by UG Prep', NULL),
('aa00d229-1b20-5c9d-9d84-695c2006430f', 'neet_ug', 'Chemistry', 'Practical Chemistry (Inorganic preparations)', 'During the preparation of Mohr''s salt solution (Ferrous ammonium sulphate), which of the following acid is added to prevent hydrolysis of Fe²⁺ ion?', '[{"id": "a", "text": "dilute nitric acid"}, {"id": "b", "text": "dilute sulphuric acid"}, {"id": "c", "text": "dilute hydrochloric acid"}, {"id": "d", "text": "concentrated sulphuric acid"}]'::jsonb, 'b', 'Dilute H₂SO₄ suppresses Fe²⁺ hydrolysis without adding foreign ions or oxidising Fe²⁺.', 'Mohr''s salt is FeSO₄·(NH₄)₂SO₄·6H₂O, which already contains sulphate. A little dilute H₂SO₄ keeps the solution acidic and stops Fe²⁺ hydrolysing to basic salts. HNO₃ and concentrated H₂SO₄ would oxidise Fe²⁺ to Fe³⁺, and HCl adds chloride ions.', '{"a": "HNO₃ is oxidising and converts Fe²⁺ to Fe³⁺.", "c": "HCl adds Cl⁻, a foreign ion.", "d": "Concentrated H₂SO₄ is oxidising and dehydrating."}'::jsonb, 'Mohr''s salt is a double salt, (NH₄)₂Fe(SO₄)₂·6H₂O, used as a primary standard in KMnO₄ titrations.', 'easy', true, 2024, NULL, 'NEET UG 2024 (NTA) · answer verified by UG Prep', NULL),
('4c2da1ee-970b-5f9b-847b-aa3fb4fcc2f4', 'neet_ug', 'Chemistry', 'Chemical Bonding and Molecular Structure', 'Identify the correct answer.', '[{"id": "a", "text": "Dipole moment of NF₃ is greater than that of NH₃."}, {"id": "b", "text": "Three canonical forms can be drawn for CO₃²⁻ ion."}, {"id": "c", "text": "Three resonance structures can be drawn for ozone."}, {"id": "d", "text": "BF₃ has non-zero dipole moment."}]'::jsonb, 'b', 'CO₃²⁻ has three equivalent resonance structures.', 'Carbonate has three equivalent canonical forms, with the C=O double bond on each oxygen in turn, so each C–O bond order is 1.33. NH₃ (1.47 D) has a larger dipole than NF₃ (0.23 D) because in NH₃ the lone pair moment adds to the bond moments. O₃ has only two resonance structures, and planar BF₃ has μ = 0.', '{"a": "NF₃ has the smaller dipole: its N–F bond moments oppose the lone-pair moment.", "c": "Ozone has two resonance structures.", "d": "Trigonal planar BF₃ is symmetric, so μ = 0."}'::jsonb, 'μ(NH₃) = 1.47 D > μ(NF₃) = 0.23 D, though F is more electronegative than H.', 'easy', true, 2024, NULL, 'NEET UG 2024 (NTA) · answer verified by UG Prep', NULL),
('cd0d30e4-71f8-501e-9b5a-c68bf0057ca8', 'neet_ug', 'Chemistry', 'Practical Chemistry (Qualitative analysis)', 'Given below are certain cations. Using inorganic qualitative analysis, arrange them in increasing group number from 0 to VI.
A. Al³⁺
B. Cu²⁺
C. Ba²⁺
D. Co²⁺
E. Mg²⁺
Choose the correct answer from the option given below:', '[{"id": "a", "text": "E, C, D, B, A"}, {"id": "b", "text": "E, A, B, C, D"}, {"id": "c", "text": "B, A, D, C, E"}, {"id": "d", "text": "B, C, A, D, E"}]'::jsonb, 'c', 'Cu²⁺ (II) < Al³⁺ (III) < Co²⁺ (IV) < Ba²⁺ (V) < Mg²⁺ (VI).', 'Group II cations precipitate as sulphides with H₂S in dilute HCl (Cu²⁺). Group III precipitate as hydroxides with NH₄OH/NH₄Cl (Al³⁺). Group IV precipitate as sulphides with H₂S in ammoniacal medium (Co²⁺). Group V precipitate as carbonates with (NH₄)₂CO₃ (Ba²⁺). Group VI is Mg²⁺.', '{"a": "Reverses the order.", "b": "Puts Mg²⁺ first; it belongs to group VI.", "d": "Puts Ba²⁺ (group V) before Al³⁺ (group III)."}'::jsonb, 'Group zero is NH₄⁺; group VI is Mg²⁺.', 'med', true, 2024, NULL, 'NEET UG 2024 (NTA) · answer verified by UG Prep', NULL),
('40088b53-e614-5e1d-8aad-9b0ffbcb8a61', 'neet_ug', 'Chemistry', 'Amines', 'Identify the major product C formed in the following reaction sequence:
CH₃–CH₂–CH₂–I —NaCN→ A —OH⁻, partial hydrolysis→ B —NaOH, Br₂→ C (major)', '[{"id": "a", "text": "butanamide"}, {"id": "b", "text": "α-bromobutanoic acid"}, {"id": "c", "text": "propylamine"}, {"id": "d", "text": "butylamine"}]'::jsonb, 'c', 'The nitrile is partially hydrolysed to an amide, and the Hofmann bromamide reaction then removes one carbon to give propylamine.', 'CH₃CH₂CH₂I + CN⁻ gives CH₃CH₂CH₂CN (A, butanenitrile). Partial hydrolysis gives CH₃CH₂CH₂CONH₂ (B, butanamide). Br₂/NaOH (Hofmann degradation) gives CH₃CH₂CH₂NH₂ (C, propylamine), which has one carbon fewer than B.', '{"a": "Butanamide is B, not C.", "b": "The HVZ reaction needs Br₂/red P on the acid, not Br₂/NaOH on the amide.", "d": "Butylamine would come from reducing the nitrile; Hofmann loses a carbon."}'::jsonb, 'Hofmann bromamide degradation gives a 1° amine with one carbon fewer than the amide.', 'easy', true, 2024, NULL, 'NEET UG 2024 (NTA) · answer verified by UG Prep', NULL),
('d8e05807-a49a-5877-8e8b-f873834ec1e4', 'neet_ug', 'Chemistry', 'Chemical Kinetics', 'The rate of a reaction quadruples when temperature changes from 27ºC to 57ºC. Calculate the energy of activation.
Given R = 8.314 J K⁻¹ mol⁻¹, log 4 = 0.6021', '[{"id": "a", "text": "3.80 kJ/mol"}, {"id": "b", "text": "3804 kJ/mol"}, {"id": "c", "text": "38.04 kJ/mol"}, {"id": "d", "text": "380.4 kJ/mol"}]'::jsonb, 'c', 'Using log(k₂/k₁) = (Eₐ/2.303R)(T₂−T₁)/(T₁T₂) gives Eₐ ≈ 38.04 kJ/mol.', 'T₁ = 300 K and T₂ = 330 K. Eₐ = 2.303 × 8.314 × log 4 × (T₁T₂/(T₂−T₁)) = 2.303 × 8.314 × 0.6021 × (300 × 330/30) = 11.53 × 3300 ≈ 38044 J ≈ 38.04 kJ/mol.', '{"a": "Off by a factor of 10.", "b": "Off by 100 and in the wrong units.", "d": "Off by a factor of 10."}'::jsonb, 'log(k₂/k₁) = (Eₐ/2.303R)·(T₂ − T₁)/(T₁T₂).', 'med', true, 2024, NULL, 'NEET UG 2024 (NTA) · answer verified by UG Prep', NULL),
('2e1a8016-f0ed-5714-aa64-10c5f0470a2a', 'neet_ug', 'Chemistry', 'Equilibrium', 'Consider the following reaction in a sealed vessel at equilibrium with concentrations of N₂ = 3.0 × 10⁻³ M, O₂ = 4.2 × 10⁻³ M and NO = 2.8 × 10⁻³ M.
2NO(g) ⇌ N₂(g) + O₂(g)
If 0.1 mol L⁻¹ of NO(g) is taken in a closed vessel, what will be degree of dissociation (α) of NO(g) at equilibrium?', '[{"id": "a", "text": "0.8889"}, {"id": "b", "text": "0.717"}, {"id": "c", "text": "0.00889"}, {"id": "d", "text": "0.0889"}]'::jsonb, 'b', 'Kc ≈ 1.607, and solving 0.5α/(1−α) = √Kc gives α ≈ 0.717.', 'Kc = (3.0×10⁻³)(4.2×10⁻³)/(2.8×10⁻³)² = 12.6/7.84 ≈ 1.607. Starting from 0.1 M NO: [NO] = 0.1(1−α) and [N₂] = [O₂] = 0.05α. Then Kc = (0.05α)²/(0.1(1−α))², so 0.5α/(1−α) = √1.607 = 1.268. This gives α = 1.268/1.768 ≈ 0.717.', '{"a": "Overestimates α; it does not satisfy Kc.", "c": "Too small; it ignores Kc > 1.", "d": "Too small by an order of magnitude."}'::jsonb, 'Taking the square root of both sides simplifies equilibrium expressions that are perfect squares.', 'hard', true, 2024, NULL, 'NEET UG 2024 (NTA) · answer verified by UG Prep', NULL),
('bee91497-9ab2-5236-8946-316463d748a7', 'neet_ug', 'Chemistry', 'Thermodynamics', 'The work done during reversible isothermal expansion of one mole of hydrogen gas at 25ºC from pressure of 20 atmosphere to 10 atmosphere is:
(Given R = 2.0 cal K⁻¹ mol⁻¹)', '[{"id": "a", "text": "413.14 calories"}, {"id": "b", "text": "100 calories"}, {"id": "c", "text": "0 calorie"}, {"id": "d", "text": "– 413.14 calories"}]'::jsonb, 'd', 'w = −2.303nRT log(P₁/P₂) = −2.303 × 1 × 2 × 298 × log 2 ≈ −413.14 cal.', 'For reversible isothermal expansion, w = −2.303nRT log(P₁/P₂) = −2.303 × 1 × 2.0 × 298 × 0.3010 ≈ −413.1 cal. The sign is negative because the system does work on the surroundings.', '{"a": "Correct magnitude but wrong sign under the IUPAC convention (work done by the system is negative).", "b": "Arbitrary value.", "c": "Zero work applies to free expansion, not reversible expansion."}'::jsonb, 'Reversible isothermal work: w = −2.303nRT log(V₂/V₁) = −2.303nRT log(P₁/P₂).', 'med', true, 2024, NULL, 'NEET UG 2024 (NTA) · answer verified by UG Prep', NULL),
('e377ffb6-172c-5aca-b15f-0c9c696eb44c', 'neet_ug', 'Chemistry', 'Electrochemistry', 'Mass in grams of copper deposited by passing 9.6487 A current through a voltmeter containing copper sulphate solution for 100 seconds is:
(Given: Molar mass of Cu : 63 g mol⁻¹, 1F = 96487 C)', '[{"id": "a", "text": "31.5 g"}, {"id": "b", "text": "0.0315 g"}, {"id": "c", "text": "3.15 g"}, {"id": "d", "text": "0.315 g"}]'::jsonb, 'd', 'Q = 964.87 C = 0.01 F, which deposits 0.005 mol Cu = 0.315 g.', 'Q = It = 9.6487 × 100 = 964.87 C = 0.01 F. Cu²⁺ + 2e⁻ → Cu, so 0.01 F deposits 0.005 mol Cu = 0.005 × 63 = 0.315 g.', '{"a": "Uses 1 F instead of 0.01 F.", "b": "Off by a factor of 10.", "c": "Off by a factor of 10."}'::jsonb, 'Faraday''s first law: m = (M/nF) × I × t.', 'easy', true, 2024, NULL, 'NEET UG 2024 (NTA) · answer verified by UG Prep', NULL),
('3433736d-dbd6-544d-acb0-aee27abc2645', 'neet_ug', 'Chemistry', 'Alcohols, Phenols and Ethers', 'Major products A and B formed in the following reaction sequence, are
2-Methylcyclohexan-1-ol —PBr₃→ A (major) —alc. KOH, Δ→ B (major)', '[{"id": "a", "text": "Option (1) in figure"}, {"id": "b", "text": "Option (2) in figure"}, {"id": "c", "text": "Option (3) in figure"}, {"id": "d", "text": "Option (4) in figure"}]'::jsonb, 'c', 'PBr₃ gives 1-bromo-2-methylcyclohexane, and dehydrohalogenation gives the Zaitsev alkene 1-methylcyclohexene.', 'PBr₃ replaces –OH by –Br without carbocation rearrangement, so A is 1-bromo-2-methylcyclohexane. Alcoholic KOH on heating causes β-elimination. Zaitsev''s rule favours the more substituted (trisubstituted) alkene, so B is 1-methylcyclohexene.', '{"a": "PBr₃ does not brominate the ring while keeping the OH.", "b": "PBr₃ does not give a bromohydrin, and KOH does not give a ketone.", "d": "This is the less substituted (Hofmann-type) alkene, which is the minor product."}'::jsonb, 'Dehydrohalogenation with alcoholic KOH follows Zaitsev''s rule, so the more substituted alkene is major.', 'med', true, 2024, NULL, 'NEET UG 2024 (NTA) · answer verified by UG Prep', '/pyq/ug/2024/99.webp'),
('277d396c-b114-5e07-b0e3-8af3383bcc41', 'neet_ug', 'Chemistry', 'The d- and f-Block Elements', 'The pair of lanthanoid ions which are diamagnetic is', '[{"id": "a", "text": "Gd³⁺ and Eu³⁺"}, {"id": "b", "text": "Pm³⁺ and Sm³⁺"}, {"id": "c", "text": "Ce⁴⁺ and Yb²⁺"}, {"id": "d", "text": "Ce³⁺ and Eu²⁺"}]'::jsonb, 'c', 'Ce⁴⁺ (4f⁰) and Yb²⁺ (4f¹⁴) have no unpaired electrons.', 'Ce (Z = 58) is [Xe]4f¹5d¹6s², so Ce⁴⁺ is 4f⁰. Yb (Z = 70) is [Xe]4f¹⁴6s², so Yb²⁺ is 4f¹⁴. Both have no unpaired electrons and are diamagnetic. The other pairs all contain partly filled 4f shells.', '{"a": "Gd³⁺ is 4f⁷ and Eu³⁺ is 4f⁶: both paramagnetic.", "b": "Pm³⁺ is 4f⁴ and Sm³⁺ is 4f⁵: both paramagnetic.", "d": "Ce³⁺ is 4f¹ and Eu²⁺ is 4f⁷: both paramagnetic."}'::jsonb, 'f⁰ (La³⁺, Ce⁴⁺) and f¹⁴ (Yb²⁺, Lu³⁺) lanthanoid ions are diamagnetic and colourless.', 'easy', true, 2024, NULL, 'NEET UG 2024 (NTA) · answer verified by UG Prep', NULL),
('7a4a2c56-a81c-5b84-a329-ef022154e9b6', 'neet_ug', 'Botany', 'Sexual Reproduction in Flowering Plants', 'Identify the set of correct statements:
A. The flowers of Vallisneria are colourful and produce nectar
B. The flowers of waterlily are not pollinated by water.
C. In most of water-pollinated species, the pollen grains are protected from wetting.
D. Pollen grains of some hydrophytes are long and ribbon like.
E. In some hydrophytes, the pollen grains are carried passively inside water.
Choose the correct answer from the options given below:', '[{"id": "a", "text": "A, C, D and E only"}, {"id": "b", "text": "B, C, D and E only"}, {"id": "c", "text": "C, D and E only"}, {"id": "d", "text": "A, B, C and D only"}]'::jsonb, 'b', 'Only A is wrong: water-pollinated flowers such as Vallisneria are dull and nectarless.', 'Water-pollinated flowers do not need to attract animals, so Vallisneria flowers are neither colourful nor nectar-producing (A false). Waterlily and water hyacinth are aquatic but pollinated by insects or wind (B true). Pollen of water-pollinated plants has a mucilaginous covering against wetting (C true), seagrass pollen is long and ribbon-like (D true), and in Zostera-like plants pollen is carried passively inside water (E true).', '{"a": "Includes A, which is false.", "c": "Omits B, which is true.", "d": "Includes A and omits E."}'::jsonb, 'Water-pollinated flowers lack colour and nectar; pollen is mucilage-coated against wetting.', 'med', true, 2024, NULL, 'NEET UG 2024 (NTA) · answer verified by UG Prep', NULL),
('3051ea07-93a6-5cae-9d6b-6962e7ab3736', 'neet_ug', 'Botany', 'Biomolecules', 'Inhibition of Succinic dehydrogenase enzyme by malonate is a classical example of:', '[{"id": "a", "text": "Competitive inhibition"}, {"id": "b", "text": "Enzyme activation"}, {"id": "c", "text": "Cofactor inhibition"}, {"id": "d", "text": "Feedback inhibition"}]'::jsonb, 'a', 'Malonate resembles succinate and competes for the active site: competitive inhibition.', 'Malonate is structurally similar to succinate, the substrate of succinic dehydrogenase. It binds the active site and prevents substrate binding, lowering enzyme activity, which is the textbook case of competitive inhibition.', '{"b": "The enzyme is inhibited, not activated.", "c": "Malonate does not act on a cofactor; it competes with substrate.", "d": "Feedback inhibition is by an end product of a pathway, not a substrate analogue."}'::jsonb, 'Competitive inhibitors are substrate analogues that bind the active site.', 'easy', true, 2024, NULL, 'NEET UG 2024 (NTA) · answer verified by UG Prep', NULL),
('0422d4ef-b226-5b81-b56c-a93ea759c845', 'neet_ug', 'Botany', 'Anatomy of Flowering Plants', 'Bulliform cells are responsible for', '[{"id": "a", "text": "Increased photosynthesis in monocots."}, {"id": "b", "text": "Providing large spaces for storage of sugars."}, {"id": "c", "text": "Inward curling of leaves in monocots."}, {"id": "d", "text": "Protecting the plant from salt stress."}]'::jsonb, 'c', 'Flaccid bulliform cells make grass leaves roll inward to cut water loss.', 'Bulliform cells are large, empty, colourless adaxial epidermal cells of grass leaves. When they are turgid the leaf is flat; under water stress they become flaccid and the leaf curls inward, reducing transpiration.', '{"a": "They are colourless and do not photosynthesise.", "b": "They are not storage cells for sugars.", "d": "Their role relates to water stress, not salt stress."}'::jsonb, 'Bulliform cells occur on the adaxial epidermis of grass leaves.', 'easy', true, 2024, NULL, 'NEET UG 2024 (NTA) · answer verified by UG Prep', NULL),
('96275851-b4c0-5c90-8543-3678b7a89d8c', 'neet_ug', 'Botany', 'Photosynthesis in Higher Plants', 'Which of the following are required for the dark reaction of photosynthesis?
A. Light
B. Chlorophyll
C. CO₂
D. ATP
E. NADPH
Choose the correct answer from the options given below:', '[{"id": "a", "text": "C, D and E only"}, {"id": "b", "text": "D and E only"}, {"id": "c", "text": "A, B and C only"}, {"id": "d", "text": "B, C and D only"}]'::jsonb, 'a', 'The Calvin cycle needs CO₂, ATP and NADPH, but not light or chlorophyll directly.', 'The biosynthetic (dark) phase fixes CO₂ by RuBisCO and reduces it using the ATP and NADPH made in the light reaction. Light and chlorophyll are needed only for the photochemical phase.', '{"b": "Omits CO₂, the substrate being fixed.", "c": "Light and chlorophyll are not directly used in the dark reaction.", "d": "Chlorophyll is not required and NADPH is omitted."}'::jsonb, 'The dark reaction depends on light only indirectly, through ATP and NADPH.', 'easy', true, 2024, NULL, 'NEET UG 2024 (NTA) · answer verified by UG Prep', NULL),
('060351af-e85a-5931-a4d2-4a1f72918ca4', 'neet_ug', 'Botany', 'Anatomy of Flowering Plants', 'Formation of interfascicular cambium from fully developed parenchyma cells is an example for', '[{"id": "a", "text": "Dedifferentiation"}, {"id": "b", "text": "Maturation"}, {"id": "c", "text": "Differentiation"}, {"id": "d", "text": "Redifferentiation"}]'::jsonb, 'a', 'Permanent parenchyma regaining the power to divide is dedifferentiation.', 'Interfascicular cambium arises from medullary ray parenchyma cells, which were mature and non-dividing. Regaining meristematic activity by such cells is dedifferentiation; the secondary xylem and phloem they later produce are products of redifferentiation.', '{"b": "Maturation is the attainment of a final form, not a return to dividing.", "c": "Differentiation is the specialisation of meristematic cells, the opposite direction.", "d": "Redifferentiation describes the cells produced by the new meristem losing division again."}'::jsonb, 'Interfascicular cambium and cork cambium arise by dedifferentiation.', 'easy', true, 2024, NULL, 'NEET UG 2024 (NTA) · answer verified by UG Prep', NULL),
('0bdd338c-f2a3-56dd-9672-cc99fafacfa1', 'neet_ug', 'Botany', 'Biotechnology: Principles and Processes', 'Hind II always cuts DNA molecules at a particular point called recognition sequence and it consists of:', '[{"id": "a", "text": "4 bp"}, {"id": "b", "text": "10 bp"}, {"id": "c", "text": "8 bp"}, {"id": "d", "text": "6 bp"}]'::jsonb, 'd', 'Hind II recognises a specific six-base-pair sequence.', 'Hind II, the first restriction endonuclease isolated, always cuts DNA at a particular point by recognising a specific sequence of six base pairs, called its recognition sequence.', '{"a": "Four-base cutters exist but Hind II is not one.", "b": "No such 10 bp site is given for Hind II.", "c": "Hind II''s site is 6 bp, not 8 bp."}'::jsonb, 'Restriction enzymes recognise palindromic sequences; Hind II cuts at a 6 bp site.', 'easy', true, 2024, NULL, 'NEET UG 2024 (NTA) · answer verified by UG Prep', NULL),
('4fd4c811-5eb2-57db-8cee-2fe79c0ace67', 'neet_ug', 'Botany', 'Biodiversity and Conservation', 'Tropical regions show greatest level of species richness because
A. Tropical latitudes have remained relatively undisturbed for millions of years, hence more time was available for species diversification.
B. Tropical environments are more seasonal.
C. More solar energy is available in tropics.
D. Constant environments promote niche specialization.
E. Tropical environments are constant and predictable.
Choose the correct answer from the options given below:', '[{"id": "a", "text": "A, B and E only"}, {"id": "b", "text": "A, B and D only"}, {"id": "c", "text": "A, C, D and E only"}, {"id": "d", "text": "A and B only"}]'::jsonb, 'c', 'Tropics are old, undisturbed, less seasonal and receive more solar energy, so all except B apply.', 'The tropics escaped glaciations and had long evolutionary time (A), they are less seasonal, more constant and predictable, which favours niche specialisation (D, E), and they receive more solar energy, supporting higher productivity (C). B is wrong because temperate regions are the more seasonal ones.', '{"a": "Includes B, which is false.", "b": "Includes B and omits C and E.", "d": "Includes B and omits true reasons."}'::jsonb, 'Species diversity decreases from the equator towards the poles.', 'easy', true, 2024, NULL, 'NEET UG 2024 (NTA) · answer verified by UG Prep', NULL),
('b04a994a-193e-5135-8879-321615c79841', 'neet_ug', 'Botany', 'Biological Classification', 'Which one of the following is not a criterion for classification of fungi?', '[{"id": "a", "text": "Mode of spore formation"}, {"id": "b", "text": "Fruiting body"}, {"id": "c", "text": "Morphology of mycelium"}, {"id": "d", "text": "Mode of nutrition"}]'::jsonb, 'd', 'Fungi are classified by mycelium, spore formation and fruiting body, not by nutrition.', 'NCERT states that the morphology of the mycelium, the mode of spore formation and the fruiting bodies form the basis for dividing kingdom Fungi into classes. Nearly all fungi are heterotrophic, so mode of nutrition does not separate them.', '{"a": "Mode of spore formation is a classification criterion.", "b": "Fruiting body type is a classification criterion.", "c": "Morphology of mycelium is a classification criterion."}'::jsonb, 'Fungal classes: Phycomycetes, Ascomycetes, Basidiomycetes, Deuteromycetes.', 'easy', true, 2024, NULL, 'NEET UG 2024 (NTA) · answer verified by UG Prep', NULL),
('9489d954-e730-5e7a-8a16-91e91d15cd0e', 'neet_ug', 'Botany', 'Photosynthesis in Higher Plants', 'How many molecules of ATP and NADPH are required for every molecule of CO₂ fixed in the Calvin cycle?', '[{"id": "a", "text": "3 molecules of ATP and 3 molecules of NADPH"}, {"id": "b", "text": "3 molecules of ATP and 2 molecules of NADPH"}, {"id": "c", "text": "2 molecules of ATP and 3 molecules of NADPH"}, {"id": "d", "text": "2 molecules of ATP and 2 molecules of NADPH"}]'::jsonb, 'b', 'Each CO₂ fixed costs 3 ATP and 2 NADPH.', 'Fixing one CO₂ uses 2 ATP and 2 NADPH to reduce two 3-PGA to triose phosphate, plus 1 ATP to regenerate RuBP. So 3 ATP and 2 NADPH per CO₂; one glucose (6 CO₂) needs 18 ATP and 12 NADPH.', '{"a": "Only 2 NADPH are used per CO₂.", "c": "Reverses the true ratio.", "d": "Ignores the ATP used for RuBP regeneration."}'::jsonb, 'One glucose via Calvin cycle needs 6 turns, 18 ATP and 12 NADPH.', 'easy', true, 2024, NULL, 'NEET UG 2024 (NTA) · answer verified by UG Prep', NULL),
('1c2fce1b-35c0-5dc9-b264-4786fdbf98bf', 'neet_ug', 'Botany', 'Biodiversity and Conservation', 'These are regarded as major causes of biodiversity loss:
A. Over exploitation
B. Co-extinction
C. Mutation
D. Habitat loss and fragmentation
E. Migration
Choose the correct option:', '[{"id": "a", "text": "A, B and E only"}, {"id": "b", "text": "A, B and D only"}, {"id": "c", "text": "A, C and D only"}, {"id": "d", "text": "A, B, C and D only"}]'::jsonb, 'b', 'Over-exploitation, co-extinction and habitat loss are among the ''Evil Quartet''.', 'The four major causes of biodiversity loss are habitat loss and fragmentation, over-exploitation, alien species invasions and co-extinction. Mutation and migration are not listed as causes of biodiversity loss.', '{"a": "Migration is not a cause of biodiversity loss.", "c": "Mutation is not a cause and co-extinction is omitted.", "d": "Includes mutation."}'::jsonb, 'Habitat loss and fragmentation is the most important cause of extinction.', 'easy', true, 2024, NULL, 'NEET UG 2024 (NTA) · answer verified by UG Prep', NULL),
('e1be245c-99bf-5243-831c-2b74b255001d', 'neet_ug', 'Botany', 'Biotechnology and its Applications', 'The capacity to generate a whole plant from any cell of the plant is called:', '[{"id": "a", "text": "Differentiation"}, {"id": "b", "text": "Somatic hybridization"}, {"id": "c", "text": "Totipotency"}, {"id": "d", "text": "Micropropagation"}]'::jsonb, 'c', 'Totipotency is the ability of a single cell to regenerate a whole plant.', 'Plant tissue culture relies on the fact that any living plant cell or explant can give rise to an entire plant; this capacity is called totipotency.', '{"a": "Differentiation is specialisation of cells, not regeneration of a plant.", "b": "Somatic hybridisation is fusion of protoplasts of two plants.", "d": "Micropropagation is the technique that exploits totipotency to produce many plants."}'::jsonb, 'Explant: any part of a plant taken out and grown in vitro.', 'easy', true, 2024, NULL, 'NEET UG 2024 (NTA) · answer verified by UG Prep', NULL),
('f92489d5-2da0-5ad5-8876-6e92c6f6df6f', 'neet_ug', 'Botany', 'Organisms and Populations', 'The equation of Verhulst-Pearl logistic growth is dN/dt = rN[(K − N)/K].
From this equation, K indicates:', '[{"id": "a", "text": "Carrying capacity"}, {"id": "b", "text": "Population density"}, {"id": "c", "text": "Intrinsic rate of natural increase"}, {"id": "d", "text": "Biotic potential"}]'::jsonb, 'a', 'K is the carrying capacity, the maximum population the environment can support.', 'In logistic growth, N is population density, r the intrinsic rate of natural increase, and K the carrying capacity. As N approaches K the factor (K − N)/K approaches zero and growth stops, giving a sigmoid curve.', '{"b": "Population density is N.", "c": "The intrinsic rate of natural increase is r.", "d": "Biotic potential is the maximal reproductive capacity, not K."}'::jsonb, 'Logistic growth gives a sigmoid curve with an asymptote at K.', 'easy', true, 2024, NULL, 'NEET UG 2024 (NTA) · answer verified by UG Prep', NULL),
('faeeb5ba-7590-5c7d-939d-aa1d6e59a0c6', 'neet_ug', 'Botany', 'Cell Cycle and Cell Division', 'Spindle fibers attach to kinetochores of chromosomes during', '[{"id": "a", "text": "Anaphase"}, {"id": "b", "text": "Telophase"}, {"id": "c", "text": "Prophase"}, {"id": "d", "text": "Metaphase"}]'::jsonb, 'd', 'NCERT lists spindle fibre attachment to kinetochores as a key feature of metaphase.', 'After the nuclear envelope breaks down, spindle fibres attach to the kinetochores of chromosomes, which then align at the metaphase plate. NCERT gives this attachment as a key feature of metaphase.', '{"a": "In anaphase the attached fibres shorten and pull chromatids apart.", "b": "In telophase chromosomes decondense at the poles.", "c": "In prophase the spindle only begins to assemble; the nuclear envelope is still present."}'::jsonb, 'Metaphase is the best stage for studying chromosome morphology.', 'easy', true, 2024, NULL, 'NEET UG 2024 (NTA) · answer verified by UG Prep', NULL),
('b7bb7018-b4f7-5c1e-9c80-f9cf0fde5495', 'neet_ug', 'Botany', 'Morphology of Flowering Plants', 'Identify the type of flowers based on the position of calyx, corolla and androecium with respect to the ovary from the given figures (a) and (b)', '[{"id": "a", "text": "(a) Perigynous; (b) Epigynous"}, {"id": "b", "text": "(a) Perigynous; (b) Perigynous"}, {"id": "c", "text": "(a) Epigynous; (b) Hypogynous"}, {"id": "d", "text": "(a) Hypogynous; (b) Epigynous"}]'::jsonb, 'd', 'In (a) the ovary sits above the other whorls (hypogynous); in (b) it is sunk in the thalamus with the whorls above it (epigynous).', 'In (a) the gynoecium is at the highest point and sepals, petals and stamens arise below it, so the ovary is superior and the flower hypogynous. In (b) the thalamus grows up around the ovary and the other whorls arise near its top, so the ovary is treated as inferior and the flower epigynous. Only option (4) has (a) as hypogynous.', '{"a": "(a) is not perigynous: its whorls arise below the ovary.", "b": "(a) is clearly hypogynous.", "c": "Reverses the positions shown."}'::jsonb, 'Hypogynous: mustard, china rose, brinjal; perigynous: plum, rose, peach; epigynous: guava, cucumber, sunflower ray florets.', 'med', true, 2024, NULL, 'NEET UG 2024 (NTA) · answer verified by UG Prep', '/pyq/ug/2024/116.webp'),
('f1a26ed1-545f-5e47-af7a-bf4de54e0d60', 'neet_ug', 'Botany', 'Biological Classification', 'Match List I with List II
List I | List II
A. Rhizopus | I. Mushroom
B. Ustilago | II. Smut fungus
C. Puccinia | III. Bread mould
D. Agaricus | IV. Rust fungus
Choose the correct answer from the options given below:', '[{"id": "a", "text": "A-III, B-II, C-I, D-IV"}, {"id": "b", "text": "A-IV, B-III, C-II, D-I"}, {"id": "c", "text": "A-III, B-II, C-IV, D-I"}, {"id": "d", "text": "A-I, B-III, C-II, D-IV"}]'::jsonb, 'c', 'Rhizopus bread mould, Ustilago smut, Puccinia rust, Agaricus mushroom.', 'Rhizopus is the common bread mould (Phycomycetes). Ustilago causes smut and Puccinia causes rust (Basidiomycetes). Agaricus is the mushroom.', '{"a": "Swaps Puccinia and Agaricus.", "b": "Wrong for every pair.", "d": "Rhizopus is not a mushroom."}'::jsonb, 'Basidiomycetes include mushrooms, bracket fungi, smuts and rusts.', 'easy', true, 2024, NULL, 'NEET UG 2024 (NTA) · answer verified by UG Prep', NULL),
('8cb41609-1c50-5010-9e1b-5f128a198046', 'neet_ug', 'Botany', 'Principles of Inheritance and Variation', 'In a plant, black seed color (BB/Bb) is dominant over white seed color (bb). In order to find out the genotype of the black seed plant, with which of the following genotype will you cross it?', '[{"id": "a", "text": "Bb"}, {"id": "b", "text": "BB/Bb"}, {"id": "c", "text": "BB"}, {"id": "d", "text": "bb"}]'::jsonb, 'd', 'A test cross with the homozygous recessive (bb) reveals the unknown genotype.', 'Crossing the black plant with bb gives all black progeny if it is BB, and a 1 : 1 ratio of black to white if it is Bb. Because the recessive parent contributes only b, the progeny phenotypes directly show the unknown parent''s gametes.', '{"a": "A heterozygous tester gives ambiguous ratios.", "b": "Not a defined tester genotype.", "c": "Crossing with BB gives all black progeny whatever the unknown genotype."}'::jsonb, 'Test cross ratio for a heterozygote: monohybrid 1:1, dihybrid 1:1:1:1.', 'easy', true, 2024, NULL, 'NEET UG 2024 (NTA) · answer verified by UG Prep', NULL),
('45dbd76b-6e99-506f-87f4-c105ba53ead1', 'neet_ug', 'Botany', 'Principles of Inheritance and Variation', 'A pink flowered Snapdragon plant was crossed with a red flowered Snapdragon plant. What type of phenotype/s is/are expected in the progeny?', '[{"id": "a", "text": "Only pink flowered plants"}, {"id": "b", "text": "Red, Pink as well as white flowered plants"}, {"id": "c", "text": "Only red flowered plants"}, {"id": "d", "text": "Red flowered as well as pink flowered plants"}]'::jsonb, 'd', 'Rr × RR gives RR (red) and Rr (pink) in a 1 : 1 ratio.', 'Flower colour in snapdragon shows incomplete dominance: RR red, Rr pink, rr white. Pink (Rr) × red (RR) gives gametes R, r × R, so the progeny are 1/2 RR red and 1/2 Rr pink. No white (rr) can arise because the red parent gives only R.', '{"a": "Half the progeny are RR and red.", "b": "White (rr) needs r from both parents.", "c": "Half the progeny are Rr and pink."}'::jsonb, 'Incomplete dominance: F₂ phenotypic and genotypic ratios are both 1:2:1.', 'easy', true, 2024, NULL, 'NEET UG 2024 (NTA) · answer verified by UG Prep', NULL),
('c05bc6e6-5ca6-55eb-b4ab-b81eaf4cdb9f', 'neet_ug', 'Botany', 'Principles of Inheritance and Variation', 'Match List I with List II
List I | List II
A. Two or more alternative forms of a gene | I. Back cross
B. Cross of F₁ progeny with homozygous recessive parent | II. Ploidy
C. Cross of F₁ progeny with any of the parents | III. Allele
D. Number of chromosome sets in plant | IV. Test cross
Choose the correct answer from the options given below:', '[{"id": "a", "text": "A-III, B-IV, C-I, D-II"}, {"id": "b", "text": "A-IV, B-III, C-II, D-I"}, {"id": "c", "text": "A-I, B-II, C-III, D-IV"}, {"id": "d", "text": "A-II, B-I, C-III, D-IV"}]'::jsonb, 'a', 'Allele, test cross, back cross, ploidy.', 'Alternative forms of a gene are alleles. Crossing F₁ with the recessive parent is a test cross, which is a special back cross; crossing F₁ with either parent is a back cross. The number of chromosome sets is ploidy.', '{"b": "Swaps allele and test cross.", "c": "Wrong for every pair.", "d": "Ploidy does not mean alternative forms of a gene."}'::jsonb, 'Every test cross is a back cross, but not every back cross is a test cross.', 'easy', true, 2024, NULL, 'NEET UG 2024 (NTA) · answer verified by UG Prep', NULL),
('d9b3c962-5569-5a20-9131-25d4c5c9cba9', 'neet_ug', 'Botany', 'Biomolecules', 'Lecithin, a small molecular weight organic compound found in living tissues, is an example of:', '[{"id": "a", "text": "Glycerides"}, {"id": "b", "text": "Carbohydrates"}, {"id": "c", "text": "Amino acids"}, {"id": "d", "text": "Phospholipids"}]'::jsonb, 'd', 'Lecithin is a phospholipid of cell membranes.', 'Lecithin (phosphatidylcholine) contains glycerol esterified with two fatty acids and a phosphate linked to choline, which makes it a phospholipid found in cell membranes.', '{"a": "Simple glycerides lack the phosphate group.", "b": "Lecithin is a lipid, not a sugar.", "c": "Lecithin is not an amino acid."}'::jsonb, 'Lecithin is a common phospholipid of cell membranes.', 'easy', true, 2024, NULL, 'NEET UG 2024 (NTA) · answer verified by UG Prep', NULL),
('a191b9d7-05b9-5a2e-b5d5-b7ef966d058b', 'neet_ug', 'Botany', 'Microbes in Human Welfare', 'Match List I with List II
List I | List II
A. Clostridium butylicum | I. Ethanol
B. Saccharomyces cerevisiae | II. Streptokinase
C. Trichoderma polysporum | III. Butyric acid
D. Streptococcus sp. | IV. Cyclosporin-A
Choose the correct answer from the options given below:', '[{"id": "a", "text": "A-III, B-I, C-IV, D-II"}, {"id": "b", "text": "A-IV, B-I, C-III, D-II"}, {"id": "c", "text": "A-III, B-I, C-II, D-IV"}, {"id": "d", "text": "A-II, B-IV, C-III, D-I"}]'::jsonb, 'a', 'Clostridium butyric acid, yeast ethanol, Trichoderma cyclosporin A, Streptococcus streptokinase.', 'Clostridium butylicum produces butyric acid, Saccharomyces cerevisiae ferments sugars to ethanol, Trichoderma polysporum yields the immunosuppressant cyclosporin A, and Streptococcus produces the clot buster streptokinase.', '{"b": "Clostridium does not produce cyclosporin A.", "c": "Swaps Trichoderma and Streptococcus products.", "d": "Wrong for every pair."}'::jsonb, 'Statins come from Monascus purpureus; citric acid from Aspergillus niger.', 'easy', true, 2024, NULL, 'NEET UG 2024 (NTA) · answer verified by UG Prep', NULL),
('f5572ba3-de8a-59e8-ac37-16ec78756c91', 'neet_ug', 'Botany', 'Morphology of Flowering Plants', 'Which of the following is an example of actinomorphic flower?', '[{"id": "a", "text": "Pisum"}, {"id": "b", "text": "Sesbania"}, {"id": "c", "text": "Datura"}, {"id": "d", "text": "Cassia"}]'::jsonb, 'c', 'Datura flowers are radially symmetrical.', 'An actinomorphic flower can be divided into two equal halves through any radial plane through the centre. Datura, mustard and chilli are actinomorphic, while pea, gulmohur, bean and Cassia are zygomorphic.', '{"a": "Pisum has a zygomorphic papilionaceous flower.", "b": "Sesbania belongs to Fabaceae and is zygomorphic.", "d": "Cassia is cited by NCERT as zygomorphic."}'::jsonb, 'Canna is asymmetric; Fabaceae flowers are zygomorphic.', 'easy', true, 2024, NULL, 'NEET UG 2024 (NTA) · answer verified by UG Prep', NULL),
('1a0f800d-032b-5e69-9f7e-ae85074ad427', 'neet_ug', 'Botany', 'Molecular Basis of Inheritance', 'A transcription unit in DNA is defined primarily by the three regions in DNA and these are with respect to upstream and downstream end;', '[{"id": "a", "text": "Inducer, Repressor, Structural gene"}, {"id": "b", "text": "Promotor, Structural gene, Terminator"}, {"id": "c", "text": "Repressor, Operator gene, Structural gene"}, {"id": "d", "text": "Structural gene, Transposons, Operator gene"}]'::jsonb, 'b', 'Promoter upstream, structural gene in the middle, terminator downstream.', 'A transcription unit has a promoter towards the 5′ (upstream) end of the coding strand, the structural gene, and a terminator towards the 3′ (downstream) end that ends transcription.', '{"a": "Inducer and repressor are regulatory molecules, not DNA regions of a transcription unit.", "c": "Repressor is a protein and operator belongs to operon regulation.", "d": "Transposons are not part of a transcription unit."}'::jsonb, 'The promoter is the binding site for RNA polymerase.', 'easy', true, 2024, NULL, 'NEET UG 2024 (NTA) · answer verified by UG Prep', NULL),
('1924bdf3-09dd-5f59-b3c4-37f4895ae8e6', 'neet_ug', 'Botany', 'Biotechnology: Principles and Processes', 'What is the fate of piece of DNA carrying only gene of interest which is transferred into an alien organism?
A. The piece of DNA would be able to multiply itself independently in the progeny cells of the organisms.
B. It may get integrated into the genome of the recipient.
C. It may multiply and be inherited along with the host DNA.
D. The alien piece of DNA is not an integrated part of chromosome.
E. It shows ability to replicate.
Choose the correct answer from the options given below:', '[{"id": "a", "text": "B and C only"}, {"id": "b", "text": "A and E only"}, {"id": "c", "text": "A and B only"}, {"id": "d", "text": "D and E only"}]'::jsonb, 'a', 'Without an ori it cannot replicate alone, but it may integrate and be inherited with host DNA.', 'A DNA fragment carrying only the gene of interest has no origin of replication, so it cannot multiply on its own in progeny cells (A and E false). If it integrates into the recipient genome it can replicate and be inherited along with host DNA (B and C true); D contradicts integration.', '{"b": "A and E describe autonomous replication, which needs an ori.", "c": "A is false.", "d": "Neither D nor E is the correct fate."}'::jsonb, 'Cloning vectors need ori, selectable marker and cloning sites.', 'med', true, 2024, NULL, 'NEET UG 2024 (NTA) · answer verified by UG Prep', NULL),
('a3669b5f-fd8d-5b1b-991c-01811818aba9', 'neet_ug', 'Botany', 'Plant Growth and Development', 'Auxin is used by gardeners to prepare weed free lawns. But no damage is caused to grass as auxin;', '[{"id": "a", "text": "does not affect mature monocotyledonous plants."}, {"id": "b", "text": "can help in cell division in grasses, to produce growth."}, {"id": "c", "text": "promotes apical dominance."}, {"id": "d", "text": "promotes abscission of mature leaves only."}]'::jsonb, 'a', 'Synthetic auxins like 2,4-D kill dicot weeds but spare mature monocots.', '2,4-D is widely used to kill dicotyledonous weeds; it does not affect mature monocotyledonous plants. Grass is a monocot, so a lawn can be cleared of broad-leaved weeds without harming the grass.', '{"b": "The selectivity is not due to stimulating cell division in grass.", "c": "Apical dominance does not explain selective weed killing.", "d": "Abscission of mature leaves does not explain the safety of grass."}'::jsonb, '2,4-D is a selective herbicide for dicot weeds.', 'easy', true, 2024, NULL, 'NEET UG 2024 (NTA) · answer verified by UG Prep', NULL),
('789ce600-35ca-5667-a62a-c58a2d456adf', 'neet_ug', 'Botany', 'Biomolecules', 'The cofactor of the enzyme carboxypeptidase is:', '[{"id": "a", "text": "Flavin"}, {"id": "b", "text": "Haem"}, {"id": "c", "text": "Zinc"}, {"id": "d", "text": "Niacin"}]'::jsonb, 'c', 'Carboxypeptidase uses zinc as its metal cofactor.', 'Metal ions act as cofactors by forming coordination bonds with the active site and substrate. Zinc is the cofactor for the proteolytic enzyme carboxypeptidase.', '{"a": "Flavins are coenzymes of flavoproteins.", "b": "Haem is the prosthetic group of peroxidase and catalase.", "d": "Niacin is a vitamin forming NAD/NADP coenzymes."}'::jsonb, 'Haem is the prosthetic group of peroxidase and catalase.', 'easy', true, 2024, NULL, 'NEET UG 2024 (NTA) · answer verified by UG Prep', NULL),
('55f3fbaf-5d41-5543-8179-49d6ebb0478b', 'neet_ug', 'Botany', 'Molecular Basis of Inheritance', 'The lactose present in the growth medium of bacteria is transported to the cell by the action of', '[{"id": "a", "text": "Permease"}, {"id": "b", "text": "Polymerase"}, {"id": "c", "text": "Beta-galactosidase"}, {"id": "d", "text": "Acetylase"}]'::jsonb, 'a', 'The lac y gene product permease increases cell permeability to β-galactosides.', 'In the lac operon, z codes β-galactosidase (hydrolyses lactose), y codes permease (lets lactose enter the cell) and a codes transacetylase. Lactose uptake depends on permease.', '{"b": "Polymerase transcribes the operon; it does not transport lactose.", "c": "β-galactosidase hydrolyses lactose once inside.", "d": "Transacetylase does not transport lactose."}'::jsonb, 'Lactose (allolactose) is the inducer of the lac operon.', 'easy', true, 2024, NULL, 'NEET UG 2024 (NTA) · answer verified by UG Prep', NULL),
('a0452476-86d6-55d8-95b9-442dc2c48192', 'neet_ug', 'Botany', 'Principles of Inheritance and Variation', 'Which one of the following can be explained on the basis of Mendel''s Law of Dominance?
A. Out of one pair of factors one is dominant and the other is recessive.
B. Alleles do not show any expression and both the characters appear as such in F₂ generation.
C. Factors occur in pair in normal diploid plants.
D. The discrete unit controlling a particular character is called factor.
E. The expression of only one of the parental characters is found in a monohybrid cross.
Choose the correct answer from the options given below:', '[{"id": "a", "text": "B, C and D only"}, {"id": "b", "text": "A, B, C, D and E"}, {"id": "c", "text": "A, B and C only"}, {"id": "d", "text": "A, C, D and E only"}]'::jsonb, 'd', 'All statements except B fit the law of dominance.', 'NCERT states the law of dominance as: characters are controlled by discrete units called factors (D), factors occur in pairs (C), and in a dissimilar pair one factor dominates the other (A). It explains why only one parental character is expressed in the F₁ of a monohybrid cross (E). B is false because one allele is expressed in a heterozygote.', '{"a": "Includes B and omits A.", "b": "Includes B, which is false.", "c": "Includes B and omits D and E."}'::jsonb, 'The law of dominance explains the 3:1 F₂ ratio and the uniform F₁.', 'med', true, 2024, NULL, 'NEET UG 2024 (NTA) · answer verified by UG Prep', NULL),
('3c8d42a4-0d25-58ff-aaa2-773e52f3aff5', 'neet_ug', 'Botany', 'Biotechnology and its Applications', 'Given below are two statements:
Statement I: Bt toxins are insect group specific and coded by a gene cry IAc.
Statement II: Bt toxin exists as inactive protoxin in B. thuringiensis. However, after ingestion by the insect the inactive protoxin gets converted into active form due to acidic pH of the insect gut.
In the light of the above statements, choose the correct answer from the options given below:', '[{"id": "a", "text": "Statement I is true but Statement II is false."}, {"id": "b", "text": "Statement I is false but Statement II is true."}, {"id": "c", "text": "Both Statement I and Statement II are true."}, {"id": "d", "text": "Both Statement I and Statement II are false."}]'::jsonb, 'a', 'Bt protoxin is activated by the alkaline, not acidic, pH of the insect gut.', 'Bt toxin proteins are specific to insect groups and are coded by cry genes such as cryIAc, which controls cotton bollworms, so Statement I is accepted as true. The protoxin is solubilised and activated by the alkaline pH of the insect gut, so Statement II is false.', '{"b": "Statement II wrongly says acidic pH.", "c": "Statement II is false.", "d": "Statement I is true."}'::jsonb, 'cryIAc and cryIIAb control cotton bollworms; cryIAb controls corn borer.', 'med', true, 2024, NULL, 'NEET UG 2024 (NTA) · answer verified by UG Prep', NULL),
('5122fff3-bafb-55e4-a9ab-279d7d9bec3e', 'neet_ug', 'Botany', 'Anatomy of Flowering Plants', 'Given below are two statements:
Statement I: Parenchyma is living but collenchyma is dead tissue.
Statement II: Gymnosperms lack xylem vessels but presence of xylem vessels is the characteristic of angiosperms.
In the light of the above statements, choose the correct answer from the options given below:', '[{"id": "a", "text": "Statement I is true but Statement II is false."}, {"id": "b", "text": "Statement I is false but Statement II is true."}, {"id": "c", "text": "Both Statement I and Statement II are true."}, {"id": "d", "text": "Both Statement I and Statement II are false."}]'::jsonb, 'b', 'Collenchyma is living, so I is false; vessels are characteristic of angiosperms, so II is true.', 'Both parenchyma and collenchyma are living simple tissues; sclerenchyma is the dead one, so Statement I is false. Xylem vessels are a characteristic feature of angiosperms and are absent in gymnosperms, so Statement II is true.', '{"a": "Statement I is false.", "c": "Statement I is false.", "d": "Statement II is true."}'::jsonb, 'Sclerenchyma is dead; collenchyma has corner pectin thickening.', 'easy', true, 2024, NULL, 'NEET UG 2024 (NTA) · answer verified by UG Prep', NULL),
('8397234e-da5c-5765-becf-c53d6e7adbc4', 'neet_ug', 'Botany', 'Cell Cycle and Cell Division', 'Given below are two Statements:
Statement I: Chromosomes become gradually visible under light microscope during leptotene stage.
Statement II: The beginning of diplotene stage is recognized by dissolution of synaptonemal complex.
In the light of the above statements, choose the correct answer from the options given below:', '[{"id": "a", "text": "Statement I is true but Statement II is false."}, {"id": "b", "text": "Statement I is false but Statement II is true."}, {"id": "c", "text": "Both Statement I and Statement II are true."}, {"id": "d", "text": "Both Statement I and Statement II are false."}]'::jsonb, 'c', 'Both statements describe meiotic prophase I correctly.', 'In leptotene the chromosomes become gradually visible under the light microscope as compaction continues. Diplotene begins with the dissolution of the synaptonemal complex, after which homologues separate except at chiasmata.', '{"a": "Statement II is also true.", "b": "Statement I is also true.", "d": "Both are true."}'::jsonb, 'Crossing over occurs in pachytene; terminalisation of chiasmata in diakinesis.', 'easy', true, 2024, NULL, 'NEET UG 2024 (NTA) · answer verified by UG Prep', NULL),
('54fccca1-2da4-5a36-bffc-516c97f78b08', 'neet_ug', 'Botany', 'Cell: The Unit of Life', 'Match List-I with List-II.
List-I | List-II
(A) Nucleolus | (I) Site of formation of glycolipid
(B) Centriole | (II) Organization like the cartwheel
(C) Leucoplasts | (III) Site for active ribosomal RNA synthesis
(D) Golgi apparatus | (IV) For storing nutrients
Choose the correct answer from the options given below:', '[{"id": "a", "text": "A-III, B-IV, C-II, D-I"}, {"id": "b", "text": "A-I, B-II, C-III, D-IV"}, {"id": "c", "text": "A-III, B-II, C-IV, D-I"}, {"id": "d", "text": "A-II, B-III, C-I, D-IV"}]'::jsonb, 'c', 'Nucleolus rRNA, centriole cartwheel, leucoplast storage, Golgi glycolipid.', 'The nucleolus is the site of active rRNA synthesis. Centrioles have a cartwheel arrangement of nine peripheral triplets. Leucoplasts are colourless plastids storing nutrients (starch, oils, proteins). Golgi apparatus is the important site of formation of glycoproteins and glycolipids.', '{"a": "Centriole is not a storage organelle.", "b": "Wrong for A, C and D.", "d": "Wrong for every pair."}'::jsonb, 'Amyloplasts store starch, elaioplasts oils, aleuroplasts proteins.', 'easy', true, 2024, NULL, 'NEET UG 2024 (NTA) · answer verified by UG Prep', NULL),
('d76dfba7-d2c5-5cd5-91d5-9e4a9b4ebb90', 'neet_ug', 'Botany', 'Biodiversity and Conservation', 'List of endangered species was released by:', '[{"id": "a", "text": "Foam"}, {"id": "b", "text": "IUCN"}, {"id": "c", "text": "GEAC"}, {"id": "d", "text": "WWF"}]'::jsonb, 'b', 'IUCN publishes the Red List of threatened species.', 'The IUCN Red List documents species at risk of extinction, including endangered ones. GEAC is India''s regulator for GM research and WWF is a conservation NGO, but neither issues the Red List.', '{"a": "FOAM does not publish an endangered species list.", "c": "GEAC regulates genetically modified organisms in India.", "d": "WWF is a conservation NGO, not the publisher of the Red List."}'::jsonb, 'IUCN Red List (2004) records 784 extinctions in the last 500 years.', 'easy', true, 2024, NULL, 'NEET UG 2024 (NTA) · answer verified by UG Prep', NULL),
('322daaa6-3402-50ae-9bdd-5cdf421eadac', 'neet_ug', 'Botany', 'Cell: The Unit of Life', 'The DNA present in chloroplast is:', '[{"id": "a", "text": "Linear, single stranded"}, {"id": "b", "text": "Circular, single stranded"}, {"id": "c", "text": "Linear, double stranded"}, {"id": "d", "text": "Circular, double stranded"}]'::jsonb, 'd', 'Chloroplast DNA is small, circular and double-stranded.', 'Chloroplasts, like mitochondria and prokaryotes, contain small, circular, double-stranded DNA along with 70S ribosomes in the stroma.', '{"a": "cpDNA is neither linear nor single stranded.", "b": "cpDNA is double stranded.", "c": "cpDNA is circular."}'::jsonb, 'Chloroplast stroma has 70S ribosomes and circular dsDNA.', 'easy', true, 2024, NULL, 'NEET UG 2024 (NTA) · answer verified by UG Prep', NULL),
('6d92c671-2328-5fb9-8540-f0fbb1c2188e', 'neet_ug', 'Botany', 'Biotechnology and its Applications', 'Which of the following are fused in somatic hybridization involving two varieties of plants?', '[{"id": "a", "text": "Protoplasts"}, {"id": "b", "text": "Pollens"}, {"id": "c", "text": "Callus"}, {"id": "d", "text": "Somatic embryos"}]'::jsonb, 'a', 'Somatic hybridisation fuses protoplasts of two plants.', 'Cell walls are digested away to obtain naked protoplasts of two varieties, which are then fused to form a hybrid protoplast that can be grown into a somatic hybrid plant, such as the pomato.', '{"b": "Fusion of pollen is not somatic hybridisation.", "c": "Callus is an undifferentiated mass, not the unit fused.", "d": "Somatic embryos are not fused."}'::jsonb, 'Pomato is a somatic hybrid of potato and tomato.', 'easy', true, 2024, NULL, 'NEET UG 2024 (NTA) · answer verified by UG Prep', NULL),
('2bde97dc-1e90-5612-b04e-7d0af9960d2f', 'neet_ug', 'Botany', 'Sexual Reproduction in Flowering Plants', 'Identify the correct description about the given figure:', '[{"id": "a", "text": "Cleistogamous flowers showing autogamy."}, {"id": "b", "text": "Compact inflorescence showing complete autogamy."}, {"id": "c", "text": "Wind pollinated plant inflorescence showing flowers with well exposed stamens."}, {"id": "d", "text": "Water pollinated flowers showing stamens with mucilaginous covering."}]'::jsonb, 'c', 'The spike with dangling, exposed stamens is a wind-pollinated inflorescence.', 'The figure shows a long spike with numerous flowers whose stamens hang out freely, as in the NCERT figure of a wind-pollinated plant. Wind-pollinated flowers have well exposed stamens so that pollen is easily dispersed, often in large feathery inflorescences.', '{"a": "Cleistogamous flowers never open, so stamens would not be exposed.", "b": "Exposed stamens suggest cross-pollination by wind, not complete autogamy.", "d": "Water-pollinated flowers have mucilage-coated pollen, not exposed dangling stamens."}'::jsonb, 'Wind-pollinated flowers: light non-sticky pollen, exposed stamens, feathery stigma.', 'easy', true, 2024, NULL, 'NEET UG 2024 (NTA) · answer verified by UG Prep', '/pyq/ug/2024/138.webp'),
('c71c2ade-5125-5244-9972-babc65780c69', 'neet_ug', 'Botany', 'Plant Growth and Development', 'Spraying sugarcane crop with which of the following plant growth regulators, increases the length of stem, thus, increasing the yield?', '[{"id": "a", "text": "Cytokinin"}, {"id": "b", "text": "Abscisic acid"}, {"id": "c", "text": "Auxin"}, {"id": "d", "text": "Gibberellin"}]'::jsonb, 'd', 'Gibberellins elongate sugarcane stems, raising yield by about 20 tonnes per acre.', 'Sugarcane stores sucrose in its stem. Spraying gibberellins increases internode length, which increases yield by as much as 20 tonnes per acre.', '{"a": "Cytokinins promote cell division and delay senescence.", "b": "ABA is a growth inhibitor.", "c": "Auxins are not used to elongate sugarcane stems for yield."}'::jsonb, 'GA also speeds malting in brewing and induces bolting in rosette plants.', 'easy', true, 2024, NULL, 'NEET UG 2024 (NTA) · answer verified by UG Prep', NULL),
('949d31af-24c7-5d5f-be86-231c212315c2', 'neet_ug', 'Botany', 'Molecular Basis of Inheritance', 'Match List-I with List-II.
List-I | List-II
(A) Frederick Griffith | (I) Genetic code
(B) Francois Jacob & Jacques Monod | (II) Semi-conservative mode of DNA replication
(C) Har Gobind Khorana | (III) Transformation
(D) Meselson & Stahl | (IV) Lac operon
Choose the correct answer from the options given below:', '[{"id": "a", "text": "A-II, B-III, C-IV, D-I"}, {"id": "b", "text": "A-IV, B-I, C-II, D-III"}, {"id": "c", "text": "A-III, B-II, C-I, D-IV"}, {"id": "d", "text": "A-III, B-IV, C-I, D-II"}]'::jsonb, 'd', 'Griffith transformation, Jacob–Monod lac operon, Khorana genetic code, Meselson–Stahl semi-conservative replication.', 'Griffith discovered transformation in Streptococcus pneumoniae. Jacob and Monod proposed the lac operon. Khorana synthesised RNA with defined repeats, helping decipher the genetic code. Meselson and Stahl proved semi-conservative replication using ¹⁵N.', '{"a": "Wrong for every pair.", "b": "Wrong for every pair.", "c": "Swaps Jacob–Monod and Meselson–Stahl."}'::jsonb, 'Meselson and Stahl used ¹⁵NH₄Cl and CsCl density gradient centrifugation.', 'easy', true, 2024, NULL, 'NEET UG 2024 (NTA) · answer verified by UG Prep', NULL),
('04635364-9674-5b1f-a1cd-4bb6f4e5c85e', 'neet_ug', 'Botany', 'Biomolecules', 'Match List-I with List-II.
List-I | List-II
(A) GLUT-4 | (I) Hormone
(B) Insulin | (II) Enzyme
(C) Trypsin | (III) Intercellular ground substances
(D) Collagen | (IV) Enables glucose transport into cell.
Choose the correct answer from the options given below:', '[{"id": "a", "text": "A-II, B-III, C-IV, D-I"}, {"id": "b", "text": "A-III, B-IV, C-I, D-II"}, {"id": "c", "text": "A-IV, B-I, C-II, D-III"}, {"id": "d", "text": "A-I, B-II, C-III, D-IV"}]'::jsonb, 'c', 'GLUT-4 transports glucose, insulin is a hormone, trypsin an enzyme, collagen ground substance.', 'NCERT''s table of protein functions lists GLUT-4 as enabling glucose transport into cells, insulin as a hormone, trypsin as an enzyme and collagen as intercellular ground substance.', '{"a": "Wrong for every pair.", "b": "Wrong for every pair.", "d": "Wrong for every pair."}'::jsonb, 'Collagen is the most abundant protein in animals; RuBisCO in the biosphere.', 'easy', true, 2024, NULL, 'NEET UG 2024 (NTA) · answer verified by UG Prep', NULL),
('0dee99a9-b2dc-51fe-bd78-1dfec923ac8c', 'neet_ug', 'Botany', 'Photosynthesis in Higher Plants', 'Given below are two statements:
Statement I: In C₃ Plants, some O₂ binds RuBisCO, hence CO₂ fixation is decreased.
Statement II: In C₄ plants, mesophyll cells show very little photorespiration while bundle sheath cells do not show photorespiration.
In the light of the above statements, choose the correct answer from the options given below:', '[{"id": "a", "text": "Statement I is true but Statement II is false."}, {"id": "b", "text": "Statement I is false but Statement II is true."}, {"id": "c", "text": "Both Statement I and Statement II are true."}, {"id": "d", "text": "Both Statement I and Statement II are false."}]'::jsonb, 'a', 'I is true; II is false because C₄ mesophyll cells lack RuBisCO, and C₄ plants essentially show no photorespiration.', 'In C₃ plants RuBisCO also binds O₂, and the resulting photorespiration lowers net CO₂ fixation, so Statement I is true. In C₄ plants the mesophyll cells lack RuBisCO, so photorespiration cannot occur there, and the high CO₂ concentration in bundle sheath cells suppresses its oxygenase activity, so NCERT says photorespiration does not occur in C₄ plants. Statement II misdescribes this and is false.', '{"b": "Statement I is true and Statement II is false.", "c": "Statement II is false.", "d": "Statement I is true."}'::jsonb, 'C₄ plants: PEPcase in mesophyll, RuBisCO in bundle sheath (Kranz anatomy).', 'med', true, 2024, NULL, 'NEET UG 2024 (NTA) · answer verified by UG Prep', NULL),
('57dc91a8-7ff7-5a1f-8fc0-3a27e11ee2d3', 'neet_ug', 'Botany', 'Respiration in Plants', 'Identify the step in tricarboxylic acid cycle, which does not involve oxidation of substrate.', '[{"id": "a", "text": "Succinyl-CoA → Succinic acid"}, {"id": "b", "text": "Isocitrate → α-ketoglutaric acid"}, {"id": "c", "text": "Malic acid → Oxaloacetic acid"}, {"id": "d", "text": "Succinic acid → Malic acid"}]'::jsonb, 'a', 'Succinyl-CoA to succinate is the substrate-level phosphorylation step with no oxidation.', 'Converting succinyl-CoA to succinic acid releases CoA and makes one GTP by substrate-level phosphorylation, with no electrons removed. Isocitrate → α-ketoglutarate and malate → oxaloacetate reduce NAD⁺, and succinate → fumarate (then malate) reduces FAD, so all of these are oxidations.', '{"b": "An oxidative decarboxylation that produces NADH.", "c": "Malate dehydrogenase oxidises malate and produces NADH.", "d": "Succinate is oxidised to fumarate, producing FADH₂, before hydration to malate."}'::jsonb, 'One TCA turn: 3 NADH, 1 FADH₂, 1 GTP/ATP.', 'med', true, 2024, NULL, 'NEET UG 2024 (NTA) · answer verified by UG Prep', NULL),
('035eb5c5-b2d6-50e6-ab95-641922196fe9', 'neet_ug', 'Botany', 'Respiration in Plants', 'Match List-I with List-II.
List-I | List-II
(A) Citric acid cycle | (I) Cytoplasm
(B) Glycolysis | (II) Mitochondrial matrix
(C) Electron transport system | (III) Intermembrane space of mitochondria
(D) Proton gradient | (IV) Inner mitochondrial membrane
Choose the correct answer from the options given below:', '[{"id": "a", "text": "A-III, B-IV, C-I, D-II"}, {"id": "b", "text": "A-IV, B-III, C-II, D-I"}, {"id": "c", "text": "A-I, B-II, C-III, D-IV"}, {"id": "d", "text": "A-II, B-I, C-IV, D-III"}]'::jsonb, 'd', 'TCA in matrix, glycolysis in cytoplasm, ETS in inner membrane, protons accumulate in intermembrane space.', 'Glycolysis occurs in the cytoplasm and the citric acid cycle in the mitochondrial matrix. ETS complexes sit in the inner mitochondrial membrane and pump protons into the intermembrane space, building the gradient that drives ATP synthase.', '{"a": "Wrong for every pair.", "b": "Wrong for every pair.", "c": "Wrong for every pair."}'::jsonb, 'Succinate dehydrogenase is the only TCA enzyme in the inner mitochondrial membrane.', 'easy', true, 2024, NULL, 'NEET UG 2024 (NTA) · answer verified by UG Prep', NULL),
('c5916248-58f2-5754-8d60-d91d93235d04', 'neet_ug', 'Botany', 'Molecular Basis of Inheritance', 'Which of the following statement is correct regarding the process of replication in E. coli?', '[{"id": "a", "text": "The DNA dependent DNA polymerase catalyses polymerization in 5′→3′ as well as 3′→5′ direction."}, {"id": "b", "text": "The DNA dependent DNA polymerase catalyses polymerization in 5′→3′ direction."}, {"id": "c", "text": "The DNA dependent DNA polymerase catalyses polymerization in one direction, that is 3′→5′."}, {"id": "d", "text": "The DNA dependent RNA polymerase catalyses polymerization in one direction, that is 5′→3′."}]'::jsonb, 'b', 'DNA polymerase adds nucleotides only in the 5′→3′ direction.', 'DNA-dependent DNA polymerases can extend a chain only at its 3′-OH end, so polymerisation is 5′→3′ only. This is why one strand is made continuously and the other discontinuously as Okazaki fragments joined by ligase. The DNA-dependent RNA polymerase is the transcription enzyme, so option (4) does not describe replication.', '{"a": "Polymerisation in the 3′→5′ direction does not occur.", "c": "The direction is 5′→3′, not 3′→5′.", "d": "Describes RNA polymerase, the enzyme of transcription, not DNA replication."}'::jsonb, 'Average E. coli replication rate is about 2000 bp per second.', 'med', true, 2024, NULL, 'NEET UG 2024 (NTA) · answer verified by UG Prep', NULL),
('cf75fb96-0edd-51c2-824c-876e73fbbc16', 'neet_ug', 'Botany', 'Ecosystem', 'In an ecosystem if the Net Primary Productivity (NPP) of first trophic level is 100x (kcal m⁻²) yr⁻¹, what would be the GPP (Gross Primary Productivity) of the third trophic level of the same ecosystem?', '[{"id": "a", "text": "10x (kcal m⁻²) yr⁻¹"}, {"id": "b", "text": "100x/3x (kcal m⁻²) yr⁻¹"}, {"id": "c", "text": "x/10 (kcal m⁻²) yr⁻¹"}, {"id": "d", "text": "x (kcal m⁻²) yr⁻¹"}]'::jsonb, 'd', 'With the 10 % law, 100x → 10x → x reaches the third trophic level.', 'By Lindeman''s 10 % law, only about one-tenth of the energy at one trophic level passes to the next. The NPP of producers (100x) gives 10x at the second level and 100x × 0.1 × 0.1 = x at the third level.', '{"a": "10x is what reaches the second trophic level.", "b": "Dividing by 3 has no ecological basis.", "c": "x/10 would reach the fourth trophic level."}'::jsonb, '10 % law: only about 10 % of energy is transferred to each next trophic level.', 'med', true, 2024, NULL, 'NEET UG 2024 (NTA) · answer verified by UG Prep', NULL),
('d469cceb-0b21-5a0c-901c-992c4832ba70', 'neet_ug', 'Botany', 'Morphology of Flowering Plants', 'Match List-I with List-II.
List-I | List-II
(A) Rose | (I) Twisted aestivation
(B) Pea | (II) Perigynous flower
(C) Cotton | (III) Drupe
(D) Mango | (IV) Marginal placentation
Choose the correct answer from the options given below:', '[{"id": "a", "text": "A-IV, B-III, C-II, D-I"}, {"id": "b", "text": "A-II, B-III, C-IV, D-I"}, {"id": "c", "text": "A-II, B-IV, C-I, D-III"}, {"id": "d", "text": "A-I, B-II, C-III, D-IV"}]'::jsonb, 'c', 'Rose perigynous, pea marginal placentation, cotton twisted aestivation, mango drupe.', 'Rose has a perigynous flower with a half-inferior ovary. Pea has marginal placentation along the ventral suture of a monocarpellary ovary. Cotton (like china rose) has twisted aestivation, and mango fruit is a drupe with a stony endocarp.', '{"a": "Wrong for every pair.", "b": "Pea is not a drupe and cotton lacks marginal placentation.", "d": "Wrong for every pair."}'::jsonb, 'Drupes: mango and coconut; edible part of mango is the fleshy mesocarp.', 'easy', true, 2024, NULL, 'NEET UG 2024 (NTA) · answer verified by UG Prep', NULL),
('1a60089a-93f7-5fba-a9a1-f393527972d0', 'neet_ug', 'Botany', 'Biodiversity and Conservation', 'Match List-I with List-II.
List-I | List-II
(A) Robert May | (I) Species area relationship
(B) Alexander von Humboldt | (II) Long term ecosystem experiment using out door plots
(C) Paul Ehrlich | (III) Global species diversity at about 7 million
(D) David Tilman | (IV) Rivet popper hypothesis
Choose the correct answer from the options given below:', '[{"id": "a", "text": "A-I, B-III, C-II, D-IV"}, {"id": "b", "text": "A-III, B-IV, C-II, D-I"}, {"id": "c", "text": "A-II, B-III, C-I, D-IV"}, {"id": "d", "text": "A-III, B-I, C-IV, D-II"}]'::jsonb, 'd', 'May 7 million species, Humboldt species-area, Ehrlich rivet popper, Tilman outdoor plots.', 'Robert May estimated global species diversity at about 7 million. Humboldt described the species-area relationship. Paul Ehrlich proposed the rivet popper hypothesis, and David Tilman''s long-term outdoor plot experiments showed that plots with more species are more stable and productive.', '{"a": "Wrong for A, B and C.", "b": "Wrong for B, C and D.", "c": "Wrong for every pair."}'::jsonb, 'Species-area relationship: log S = log C + Z log A; Z ≈ 0.1–0.2 for most areas.', 'easy', true, 2024, NULL, 'NEET UG 2024 (NTA) · answer verified by UG Prep', NULL),
('47daf46f-ddc6-516e-a322-120b92c46e46', 'neet_ug', 'Botany', 'Morphology of Flowering Plants', 'Match List-I with List-II.
List-I (Types of stamen) | List-II (Example)
(A) Monoadelphous | (I) Citrus
(B) Diadelphous | (II) Pea
(C) Polyadelphous | (III) Lily
(D) Epiphyllous | (IV) China-rose
Choose the correct answer from the options given below:', '[{"id": "a", "text": "A-I, B-II, C-IV, D-III"}, {"id": "b", "text": "A-III, B-I, C-IV, D-II"}, {"id": "c", "text": "A-IV, B-II, C-I, D-III"}, {"id": "d", "text": "A-IV, B-I, C-II, D-III"}]'::jsonb, 'c', 'China rose monoadelphous, pea diadelphous, citrus polyadelphous, lily epiphyllous.', 'China rose stamens are united in one bundle (monoadelphous), pea in two bundles (diadelphous) and citrus in more than two (polyadelphous). In lily the stamens are attached to the perianth (epiphyllous).', '{"a": "Citrus is not monoadelphous.", "b": "Wrong for every pair.", "d": "Swaps pea and citrus."}'::jsonb, 'Epipetalous stamens occur in brinjal; epiphyllous in lily.', 'easy', true, 2024, NULL, 'NEET UG 2024 (NTA) · answer verified by UG Prep', NULL),
('ce722653-058f-5bec-bde9-7d4ca3456535', 'neet_ug', 'Botany', 'Plant Kingdom', 'Read the following statements and choose the set of correct statements.
In the members of Phaeophyceae,
A. Asexual reproduction occurs usually by biflagellate zoospores.
B. Sexual reproduction is by oogamous method only.
C. Stored food is in the form of carbohydrates which is either mannitol or laminarin.
D. The major pigments found are chlorophyll a, c and carotenoids and xanthophyll.
E. Vegetative cells have a cellulosic wall, usually covered on the outside by gelatinous coating of algin.
Choose the correct answer from the options given below:', '[{"id": "a", "text": "A, C, D and E only"}, {"id": "b", "text": "A, B, C and E only"}, {"id": "c", "text": "A, B, C and D only"}, {"id": "d", "text": "B, C, D and E only"}]'::jsonb, 'a', 'All are true except B; brown algae can be isogamous, anisogamous or oogamous.', 'Brown algae reproduce asexually by pear-shaped biflagellate zoospores (A), store laminarin or mannitol (C), contain chlorophyll a, c, carotenoids and fucoxanthin-type xanthophylls (D), and have cellulosic walls coated with algin (E). Sexual reproduction may be isogamous, anisogamous or oogamous, so B is false.', '{"b": "Includes B and omits D.", "c": "Includes B and omits E.", "d": "Includes B and omits A."}'::jsonb, 'Phaeophyceae: Ectocarpus, Dictyota, Laminaria, Sargassum, Fucus.', 'med', true, 2024, NULL, 'NEET UG 2024 (NTA) · answer verified by UG Prep', NULL),
('764a1219-7548-52cd-b873-5e2dac35305b', 'neet_ug', 'Zoology', 'Human Health and Disease', 'Match List I with List II:
List I | List II
A. Typhoid | I. Fungus
B. Leishmaniasis | II. Nematode
C. Ringworm | III. Protozoa
D. Filariasis | IV. Bacteria
Choose the correct answer from the options given below:', '[{"id": "a", "text": "A-III, B-I, C-IV, D-II"}, {"id": "b", "text": "A-II, B-IV, C-III, D-I"}, {"id": "c", "text": "A-I, B-III, C-II, D-IV"}, {"id": "d", "text": "A-IV, B-III, C-I, D-II"}]'::jsonb, 'd', 'Typhoid is bacterial, leishmaniasis protozoan, ringworm fungal and filariasis nematode.', 'Typhoid is caused by the bacterium Salmonella typhi and leishmaniasis by the protozoan Leishmania. Ringworm is caused by fungi such as Microsporum, Trichophyton and Epidermophyton, and filariasis by the nematode Wuchereria. So the match is A-IV, B-III, C-I, D-II.', '{"a": "Typhoid is not protozoan and leishmaniasis is not fungal.", "b": "Typhoid is not caused by a nematode.", "c": "Typhoid is not a fungal disease."}'::jsonb, 'Ringworm fungi (Microsporum, Trichophyton, Epidermophyton) thrive in warm, moist skin folds.', 'easy', true, 2024, NULL, 'NEET UG 2024 (NTA) · answer verified by UG Prep', NULL),
('c021fb79-907a-5904-b1fb-acf0a77164d6', 'neet_ug', 'Zoology', 'Reproductive Health', 'Match List I with List II:
List I | List II
A. Non-medicated IUD | I. Multiload 375
B. Copper releasing IUD | II. Progestogens
C. Hormone releasing IUD | III. Lippes loop
D. Implants | IV. LNG-20
Choose the correct answer from the options given below:', '[{"id": "a", "text": "A-IV, B-I, C-II, D-III"}, {"id": "b", "text": "A-III, B-I, C-IV, D-II"}, {"id": "c", "text": "A-III, B-I, C-II, D-IV"}, {"id": "d", "text": "A-I, B-III, C-IV, D-II"}]'::jsonb, 'b', 'Lippes loop is non-medicated, Multiload 375 releases copper, LNG-20 releases hormone and implants contain progestogens.', 'Lippes loop is the classic non-medicated IUD, while CuT, Cu7 and Multiload 375 release copper. Progestasert and LNG-20 are hormone-releasing IUDs. Implants placed under the skin contain progestogens alone or with oestrogen. So the match is A-III, B-I, C-IV, D-II.', '{"a": "LNG-20 is not a non-medicated IUD.", "c": "LNG-20 is a hormone-releasing IUD, not an implant.", "d": "Multiload 375 releases copper; Lippes loop is non-medicated."}'::jsonb, 'Copper ions released by Cu-IUDs suppress sperm motility and fertilising capacity.', 'easy', true, 2024, NULL, 'NEET UG 2024 (NTA) · answer verified by UG Prep', NULL),
('cc35f3f3-c6a1-5c79-8cc7-70b9342c0b72', 'neet_ug', 'Zoology', 'Human Reproduction', 'Given below are two statements:
Statement I: The presence or absence of hymen is not a reliable indicator of virginity.
Statement II: The hymen is torn during the first coitus only.
In the light of the above statements, choose the correct answer from the options given below:', '[{"id": "a", "text": "Statement I is true but Statement II is false."}, {"id": "b", "text": "Statement I is false but Statement II is true."}, {"id": "c", "text": "Both Statement I and Statement II are true."}, {"id": "d", "text": "Both Statement I and Statement II are false."}]'::jsonb, 'a', 'The hymen can tear in many ways besides coitus, so it is not a marker of virginity.', 'NCERT says the hymen is often torn during the first coitus, but it can also break from a sudden fall or jolt, inserting a tampon, or activities like horse-riding and cycling. In some women it persists even after coitus. So Statement I is true, and Statement II is false because of the word ''only''.', '{"b": "Statement I is true.", "c": "Statement II is false because the hymen can tear without coitus.", "d": "Statement I is a correct NCERT statement."}'::jsonb, 'Hymen is a membrane partially covering the vaginal opening; its presence or absence says nothing about sexual experience.', 'easy', true, 2024, NULL, 'NEET UG 2024 (NTA) · answer verified by UG Prep', NULL),
('28633a44-1579-5417-9e7f-8becbfbb9fb9', 'neet_ug', 'Zoology', 'Structural Organisation in Animals', 'In both sexes of cockroach, a pair of jointed filamentous structures called anal cerci are present on:', '[{"id": "a", "text": "8th and 9th segment"}, {"id": "b", "text": "11th segment"}, {"id": "c", "text": "5th segment"}, {"id": "d", "text": "10th segment"}]'::jsonb, 'd', 'Anal cerci arise from the 10th abdominal segment in both sexes.', 'The cockroach abdomen has 10 segments. A pair of jointed filamentous anal cerci is present on the 10th segment in both males and females. Males also bear a pair of short, unjointed anal styles on the 9th sternum.', '{"a": "The 8th and 9th terga form the genital pouch roof in females, not the cerci.", "b": "The cockroach abdomen has only 10 segments.", "c": "The 5th segment bears no cerci."}'::jsonb, 'Anal styles (9th segment) are present only in male cockroaches; anal cerci (10th segment) are present in both sexes.', 'easy', true, 2024, NULL, 'NEET UG 2024 (NTA) · answer verified by UG Prep', NULL),
('6dd5d06c-a71c-5125-b65b-9b4ef6d0b20c', 'neet_ug', 'Zoology', 'Neural Control and Coordination', 'Match List I with List II:
List I | List II
A. Pons | I. Provides additional space for Neurons, regulates posture and balance.
B. Hypothalamus | II. Controls respiration and gastric secretions.
C. Medulla | III. Connects different regions of the brain.
D. Cerebellum | IV. Neuro secretory cells
Choose the correct answer from the options given below:', '[{"id": "a", "text": "A-I, B-III, C-II, D-IV"}, {"id": "b", "text": "A-II, B-I, C-III, D-IV"}, {"id": "c", "text": "A-II, B-III, C-I, D-IV"}, {"id": "d", "text": "A-III, B-IV, C-II, D-I"}]'::jsonb, 'd', 'Pons interconnects brain regions, hypothalamus has neurosecretory cells, medulla controls respiration and cerebellum gives space for neurons.', 'The pons is made of fibre tracts that interconnect different regions of the brain. The hypothalamus contains neurosecretory cells that make hypothalamic hormones. The medulla holds the centres for respiration, cardiovascular reflexes and gastric secretion. The convoluted cerebellum provides extra space for many neurons and maintains posture and balance. So the match is A-III, B-IV, C-II, D-I.', '{"a": "Posture and balance belong to the cerebellum, not the pons.", "b": "The pons does not control respiration and gastric secretion as its main role; that is the medulla.", "c": "The medulla is not the region with extra neuron space."}'::jsonb, 'Brain stem = midbrain + pons + medulla oblongata.', 'easy', true, 2024, NULL, 'NEET UG 2024 (NTA) · answer verified by UG Prep', NULL),
('dedd059d-a674-5d17-ac8a-f8813b0bc3a7', 'neet_ug', 'Zoology', 'Chemical Coordination and Integration', 'Which of the following is not a steroid hormone?', '[{"id": "a", "text": "Progesterone"}, {"id": "b", "text": "Glucagon"}, {"id": "c", "text": "Cortisol"}, {"id": "d", "text": "Testosterone"}]'::jsonb, 'b', 'Glucagon is a peptide hormone; the rest are steroids.', 'Glucagon is a peptide hormone secreted by the α-cells of the islets of Langerhans. Progesterone, cortisol and testosterone are all steroid hormones derived from cholesterol, and they act through intracellular receptors.', '{"a": "Progesterone is a steroid made by the corpus luteum.", "c": "Cortisol is a steroid glucocorticoid from the adrenal cortex.", "d": "Testosterone is a steroid androgen from Leydig cells."}'::jsonb, 'Steroid hormones bind intracellular receptors; peptide hormones like glucagon and insulin act through membrane receptors and second messengers.', 'easy', true, 2024, NULL, 'NEET UG 2024 (NTA) · answer verified by UG Prep', NULL),
('d64e5272-6aab-5c0d-b14e-909fc454946b', 'neet_ug', 'Zoology', 'Molecular Basis of Inheritance', 'Which one is the correct product of DNA dependent RNA polymerase to the given template?
3'' TACATGGCAAATATCCATTCA 5''', '[{"id": "a", "text": "5'' AUGUACCGUUUAUAGGGAAGU 3''"}, {"id": "b", "text": "5'' ATGTACCGTTTATAGGTAAGT 3''"}, {"id": "c", "text": "5'' AUGUACCGUUUAUAGGUAAGU 3''"}, {"id": "d", "text": "5'' AUGUAAAGUUUAUAGGUAAGU 3''"}]'::jsonb, 'c', 'The RNA is complementary and antiparallel to the template, with U in place of T.', 'Pairing each template base (T→A, A→U, G→C, C→G) from the 3'' end gives 5'' AUG UAC CGU UUA UAG GUA AGU 3''. Option (3) matches base for base. Option (1) differs at position 17 (G instead of U), option (4) at positions 6–8, and option (2) contains T, so it is DNA.', '{"a": "Has GGG instead of GGU near the 3'' end, which is wrong for the template CCA.", "b": "Contains thymine, so it is DNA, not an RNA transcript.", "d": "Has AAA at positions 6–8 where the template TGG demands ACC."}'::jsonb, 'RNA is synthesised 5''→3'' on the template strand that runs 3''→5''.', 'med', true, 2024, NULL, 'NEET UG 2024 (NTA) · answer verified by UG Prep', NULL),
('62b1b2e8-4361-5f61-b9a7-9dc750bc00c6', 'neet_ug', 'Zoology', 'Structural Organisation in Animals', 'Three type of muscles are given as a, b and c. Identify the correct matching pair along with their location in human body.
Name of muscle/location', '[{"id": "a", "text": "(a) Skeletal - Biceps; (b) Involuntary - Intestine; (c) Smooth - Heart"}, {"id": "b", "text": "(a) Involuntary - Nose tip; (b) Skeletal - Bone; (c) Cardiac - Heart"}, {"id": "c", "text": "(a) Smooth - Toes; (b) Skeletal - Legs; (c) Cardiac - Heart"}, {"id": "d", "text": "(a) Skeletal - Triceps; (b) Smooth - Stomach; (c) Cardiac - Heart"}]'::jsonb, 'd', '(a) is striated skeletal, (b) is spindle-shaped smooth and (c) is branched cardiac muscle.', 'Figure (a) shows long, parallel, striated, multinucleate fibres, which are skeletal muscle like the triceps. Figure (b) shows unstriated spindle-shaped fibres with tapering ends, which are smooth muscle found in the stomach wall. Figure (c) shows branched striated fibres joined together, which are cardiac muscle of the heart.', '{"a": "(c) is cardiac muscle, not smooth muscle.", "b": "(a) is striated skeletal muscle, not involuntary, and (b) is smooth, not skeletal.", "c": "(a) is skeletal muscle, not smooth, and (b) is smooth, not skeletal."}'::jsonb, 'Cardiac muscle cells are joined by intercalated discs (fusion points) that let them contract as a unit.', 'easy', true, 2024, NULL, 'NEET UG 2024 (NTA) · answer verified by UG Prep', '/pyq/ug/2024/158.webp'),
('73f7e19d-5ef1-5642-9235-72140d9f4c65', 'neet_ug', 'Zoology', 'Cell Cycle and Cell Division', 'Following are the stages of cell division:
A. Gap 2 phase
B. Cytokinesis
C. Synthesis phase
D. Karyokinesis
E. Gap 1 phase
Choose the correct sequence of stages from the options given below:', '[{"id": "a", "text": "B-D-E-A-C"}, {"id": "b", "text": "E-C-A-D-B"}, {"id": "c", "text": "C-E-D-A-B"}, {"id": "d", "text": "E-B-D-A-C"}]'::jsonb, 'b', 'Cell cycle order: G₁ → S → G₂ → karyokinesis → cytokinesis.', 'Interphase comes first as G₁, then S (DNA replication), then G₂. The M phase follows, with karyokinesis (nuclear division) usually followed by cytokinesis (division of the cytoplasm). So the sequence is E-C-A-D-B.', '{"a": "Starts with cytokinesis, which ends the cycle.", "c": "S phase cannot precede G₁.", "d": "Cytokinesis cannot come right after G₁."}'::jsonb, 'In a typical human cell in culture, the cycle takes about 24 h and M phase lasts only about 1 h.', 'easy', true, 2024, NULL, 'NEET UG 2024 (NTA) · answer verified by UG Prep', NULL),
('d313059d-f055-5140-ada8-5ce09087b4e3', 'neet_ug', 'Zoology', 'Human Health and Disease', 'Which of the following are Autoimmune disorders?
A. Myasthenia gravis
B. Rheumatoid arthritis
C. Gout
D. Muscular dystrophy
E. Systemic Lupus Erythematosus (SLE)
Choose the most appropriate answer from the options given below:', '[{"id": "a", "text": "B, C & E only"}, {"id": "b", "text": "C, D & E only"}, {"id": "c", "text": "A, B & D only"}, {"id": "d", "text": "A, B & E only"}]'::jsonb, 'd', 'Myasthenia gravis, rheumatoid arthritis and SLE are autoimmune; gout and muscular dystrophy are not.', 'In myasthenia gravis, autoantibodies attack the neuromuscular junction. Rheumatoid arthritis and SLE are also autoimmune. Gout comes from uric acid crystals building up in joints, and muscular dystrophy is a genetic disorder that makes skeletal muscle degenerate.', '{"a": "Gout is metabolic, not autoimmune.", "b": "Gout and muscular dystrophy are not autoimmune.", "c": "Muscular dystrophy is genetic, not autoimmune."}'::jsonb, 'Autoimmunity is when the immune system attacks self cells, for example in rheumatoid arthritis.', 'easy', true, 2024, NULL, 'NEET UG 2024 (NTA) · answer verified by UG Prep', NULL),
('f45e117c-a525-51df-8901-25e8a9b61464', 'neet_ug', 'Zoology', 'Biomolecules', 'Match List I with List II:
List I | List II
A. Lipase | I. Peptide bond
B. Nuclease | II. Ester bond
C. Protease | III. Glycosidic bond
D. Amylase | IV. Phosphodiester bond
Choose the correct answer from the options given below:', '[{"id": "a", "text": "A-II, B-IV, C-I, D-III"}, {"id": "b", "text": "A-IV, B-I, C-III, D-II"}, {"id": "c", "text": "A-IV, B-II, C-III, D-I"}, {"id": "d", "text": "A-III, B-II, C-I, D-IV"}]'::jsonb, 'a', 'Each enzyme hydrolyses the bond that links its own substrate''s monomers.', 'Lipases break the ester bonds between glycerol and fatty acids, and nucleases break the phosphodiester bonds of nucleic acids. Proteases cleave peptide bonds, and amylase cleaves the α-glycosidic bonds of starch. So the match is A-II, B-IV, C-I, D-III.', '{"b": "Lipids have no phosphodiester bonds.", "c": "Protease does not act on glycosidic bonds.", "d": "Amylase does not act on phosphodiester bonds."}'::jsonb, 'Nucleotides in nucleic acids are joined by 3''–5'' phosphodiester bonds.', 'easy', true, 2024, NULL, 'NEET UG 2024 (NTA) · answer verified by UG Prep', NULL),
('8199620e-1e5b-5626-b3e8-8bc65ed3b420', 'neet_ug', 'Zoology', 'Evolution', 'The flippers of the Penguins and Dolphins are the example of the', '[{"id": "a", "text": "Convergent evolution"}, {"id": "b", "text": "Divergent evolution"}, {"id": "c", "text": "Adaptive radiation"}, {"id": "d", "text": "Natural selection"}]'::jsonb, 'a', 'Penguin and dolphin flippers are analogous structures, so they show convergent evolution.', 'Penguins (birds) and dolphins (mammals) are not closely related, but both evolved paddle-like flippers for swimming. Organs that do the same job but have different ancestry are analogous, and they come from convergent evolution.', '{"b": "Divergent evolution produces homologous organs from a common ancestor.", "c": "Adaptive radiation is one ancestor radiating into many forms, like Darwin''s finches.", "d": "Natural selection is the mechanism, not the pattern this example shows."}'::jsonb, 'Analogous organs: wings of butterfly and bird, eye of octopus and mammal, flippers of penguin and dolphin.', 'easy', true, 2024, NULL, 'NEET UG 2024 (NTA) · answer verified by UG Prep', NULL),
('4c03c6f2-9e60-5241-b73e-9563582a37d3', 'neet_ug', 'Zoology', 'Breathing and Exchange of Gases', 'Match List I with List II:
List I | List II
A. Expiratory capacity | I. Expiratory reserve volume + Tidal volume + Inspiratory reserve volume
B. Functional residual capacity | II. Tidal volume + Expiratory reserve volume
C. Vital capacity | III. Tidal volume + Inspiratory reserve volume
D. Inspiratory capacity | IV. Expiratory reserve volume + Residual volume
Choose the correct answer from the options given below:', '[{"id": "a", "text": "A-II, B-I, C-IV, D-III"}, {"id": "b", "text": "A-I, B-III, C-II, D-IV"}, {"id": "c", "text": "A-II, B-IV, C-I, D-III"}, {"id": "d", "text": "A-III, B-II, C-IV, D-I"}]'::jsonb, 'c', 'EC = TV+ERV, FRC = ERV+RV, VC = ERV+TV+IRV, IC = TV+IRV.', 'Expiratory capacity is the total a person can breathe out after a normal inspiration, which is TV + ERV. Functional residual capacity is the air left after a normal expiration, which is ERV + RV. Vital capacity is ERV + TV + IRV, and inspiratory capacity is TV + IRV. So the match is A-II, B-IV, C-I, D-III.', '{"a": "FRC does not include IRV.", "b": "Expiratory capacity is not the sum of all three volumes.", "d": "Expiratory capacity does not include IRV."}'::jsonb, 'Total lung capacity = VC + RV, about 5800–6000 mL.', 'med', true, 2024, NULL, 'NEET UG 2024 (NTA) · answer verified by UG Prep', NULL),
('a46a27a4-f382-5b0d-8b5e-f702f1077bed', 'neet_ug', 'Zoology', 'Evolution', 'Which one of the following factors will not affect the Hardy-Weinberg equilibrium?', '[{"id": "a", "text": "Gene migration"}, {"id": "b", "text": "Constant gene pool"}, {"id": "c", "text": "Genetic recombination"}, {"id": "d", "text": "Genetic drift"}]'::jsonb, 'b', 'A constant gene pool is the condition of equilibrium itself, not a factor that disturbs it.', 'Hardy–Weinberg equilibrium is upset by gene migration (gene flow), genetic drift, mutation, genetic recombination and natural selection. A constant gene pool means allele frequencies stay stable, which is the equilibrium state, so it does not disturb it.', '{"a": "Gene flow changes allele frequencies.", "c": "Recombination is listed by NCERT as a factor affecting equilibrium.", "d": "Chance changes in small populations shift allele frequencies."}'::jsonb, 'p² + 2pq + q² = 1 is the binomial expansion of (p + q)².', 'easy', true, 2024, NULL, 'NEET UG 2024 (NTA) · answer verified by UG Prep', NULL),
('f49f63ca-cd36-5e23-9841-e7d6c2cf28da', 'neet_ug', 'Zoology', 'Evolution', 'Given below are some stages of human evolution. Arrange them in correct sequence. (Past to Recent)
A. Homo habilis
B. Homo sapiens
C. Homo neanderthalensis
D. Homo erectus
Choose the correct sequence of human evolution from the options given below:', '[{"id": "a", "text": "C-B-D-A"}, {"id": "b", "text": "A-D-C-B"}, {"id": "c", "text": "D-A-C-B"}, {"id": "d", "text": "B-A-D-C"}]'::jsonb, 'b', 'Homo habilis → Homo erectus → Neanderthals → Homo sapiens.', 'Homo habilis (brain about 650–800 cc) came first, followed by Homo erectus about 1.5 mya (about 900 cc). Neanderthal man (about 1400 cc) lived from about 1,00,000 to 40,000 years ago, and Homo sapiens arose in Africa. So the order is A-D-C-B.', '{"a": "Neanderthals are not the earliest form.", "c": "Homo erectus came after Homo habilis.", "d": "Homo sapiens is the most recent form."}'::jsonb, 'Homo habilis was probably the first human-like being and did not eat meat.', 'easy', true, 2024, NULL, 'NEET UG 2024 (NTA) · answer verified by UG Prep', NULL),
('063e941d-592d-5db8-93e9-830c469dc3fa', 'neet_ug', 'Zoology', 'Body Fluids and Circulation', 'Following are the stages of pathway for conduction of an action potential through the heart:
A. AV bundle
B. Purkinje fibres
C. AV node
D. Bundle branches
E. SA node
Choose the correct sequence of pathway from the options given below:', '[{"id": "a", "text": "B-D-E-C-A"}, {"id": "b", "text": "E-A-D-B-C"}, {"id": "c", "text": "E-C-A-D-B"}, {"id": "d", "text": "A-E-C-B-D"}]'::jsonb, 'c', 'SA node → AV node → AV bundle → bundle branches → Purkinje fibres.', 'The SA node is the pacemaker that starts the impulse. It reaches the AV node, then the AV bundle (bundle of His), which divides into right and left bundle branches in the interventricular septum. These end in Purkinje fibres in the ventricular wall. So the sequence is E-C-A-D-B.', '{"a": "Conduction cannot start at the Purkinje fibres.", "b": "The AV node comes before the AV bundle.", "d": "The impulse starts at the SA node, not the AV bundle."}'::jsonb, 'The SA node generates 70–75 action potentials per minute and is called the pacemaker.', 'easy', true, 2024, NULL, 'NEET UG 2024 (NTA) · answer verified by UG Prep', NULL),
('038f2a5a-3c4e-5f50-b7ca-91f8e6273bf6', 'neet_ug', 'Zoology', 'Breathing and Exchange of Gases', 'Which of the following factors are favourable for the formation of oxyhaemoglobin in alveoli?', '[{"id": "a", "text": "Low pCO₂ and High H⁺ concentration"}, {"id": "b", "text": "Low pCO₂ and High temperature"}, {"id": "c", "text": "High pO₂ and High pCO₂"}, {"id": "d", "text": "High pO₂ and Lesser H⁺ concentration"}]'::jsonb, 'd', 'High pO₂, low pCO₂, low H⁺ and lower temperature favour oxyhaemoglobin formation.', 'In the alveoli, high pO₂, low pCO₂, low H⁺ concentration and lower temperature all help O₂ bind to haemoglobin. The opposite conditions in the tissues favour dissociation of oxyhaemoglobin (the Bohr effect).', '{"a": "High H⁺ favours dissociation.", "b": "High temperature favours dissociation.", "c": "High pCO₂ favours dissociation."}'::jsonb, 'About 97% of O₂ is carried by RBCs as oxyhaemoglobin and about 3% is dissolved in plasma.', 'easy', true, 2024, NULL, 'NEET UG 2024 (NTA) · answer verified by UG Prep', NULL),
('7fecf0a5-2bfb-5d0f-8707-3d344c991b1b', 'neet_ug', 'Zoology', 'Biotechnology and its Applications', 'Match List I with List II:
List I | List II
A. α-1 antitrypsin | I. Cotton bollworm
B. Cry IAb | II. ADA deficiency
C. Cry IAc | III. Emphysema
D. Enzyme replacement therapy | IV. Corn borer
Choose the correct answer from the options given below:', '[{"id": "a", "text": "A-III, B-IV, C-I, D-II"}, {"id": "b", "text": "A-II, B-IV, C-I, D-III"}, {"id": "c", "text": "A-II, B-I, C-IV, D-III"}, {"id": "d", "text": "A-III, B-I, C-II, D-IV"}]'::jsonb, 'a', 'α-1 antitrypsin treats emphysema, cryIAb kills corn borer, cryIAc and cryIIAb control cotton bollworm, and ERT treats ADA deficiency.', 'Transgenic animals produce α-1 antitrypsin, which is used to treat emphysema. The cryIAb gene controls the corn borer, while cryIAc controls cotton bollworms. Enzyme replacement therapy (injecting functional ADA) is one treatment for ADA deficiency. So the match is A-III, B-IV, C-I, D-II.', '{"b": "α-1 antitrypsin is not a treatment for ADA deficiency.", "c": "Cry IAb targets corn borer, not cotton bollworm.", "d": "Cry IAc is insecticidal; it does not treat ADA deficiency."}'::jsonb, 'cryIAc and cryIIAb control cotton bollworms; cryIAb controls corn borer.', 'easy', true, 2024, NULL, 'NEET UG 2024 (NTA) · answer verified by UG Prep', NULL),
('5e21ef31-d53e-5c3a-bf1b-93565986a11e', 'neet_ug', 'Zoology', 'Chemical Coordination and Integration', 'Given below are two statement: one is labelled as Assertion A and the other is labelled as Reason R:
Assertion A: FSH acts upon ovarian follicles in female and Leydig cells in male.
Reason R: Growing ovarian follicles secrete estrogen in female while interstitial cells secrete androgen in male human being.
In the light of the above statements, choose the correct answer from the options given below:', '[{"id": "a", "text": "A is true but R is false"}, {"id": "b", "text": "A is false but R is true"}, {"id": "c", "text": "Both A and R are true and R is the correct explanation of A."}, {"id": "d", "text": "Both A and R are true but R is NOT the correct explanation of A."}]'::jsonb, 'b', 'In males, FSH acts on Sertoli cells, not Leydig cells, so A is false while R is true.', 'In females, FSH stimulates the growth of ovarian follicles, and the growing follicles secrete oestrogen. In males, FSH acts on Sertoli cells, while LH (ICSH) acts on Leydig (interstitial) cells, which secrete androgens. So the Assertion is false and the Reason is true.', '{"a": "A is false because FSH targets Sertoli cells in males.", "c": "A is false.", "d": "A is false."}'::jsonb, 'LH stimulates Leydig cells to secrete androgens; FSH acts on Sertoli cells to aid spermiogenesis.', 'med', true, 2024, NULL, 'NEET UG 2024 (NTA) · answer verified by UG Prep', NULL),
('23c53a34-a8ee-5639-892b-5c8efee0c5bf', 'neet_ug', 'Zoology', 'Biotechnology: Principles and Processes', 'The following diagram showing restriction sites in E.coli cloning vector pBR322. Find the role of ''X'' and ''Y'' genes:', '[{"id": "a", "text": "The gene ''X'' is for protein involved in replication of Plasmid and ''Y'' for resistance to antibiotics."}, {"id": "b", "text": "Gene ''X'' is responsible for recognition sites and ''Y'' is responsible for antibiotic resistance."}, {"id": "c", "text": "The gene ''X'' is respoinsible for resistance to antibiotics and ''Y'' for protein involved in the replication of Plasmid."}, {"id": "d", "text": "The gene ''X'' is responsible for controlling the copy number of the linked DNA and ''Y'' for protein involved in the replication of Plasmid."}]'::jsonb, 'd', 'X is ori, which controls the copy number of the linked DNA, and Y is rop, which codes for proteins of plasmid replication.', 'In the NCERT map of pBR322, amp^R spans Pvu I/Pst I and tet^R spans BamH I/Sal I. The lower-left position (X) is ori, where replication starts, and it controls the copy number of the linked DNA. The position at the bottom near Pvu II (Y) is rop, which codes for the proteins that take part in plasmid replication. So option (4) is correct.', '{"a": "Reverses the roles: X (ori) is not a protein-coding gene and Y (rop) is not an antibiotic-resistance gene.", "b": "ori is not a recognition site, and rop does not give antibiotic resistance.", "c": "Antibiotic-resistance genes are amp^R and tet^R, not X."}'::jsonb, 'pBR322 carries amp^R and tet^R as selectable markers, ori and rop; BamH I in tet^R allows insertional inactivation.', 'hard', true, 2024, NULL, 'NEET UG 2024 (NTA) · answer verified by UG Prep', '/pyq/ug/2024/170.webp'),
('fd396775-1305-5f3a-afd7-8642a56a04d4', 'neet_ug', 'Zoology', 'Human Health and Disease', 'Match List I with List II:
List I | List II
A. Cocaine | I. Effective sedative in surgery
B. Heroin | II. Cannabis sativa
C. Morphine | III. Erythroxylum
D. Marijuana | IV. Papaver somniferum
Choose the correct answer from the options given below:', '[{"id": "a", "text": "A-II, B-I, C-III, D-IV"}, {"id": "b", "text": "A-III, B-IV, C-I, D-II"}, {"id": "c", "text": "A-IV, B-III, C-I, D-II"}, {"id": "d", "text": "A-I, B-III, C-II, D-IV"}]'::jsonb, 'b', 'Cocaine comes from Erythroxylum, heroin from poppy, morphine is a surgical sedative and marijuana is from Cannabis.', 'Cocaine is an alkaloid from the coca plant Erythroxylum coca. Heroin (smack) is diacetylmorphine, made from morphine taken from the latex of the poppy Papaver somniferum. Morphine itself is a very effective sedative and painkiller used in surgery. Marijuana comes from the inflorescences of Cannabis sativa. So the match is A-III, B-IV, C-I, D-II.', '{"a": "Cocaine is not from Cannabis.", "c": "Cocaine is not from poppy.", "d": "Cocaine is not a surgical sedative."}'::jsonb, 'Cannabinoids act on cannabinoid receptors of the brain and affect the cardiovascular system.', 'easy', true, 2024, NULL, 'NEET UG 2024 (NTA) · answer verified by UG Prep', NULL),
('31698fc1-d335-50f4-821f-3985daa96b3d', 'neet_ug', 'Zoology', 'Animal Kingdom', 'Consider the following statements:
A. Annelids are true coelomates
B. Poriferans are pseudocoelomates
C. Aschelminthes are acoelomates
D. Platyhelminthes are pseudocoelomates
Choose the correct answer from the options given below:', '[{"id": "a", "text": "C only"}, {"id": "b", "text": "D only"}, {"id": "c", "text": "B only"}, {"id": "d", "text": "A only"}]'::jsonb, 'd', 'Only annelids, which have a true mesodermal coelom, are correctly described.', 'Annelids are true coelomates (eucoelomates). Poriferans are at the cellular level of organisation and have no coelom at all. Aschelminthes are pseudocoelomates, and Platyhelminthes are acoelomates. So only statement A is correct.', '{"a": "Aschelminthes are pseudocoelomates.", "b": "Platyhelminthes are acoelomates.", "c": "Sponges are not pseudocoelomates."}'::jsonb, 'Coelomates: annelids, arthropods, molluscs, echinoderms, hemichordates and chordates.', 'easy', true, 2024, NULL, 'NEET UG 2024 (NTA) · answer verified by UG Prep', NULL),
('aa522106-e398-587d-aeb7-316cc997ef5d', 'neet_ug', 'Zoology', 'Excretory Products and their Elimination', 'Given below are two statements:
Statement I: In the nephron the descending limb of loop of Henle is impermeable to water and permeable to electrolytes.
Statement II: The proximal convoluted tubule is lined by simple columnar brush border epithelium and increases the surface area for reabsorption.
In the light of the above statements, choose the correct answer from the options given below:', '[{"id": "a", "text": "Statement I is true but Statement II is false."}, {"id": "b", "text": "Statement I is false but Statement II is true."}, {"id": "c", "text": "Both Statement I and Statement II are true."}, {"id": "d", "text": "Both Statement I and Statement II are false."}]'::jsonb, 'd', 'The descending limb is permeable to water, and the PCT has cuboidal, not columnar, brush border epithelium.', 'The descending limb of the loop of Henle is permeable to water but almost impermeable to electrolytes, so Statement I has the two reversed. The PCT is lined by simple cuboidal brush border epithelium, which increases the surface area for reabsorption, so Statement II is wrong to say columnar. Both statements are false.', '{"a": "Statement I reverses the permeability of the descending limb.", "b": "PCT epithelium is cuboidal, not columnar.", "c": "Both statements contain errors."}'::jsonb, 'The ascending limb of the loop of Henle is impermeable to water but allows transport of electrolytes.', 'med', true, 2024, NULL, 'NEET UG 2024 (NTA) · answer verified by UG Prep', NULL),
('af546568-0e97-550d-b219-419e6038656b', 'neet_ug', 'Zoology', 'Locomotion and Movement', 'Match List I with List II:
List I | List II
A. Fibrous joints | I. Adjacent vertebrae, limited movement
B. Cartilaginous joints | II. Humerus and pectoral girdle, rotational movement
C. Hinge | III. Skull, don''t allow any movement
D. Ball and socket joints | IV. Knee, help in locomotion
Choose the correct answer from the options given below:', '[{"id": "a", "text": "A-II, B-III, C-I, D-IV"}, {"id": "b", "text": "A-III, B-I, C-IV, D-II"}, {"id": "c", "text": "A-IV, B-II, C-III, D-I"}, {"id": "d", "text": "A-I, B-III, C-II, D-IV"}]'::jsonb, 'b', 'Skull sutures are fibrous, vertebrae are joined by cartilage, the knee is a hinge and the shoulder is a ball-and-socket joint.', 'Fibrous joints such as the skull sutures allow no movement. Cartilaginous joints between adjacent vertebrae allow limited movement. The knee is a hinge synovial joint used in locomotion. The joint between the humerus and the pectoral girdle is a ball-and-socket joint that allows rotation. So the match is A-III, B-I, C-IV, D-II.', '{"a": "Fibrous joints do not allow rotational movement.", "c": "The knee is not a fibrous joint.", "d": "Fibrous joints are immovable, not between vertebrae."}'::jsonb, 'Pivot joint: between atlas and axis; saddle joint: carpal–metacarpal of thumb.', 'easy', true, 2024, NULL, 'NEET UG 2024 (NTA) · answer verified by UG Prep', NULL),
('e2e52887-c2b6-5211-a8bf-e0158b9e4c9c', 'neet_ug', 'Zoology', 'Reproductive Health', 'Which of the following is not a natural/traditional contraceptive method?', '[{"id": "a", "text": "Lactational amenorrhea"}, {"id": "b", "text": "Vaults"}, {"id": "c", "text": "Coitus interruptus"}, {"id": "d", "text": "Periodic abstinence"}]'::jsonb, 'b', 'Vaults are a barrier method; the others are natural methods.', 'Natural methods avoid meeting of ovum and sperm without devices or chemicals. They include periodic abstinence, withdrawal (coitus interruptus) and lactational amenorrhea. Diaphragms, cervical caps and vaults are barrier devices placed in the female reproductive tract.', '{"a": "Lactational amenorrhea is a natural method, effective for up to about six months after parturition.", "c": "Withdrawal is a natural method.", "d": "Avoiding coitus on days 10–17 is a natural method."}'::jsonb, 'Diaphragms, cervical caps and vaults are reusable barrier methods for females.', 'easy', true, 2024, NULL, 'NEET UG 2024 (NTA) · answer verified by UG Prep', NULL),
('fdabc761-ea59-5a54-ba50-86b826f5256e', 'neet_ug', 'Zoology', 'Animal Kingdom', 'Match List I with List II:
List-I | List-II
A. Pleurobrachia | I. Mollusca
B. Radula | II. Ctenophora
C. Stomochord | III. Osteichthyes
D. Air bladder | IV. Hemichordata
Choose the correct answer form the options given below:', '[{"id": "a", "text": "A-II, B-IV, C-I, D-III"}, {"id": "b", "text": "A-IV, B-III, C-II, D-I"}, {"id": "c", "text": "A-IV, B-II, C-III, D-I"}, {"id": "d", "text": "A-II, B-I, C-IV, D-III"}]'::jsonb, 'd', 'Pleurobrachia is a ctenophore, radula belongs to molluscs, stomochord to hemichordates and air bladder to bony fishes.', 'Pleurobrachia (sea walnut) is a ctenophore. The radula is the file-like rasping organ of molluscs. The stomochord is a notochord-like structure in the proboscis of hemichordates. The air bladder, which controls buoyancy, is found in bony fishes (Osteichthyes). So the match is A-II, B-I, C-IV, D-III.', '{"a": "Radula is not a hemichordate feature.", "b": "Pleurobrachia is not a hemichordate.", "c": "Pleurobrachia is a ctenophore, not a hemichordate."}'::jsonb, 'Ctenophores have eight external rows of ciliated comb plates for locomotion and show bioluminescence.', 'easy', true, 2024, NULL, 'NEET UG 2024 (NTA) · answer verified by UG Prep', NULL),
('7c5089ad-ede5-5539-a930-7ac97dd52b96', 'neet_ug', 'Zoology', 'Cell: The Unit of Life', 'Match List I with List II:
List-I | List-II
A. Axoneme | I. Centriole
B. Cartwheel pattern | II. Cilia and flagella
C. Crista | III. Chromosome
D. Satellite | IV. Mitochondria
Choose the correct answer form the options given below:', '[{"id": "a", "text": "A-II, B-IV, C-I, D-III"}, {"id": "b", "text": "A-II, B-I, C-IV, D-III"}, {"id": "c", "text": "A-IV, B-III, C-II, D-I"}, {"id": "d", "text": "A-IV, B-II, C-III, D-II"}]'::jsonb, 'b', 'Axoneme belongs to cilia and flagella, cartwheel to centriole, cristae to mitochondria and satellite to chromosome.', 'The axoneme is the 9+2 microtubule core of cilia and flagella. Centrioles show a cartwheel arrangement of nine peripheral triplet fibrils. Cristae are infoldings of the inner mitochondrial membrane. A satellite is the small piece of chromosome beyond a secondary constriction. So the match is A-II, B-I, C-IV, D-III.', '{"a": "Cartwheel pattern is not a mitochondrial feature.", "c": "Axoneme is not a mitochondrial feature.", "d": "Axoneme is not mitochondrial, and the option repeats II."}'::jsonb, 'Centrioles form the basal bodies of cilia and flagella and the spindle apparatus in animal cells.', 'easy', true, 2024, NULL, 'NEET UG 2024 (NTA) · answer verified by UG Prep', NULL),
('6167ff1f-3cdd-5ace-8180-ea4717edc5d4', 'neet_ug', 'Zoology', 'Biotechnology: Principles and Processes', 'Which of the following statements is incorrect?', '[{"id": "a", "text": "Bio-reactors are used to produce small scale bacterial cultures."}, {"id": "b", "text": "Bio-reactors have an agitator system, an oxygen delivery system and foam control system."}, {"id": "c", "text": "A bio-reactor provides optimal growth conditions for achieving the desired product."}, {"id": "d", "text": "Most commonly used bio-reactors are of stirring type."}]'::jsonb, 'a', 'Bioreactors are for large-volume (100–1000 L) culture, not small scale.', 'Bioreactors are vessels for processing large volumes of culture to obtain large amounts of product. They provide optimal temperature, pH, substrate, vitamins and oxygen. The most common is the stirred-tank type, with agitator, oxygen delivery, foam control, temperature and pH control systems, and sampling ports. Statement (1) wrongly says small scale.', '{"b": "This correctly describes the components of a stirred-tank bioreactor.", "c": "This is the stated purpose of a bioreactor.", "d": "Stirred-tank bioreactors are indeed the most common."}'::jsonb, 'Downstream processing (separation, purification, formulation) follows biosynthesis in the bioreactor.', 'easy', true, 2024, NULL, 'NEET UG 2024 (NTA) · answer verified by UG Prep', NULL),
('1820e39a-b18a-5707-9362-006b7fe20b66', 'neet_ug', 'Zoology', 'Cell Cycle and Cell Division', 'Match List I with List II:
List-I (Sub phases of prophase I) | List-II (Specific characters)
A. Diakinesis | I. Synaptonemal complex formation
B. Pachytene | II. Completion of terminalisation of chiasmata
C. Zygotene | III. Chromosomes look like thin threads
D. Leptotene | IV. Appearance of recombination nodules
Choose the correct answer form the options given below:', '[{"id": "a", "text": "A-II, B-IV, C-I, D-III"}, {"id": "b", "text": "A-IV, B-III, C-II, D-I"}, {"id": "c", "text": "A-IV, B-II, C-III, D-I"}, {"id": "d", "text": "A-I, B-II, C-IV, D-III"}]'::jsonb, 'a', 'Leptotene has thin threads, zygotene forms the synaptonemal complex, pachytene has recombination nodules and diakinesis completes terminalisation.', 'In leptotene, chromosomes become visible as thin threads. Synapsis and the synaptonemal complex form in zygotene. In pachytene, recombination nodules appear where crossing over happens. Terminalisation of chiasmata is completed in diakinesis. So the match is A-II, B-IV, C-I, D-III.', '{"b": "Recombination nodules are not a diakinesis feature.", "c": "Diakinesis does not show recombination nodules.", "d": "The synaptonemal complex forms in zygotene, not diakinesis."}'::jsonb, 'Chiasmata, the X-shaped sites of crossing over, become visible in diplotene as the synaptonemal complex dissolves.', 'easy', true, 2024, NULL, 'NEET UG 2024 (NTA) · answer verified by UG Prep', NULL),
('23ea493d-315c-5c32-9c46-8547031bbe72', 'neet_ug', 'Zoology', 'Human Health and Disease', 'Match List I with List II:
List-I | List-II
A. Common cold | I. Plasmodium
B. Haemozoin | II. Typhoid
C. Widal test | III. Rhinoviruses
D. Allergy | IV. Dust mites
Choose the correct answer form the options given below:', '[{"id": "a", "text": "A-III, B-I, C-II, D-IV"}, {"id": "b", "text": "A-IV, B-II, C-III, D-I"}, {"id": "c", "text": "A-II, B-IV, C-III, D-I"}, {"id": "d", "text": "A-I, B-III, C-II, D-IV"}]'::jsonb, 'a', 'Common cold comes from rhinoviruses, haemozoin from Plasmodium, the Widal test detects typhoid and dust mites cause allergy.', 'Rhinoviruses cause the common cold. Haemozoin is the toxin released when RBCs infected with Plasmodium rupture, and it causes the cyclic chills and fever of malaria. The Widal test confirms typhoid. Dust mites are common allergens. So the match is A-III, B-I, C-II, D-IV.', '{"b": "Common cold is not caused by dust mites.", "c": "Common cold is not typhoid.", "d": "Common cold is not caused by Plasmodium."}'::jsonb, 'Allergy involves IgE antibodies and release of histamine and serotonin from mast cells.', 'easy', true, 2024, NULL, 'NEET UG 2024 (NTA) · answer verified by UG Prep', NULL),
('c1976800-91c1-540c-b224-8fa4b15d0fbf', 'neet_ug', 'Zoology', 'Human Health and Disease', 'Given below are two statements: one is labelled as Assertion A and the other is labelled as Reason R:
Assertion A: Breast-feeding during initial period of infant growth is recommended by doctors for bringing a healthy baby
Reason R: Colostrum contains several antibodies absolutely essential to develop resistance for the new born baby.
In the light of the above statements, choose the most appropriate answer from the options given below:', '[{"id": "a", "text": "A is correct but R is not correct."}, {"id": "b", "text": "A is not correct but R is correct."}, {"id": "c", "text": "Both A and R are correct and R is the correct explanation of A."}, {"id": "d", "text": "Both A and R are correct but R is NOT the correct explanation of A."}]'::jsonb, 'c', 'Colostrum''s IgA antibodies give passive immunity, which is why breast-feeding is recommended.', 'Colostrum, the yellowish milk secreted in the first few days of lactation, is rich in IgA antibodies. These give the newborn passive immunity and help it develop resistance. That is exactly why doctors recommend breast-feeding in the early period, so R correctly explains A.', '{"a": "R is a correct NCERT statement.", "b": "A is correct.", "d": "R directly explains why breast-feeding is recommended."}'::jsonb, 'Antibodies passed from mother to foetus through the placenta and to the infant through colostrum give passive immunity.', 'easy', true, 2024, NULL, 'NEET UG 2024 (NTA) · answer verified by UG Prep', NULL),
('d2bc0148-2fb8-5574-ba8a-b509dbd80f17', 'neet_ug', 'Zoology', 'Animal Kingdom', 'Match List I with List II:
List-I | List-II
A. Pterophyllum | I. Hag fish
B. Myxine | II. Saw fish
C. Pristis | III. Angel fish
D. Exocoetus | IV. Flying fish
Choose the correct answer form the options given below:', '[{"id": "a", "text": "A-IV, B-I, C-II, D-III"}, {"id": "b", "text": "A-III, B-II, C-I, D-IV"}, {"id": "c", "text": "A-II, B-I, C-III, D-IV"}, {"id": "d", "text": "A-III, B-I, C-II, D-IV"}]'::jsonb, 'd', 'Pterophyllum is angel fish, Myxine is hagfish, Pristis is sawfish and Exocoetus is flying fish.', 'Pterophyllum is the freshwater angel fish, a bony fish. Myxine is the hagfish, a cyclostome. Pristis is the sawfish, a cartilaginous fish. Exocoetus is the flying fish, a bony fish. So the match is A-III, B-I, C-II, D-IV.', '{"a": "Pterophyllum is not the flying fish.", "b": "Myxine is the hagfish, not the sawfish.", "c": "Pterophyllum is not the sawfish."}'::jsonb, 'Cyclostomes (Petromyzon, Myxine) are jawless ectoparasites on fishes.', 'easy', true, 2024, NULL, 'NEET UG 2024 (NTA) · answer verified by UG Prep', NULL),
('73a73b0f-89b5-5d39-b92d-2e7cc8cf67cf', 'neet_ug', 'Zoology', 'Biotechnology: Principles and Processes', 'The "Ti plasmid" of Agrobacterium tumefaciens stands for', '[{"id": "a", "text": "Tumor inducing plasmid"}, {"id": "b", "text": "Temperature independent plasmid"}, {"id": "c", "text": "Tumour inhibiting plasmid"}, {"id": "d", "text": "Tumor independent plasmid"}]'::jsonb, 'a', 'Ti stands for tumour-inducing.', 'Agrobacterium tumefaciens causes crown gall in dicots by transferring T-DNA from its Ti (tumour-inducing) plasmid into the plant cell genome. Once its pathogenic genes are removed, the plasmid is used as a cloning vector for plants.', '{"b": "Ti has nothing to do with temperature.", "c": "It induces tumours; it does not inhibit them.", "d": "Not what Ti stands for."}'::jsonb, 'Retroviruses are disarmed in the same way to serve as vectors for animal cells.', 'easy', true, 2024, NULL, 'NEET UG 2024 (NTA) · answer verified by UG Prep', NULL),
('7bdbdd52-4ff3-5b6f-89cb-67e4bad38a00', 'neet_ug', 'Zoology', 'Human Reproduction', 'Which of the following is not a component of Fallopian tube?', '[{"id": "a", "text": "Infundibulum"}, {"id": "b", "text": "Ampulla"}, {"id": "c", "text": "Uterine fundus"}, {"id": "d", "text": "Isthmus"}]'::jsonb, 'c', 'The fundus is part of the uterus; the oviduct has infundibulum, ampulla and isthmus.', 'Each fallopian tube has a funnel-shaped infundibulum with fimbriae near the ovary, a wider ampulla, and a narrow isthmus that joins the uterus. The fundus is the dome-shaped upper part of the uterus, not of the oviduct.', '{"a": "The infundibulum is the funnel-shaped end of the oviduct.", "b": "The ampulla is the wider middle part where fertilisation occurs.", "d": "The isthmus is the last narrow part of the oviduct."}'::jsonb, 'Fertilisation normally occurs at the ampullary region of the fallopian tube.', 'easy', true, 2024, NULL, 'NEET UG 2024 (NTA) · answer verified by UG Prep', NULL),
('c6792fa9-4e21-5d3b-9074-6ebdf018a9e3', 'neet_ug', 'Zoology', 'Principles of Inheritance and Variation', 'Match List I with List II:
List-I | List-II
A. Down''s syndrome | I. 11th chromosome
B. α-Thalassemia | II. ''X'' chromosome
C. β-Thalassemia | III. 21st chromosome
D. Klinefelter''s | IV. 16th chromosome
Choose the correct answer form the options given below:', '[{"id": "a", "text": "A-III, B-IV, C-I, D-II"}, {"id": "b", "text": "A-IV, B-I, C-II, D-III"}, {"id": "c", "text": "A-I, B-II, C-III, D-IV"}, {"id": "d", "text": "A-II, B-III, C-IV, D-I"}]'::jsonb, 'a', 'Down''s involves chromosome 21, α-thalassemia chromosome 16, β-thalassemia chromosome 11 and Klinefelter''s the X chromosome.', 'Down''s syndrome is trisomy of chromosome 21. α-thalassemia comes from the HBA1/HBA2 genes on chromosome 16, and β-thalassemia from the HBB gene on chromosome 11. Klinefelter''s syndrome (47, XXY) has an extra X chromosome. So the match is A-III, B-IV, C-I, D-II.', '{"b": "Down''s syndrome does not involve chromosome 16.", "c": "Down''s syndrome does not involve chromosome 11.", "d": "Down''s syndrome is not an X-chromosome disorder."}'::jsonb, 'Thalassemia is a quantitative defect (less globin made); sickle-cell anaemia is a qualitative defect (Glu→Val at position 6 of β-globin).', 'easy', true, 2024, NULL, 'NEET UG 2024 (NTA) · answer verified by UG Prep', NULL),
('ea67320f-d061-5b45-88fa-b05d184a5c22', 'neet_ug', 'Zoology', 'Animal Kingdom', 'The following are the statements about non-chordates:
A. Pharynx is perforated by gill slits.
B. Notochord is absent.
C. Central nervous system is dorsal.
D. Heart is dorsal if present.
E. Post anal tail is absent.
Choose the most appropriate answer from the options given below:', '[{"id": "a", "text": "B, D and E only"}, {"id": "b", "text": "B, C and D only"}, {"id": "c", "text": "A and C only"}, {"id": "d", "text": "A, B and D only"}]'::jsonb, 'a', 'Non-chordates lack a notochord, gill slits and post-anal tail, and have a ventral CNS and a dorsal heart.', 'NCERT contrasts the two groups. Non-chordates have no notochord, a ventral, solid, double nerve cord, no gill slits, a dorsal heart (if present) and no post-anal tail. So B, D and E are correct, while A and C describe chordates.', '{"b": "A dorsal CNS is a chordate feature.", "c": "Both A and C are chordate features.", "d": "Pharyngeal gill slits are a chordate feature."}'::jsonb, 'Chordates have a ventral heart and a dorsal, hollow, single nerve cord.', 'easy', true, 2024, NULL, 'NEET UG 2024 (NTA) · answer verified by UG Prep', NULL),
('7ee9948f-dcd3-5c0a-b668-9cca93f27408', 'neet_ug', 'Zoology', 'Evolution', 'Match List I with List II:
List-I | List-II
A. Mesozoic Era | I. Lower invertebrates
B. Proterozoic Era | II. Fish & Amphibia
C. Cenozoic Era | III. Birds & Reptiles
D. Paleozoic Era | IV. Mammals
Choose the correct answer form the options given below:', '[{"id": "a", "text": "A-I, B-II, C-IV, D-III"}, {"id": "b", "text": "A-III, B-I, C-IV, D-II"}, {"id": "c", "text": "A-II, B-I, C-III, D-IV"}, {"id": "d", "text": "A-III, B-I, C-II, D-IV"}]'::jsonb, 'b', 'Mesozoic is the age of reptiles and birds, Proterozoic of lower invertebrates, Cenozoic of mammals and Paleozoic of fishes and amphibians.', 'The Proterozoic era had early, simple invertebrate life. The Paleozoic saw jawless and jawed fishes and then amphibians. The Mesozoic was dominated by reptiles (dinosaurs), and birds appeared then. The Cenozoic is the age of mammals. So the match is A-III, B-I, C-IV, D-II.', '{"a": "The Mesozoic is not the era of lower invertebrates.", "c": "The Mesozoic is not the era of fishes and amphibians.", "d": "The Cenozoic is the age of mammals, not of fish and amphibia."}'::jsonb, 'Dinosaurs disappeared suddenly about 65 mya, at the end of the Mesozoic.', 'med', true, 2024, NULL, 'NEET UG 2024 (NTA) · answer verified by UG Prep', NULL),
('b4ea841e-e01a-5803-a54f-7b3eb195ecfb', 'neet_ug', 'Zoology', 'Neural Control and Coordination', 'Given below are two statements:
Statement I: The cerebral hemispheres are connected by nerve tract known as corpus callosum.
Statement II: The brain stem consists of the medulla oblongata, pons and cerebrum.
In the light of the above statements, choose the most approriate answer from the options given below:', '[{"id": "a", "text": "Statement I is correct but statement II is incorrect."}, {"id": "b", "text": "Statement I is incorrect but statement II is correct."}, {"id": "c", "text": "Both statement I and Statement II are correct."}, {"id": "d", "text": "Both statement I and Statement II are incorrect."}]'::jsonb, 'a', 'The brain stem is the midbrain, pons and medulla, not the cerebrum.', 'The two cerebral hemispheres are connected by a tract of nerve fibres called the corpus callosum, so Statement I is correct. The brain stem is made of the midbrain, pons and medulla oblongata. The cerebrum is part of the forebrain, so Statement II is incorrect.', '{"b": "Statement I is correct.", "c": "Statement II wrongly includes the cerebrum.", "d": "Statement I is correct."}'::jsonb, 'The brain stem connects the brain to the spinal cord.', 'easy', true, 2024, NULL, 'NEET UG 2024 (NTA) · answer verified by UG Prep', NULL),
('fbc2c3d4-4d22-5e3b-886c-14158a68c871', 'neet_ug', 'Zoology', 'Human Reproduction', 'Identify the correct option (A), (B), (C), (D) with respect to spermatogenesis.
GnRH → LH and (A)
LH → (B) → Androgens → Formation of spermatids
(A) → (C) → Factors → (D)', '[{"id": "a", "text": "FSH, Sertoli cells, Leydig cells, spermatogenesis."}, {"id": "b", "text": "ICSH, Leydig cells, Sertoli cells spermatogenesis."}, {"id": "c", "text": "FSH, Leydig cells, Sertoli cells, spermiogenesis"}, {"id": "d", "text": "ICSH, Interstitial cells, Leydig cells, spermiogenesis."}]'::jsonb, 'c', 'GnRH releases LH and FSH; LH acts on Leydig cells and FSH on Sertoli cells, whose factors drive spermiogenesis.', 'GnRH from the hypothalamus stimulates the pituitary to release LH and FSH, so (A) is FSH. LH acts on Leydig cells (B), which secrete androgens that stimulate spermatogenesis. FSH acts on Sertoli cells (C), which secrete factors that help spermiogenesis (D), the change of spermatids into sperms. So option (3) is correct.', '{"a": "LH acts on Leydig cells, not Sertoli cells.", "b": "(A) is FSH, since LH and ICSH are the same hormone already shown on the left.", "d": "(A) cannot be ICSH, and Leydig cells are the same as interstitial cells."}'::jsonb, 'LH in males is also called ICSH (interstitial cell stimulating hormone).', 'med', true, 2024, NULL, 'NEET UG 2024 (NTA) · answer verified by UG Prep', '/pyq/ug/2024/189.webp'),
('5d7d3f8d-a448-522d-a730-86d2a8468f1b', 'neet_ug', 'Zoology', 'Molecular Basis of Inheritance', 'Match List I with List II:
List-I | List-II
A. RNA polymerase III | I. snRNPs
B. Termination of transcription | II. Promotor
C. Splicing of Exons | III. Rho factor
D. Tata box | IV. SnRNAs, tRNA
Choose the correct answer form the options given below:', '[{"id": "a", "text": "A-III, B-IV, C-I, D-II"}, {"id": "b", "text": "A-IV, B-III, C-I, D-II"}, {"id": "c", "text": "A-II, B-IV, C-I, D-III"}, {"id": "d", "text": "A-III, B-II, C-IV, D-I"}]'::jsonb, 'b', 'RNA pol III makes tRNA and snRNA, rho ends transcription, snRNPs splice and the TATA box is in the promoter.', 'In eukaryotes, RNA polymerase III transcribes tRNA, 5S rRNA and snRNAs. In bacteria, the rho factor helps terminate transcription. Splicing, which removes introns and joins exons, is done by the spliceosome made of snRNPs. The TATA box is part of the promoter. So the match is A-IV, B-III, C-I, D-II.', '{"a": "RNA pol III is not the rho factor.", "c": "RNA pol III is not the promoter.", "d": "Termination is not done by the promoter."}'::jsonb, 'RNA pol I makes rRNAs (28S, 18S, 5.8S); RNA pol II makes hnRNA (the precursor of mRNA).', 'med', true, 2024, NULL, 'NEET UG 2024 (NTA) · answer verified by UG Prep', NULL),
('80b6e763-938c-5d78-bb4f-8337dfe68485', 'neet_ug', 'Zoology', 'Chemical Coordination and Integration', 'Match List I with List II:
List-I | List-II
A. Exophthalmic goiter | I. Excess secretion of cortisol, moon face & hyperglycemia
B. Acromegaly | II. Hypo-secretion of thyroid hormone and stunted growth.
C. Cushing''s syndrome | III. Hyper secretion of thyroid hormone & protruding eye balls.
D. Cretinism | IV. Excessive secretion of growth hormone.
Choose the correct answer form the options given below:', '[{"id": "a", "text": "A-III, B-IV, C-II, D-I"}, {"id": "b", "text": "A-III, B-IV, C-I, D-II"}, {"id": "c", "text": "A-I, B-III, C-II, D-IV"}, {"id": "d", "text": "A-IV, B-II, C-I, D-III"}]'::jsonb, 'b', 'Graves'' disease is hyperthyroidism, acromegaly is excess GH in adults, Cushing''s is excess cortisol and cretinism is childhood hypothyroidism.', 'Exophthalmic goitre (Graves'' disease) is hyperthyroidism with protruding eyeballs. Acromegaly comes from excess growth hormone in adults. Cushing''s syndrome is excess cortisol, with moon face and hyperglycaemia. Cretinism is hypothyroidism during development, causing stunted growth and mental retardation. So the match is A-III, B-IV, C-I, D-II.', '{"a": "Cushing''s syndrome is not hypothyroidism.", "c": "Exophthalmic goitre is not excess cortisol.", "d": "Exophthalmic goitre is not excess GH."}'::jsonb, 'Excess GH in children causes gigantism; too little causes dwarfism.', 'easy', true, 2024, NULL, 'NEET UG 2024 (NTA) · answer verified by UG Prep', NULL),
('286e7c30-c7cd-5bd4-bfd2-c77fb63dfded', 'neet_ug', 'Zoology', 'Structural Organisation in Animals', 'Match List I with List II:
List-I | List-II
A. Unicellular glandular epithelium | I. Salivary glands
B. Compound epithelium | II. Pancreas
C. Multicellular glandular epithelium | III. Goblet cells of alimentary canal
D. Endocrine glandular epithelium | IV. Moist surface of buccal cavity
Choose the correct answer form the options given below:', '[{"id": "a", "text": "A-III, B-IV, C-I, D-II"}, {"id": "b", "text": "A-II, B-I, C-IV, D-III"}, {"id": "c", "text": "A-II, B-I, C-III, D-IV"}, {"id": "d", "text": "A-IV, B-III, C-I, D-II"}]'::jsonb, 'a', 'Goblet cells are unicellular glands, the buccal cavity has compound epithelium, salivary glands are multicellular and the pancreas has an endocrine part.', 'Goblet cells of the alimentary canal are unicellular glands. Compound (stratified) epithelium lines the moist surface of the buccal cavity, pharynx and other places that need protection. Salivary glands are multicellular. The pancreas has endocrine tissue (islets of Langerhans) as well as exocrine tissue. So the match is A-III, B-IV, C-I, D-II.', '{"b": "Goblet cells are not endocrine.", "c": "The pancreas is not a unicellular gland.", "d": "The buccal cavity lining is not unicellular glandular epithelium."}'::jsonb, 'Compound epithelium is mainly protective and also lines the inner surface of salivary and pancreatic ducts.', 'med', true, 2024, NULL, 'NEET UG 2024 (NTA) · answer verified by UG Prep', NULL),
('bbb51f7f-8f59-551e-b3e2-c4a1a5b72d8f', 'neet_ug', 'Zoology', 'Human Health and Disease', 'Given below are two statements:
Statement I: Bone marrow is the main lymphoid organ where all blood cells including lymphocytes are produced.
Statement II: Both bone marrow and thymus provide micro environments for the development and maturation of T-lymphocytes.
In the light of the above statements, choose the most approriate answer from the options given below:', '[{"id": "a", "text": "Statement I is correct but statement II is incorrect."}, {"id": "b", "text": "Statement I is incorrect but statement II is correct."}, {"id": "c", "text": "Both statement I and Statement II are correct."}, {"id": "d", "text": "Both statement I and Statement II are incorrect."}]'::jsonb, 'c', 'Both are NCERT statements about the primary lymphoid organs.', 'Bone marrow is the main lymphoid organ, where all blood cells including lymphocytes are made. NCERT also says that the bone marrow and thymus provide micro-environments for the development and maturation of T-lymphocytes. So both statements are correct.', '{"a": "Statement II is an NCERT statement.", "b": "Statement I is an NCERT statement.", "d": "Both statements are correct."}'::jsonb, 'Primary lymphoid organs are the bone marrow and thymus; secondary ones include the spleen, lymph nodes, tonsils, Peyer''s patches and appendix.', 'med', true, 2024, NULL, 'NEET UG 2024 (NTA) · answer verified by UG Prep', NULL),
('0522ebe0-41bf-5825-8f99-c791b7f27f95', 'neet_ug', 'Zoology', 'Structural Organisation in Animals', 'Match List I with List II:
List-I | List-II
A. The structures used for storing of food. | I. Gizzard
B. Ring of 6-8 blind tubules at junction of foregut and midgut. | II. Gastric Caeca
C. Ring of 100-150 yellow coloured thin filaments at junction of midgut and hindgut. | III. Malpighian tubules
D. The structures used for grinding the food. | IV. Crop
Choose the correct answer form the options given below:', '[{"id": "a", "text": "A-IV, B-III, C-II, D-I"}, {"id": "b", "text": "A-III, B-II, C-IV, D-I"}, {"id": "c", "text": "A-IV, B-II, C-III, D-I"}, {"id": "d", "text": "A-I, B-II, C-III, D-IV"}]'::jsonb, 'c', 'In the cockroach, the crop stores food, gastric caeca are 6–8 tubules, Malpighian tubules are 100–150 filaments and the gizzard grinds food.', 'The crop stores food in the cockroach. A ring of 6–8 blind gastric caeca at the foregut–midgut junction secretes digestive juice. A ring of 100–150 yellow Malpighian tubules at the midgut–hindgut junction removes excretory products. The gizzard (proventriculus), with chitinous teeth, grinds food. So the match is A-IV, B-II, C-III, D-I.', '{"a": "Gastric caeca and Malpighian tubules are swapped.", "b": "The crop, not Malpighian tubules, stores food.", "d": "The gizzard grinds; it does not store food."}'::jsonb, 'Cockroach Malpighian tubules excrete uric acid, so the cockroach is uricotelic.', 'easy', true, 2024, NULL, 'NEET UG 2024 (NTA) · answer verified by UG Prep', NULL),
('61fa011f-0ae9-5292-a42f-b371aea7731b', 'neet_ug', 'Zoology', 'Excretory Products and their Elimination', 'Choose the correct statement given below regarding juxta medullary nephron.', '[{"id": "a", "text": "Loop of Henle of juxtamedullary nephron runs deep into medulla."}, {"id": "b", "text": "Juxtamedullary nephrons outnumber the cortical nephtons."}, {"id": "c", "text": "Juxtamedullary nephrons are located in the columns of Bertini."}, {"id": "d", "text": "Renal corpuscle of juxtamedullary nephron lies in the outer portion of he renal medulla."}]'::jsonb, 'a', 'Juxtamedullary nephrons have very long loops of Henle that dip deep into the medulla.', 'In juxtamedullary nephrons, the loop of Henle is very long and runs deep into the medulla. Cortical nephrons make up most of the nephrons. Like all nephrons, the renal corpuscles of juxtamedullary nephrons sit in the cortex, near the corticomedullary junction, not in the columns of Bertini or the medulla.', '{"b": "Cortical nephrons are the majority.", "c": "Columns of Bertini are cortical extensions between pyramids, not where these nephrons lie.", "d": "Renal corpuscles always lie in the cortex."}'::jsonb, 'The vasa recta is absent or highly reduced in cortical nephrons.', 'easy', true, 2024, NULL, 'NEET UG 2024 (NTA) · answer verified by UG Prep', NULL),
('996e5670-2a0d-57c1-843c-5b7308e0e173', 'neet_ug', 'Zoology', 'Body Fluids and Circulation', 'Match List I with List II:
List-I | List-II
A. P wave | I. Heart muscles are electrically silent.
B. QRS complex | II. Depolarisation of ventricles.
C. T wave | III. Depolarisation of atria.
D. T-P gap | IV. Repolarisation of ventricles.
Choose the correct answer form the options given below:', '[{"id": "a", "text": "A-II, B-III, C-I, D-IV"}, {"id": "b", "text": "A-IV, B-II, C-I, D-III"}, {"id": "c", "text": "A-I, B-III, C-IV, D-II"}, {"id": "d", "text": "A-III, B-II, C-IV, D-I"}]'::jsonb, 'd', 'P is atrial depolarisation, QRS is ventricular depolarisation, T is ventricular repolarisation and the T-P gap is electrical silence.', 'On an ECG, the P wave is atrial depolarisation and the QRS complex is ventricular depolarisation. The T wave is ventricular repolarisation. During the T-P interval the heart muscle is electrically silent until the next P wave. So the match is A-III, B-II, C-IV, D-I.', '{"a": "The P wave reflects atria, not ventricles.", "b": "The P wave is not repolarisation.", "c": "The P wave is not electrical silence."}'::jsonb, 'Counting QRS complexes in a given time gives the heart rate.', 'easy', true, 2024, NULL, 'NEET UG 2024 (NTA) · answer verified by UG Prep', NULL),
('2c498392-8d3f-5554-8142-40216a0ef020', 'neet_ug', 'Zoology', 'Principles of Inheritance and Variation', 'As per ABO blood grouping system, the blood group of fathers is B⁺, mother is A⁺ and child is O⁺. Their respective genotype can be
A. Iᴮi/Iᴬi/ii
B. IᴮIᴮ/IᴬIᴬ/ii
C. IᴬIᴮ/iIᴬ/Iᴮi
D. Iᴬi/Iᴮi/Iᴬi
E. iIᴮ/iIᴬ/IᴬIᴮ
Choose the most appropriate answer from the options given below:', '[{"id": "a", "text": "C & B only"}, {"id": "b", "text": "D & E only"}, {"id": "c", "text": "A only"}, {"id": "d", "text": "B only"}]'::jsonb, 'c', 'For an O child, both parents must carry i, so the father is Iᴮi and the mother Iᴬi.', 'A group O child is ii and must get one i from each parent. So the B father must be Iᴮi and the A mother Iᴬi, which is set A. Set B has homozygous parents who cannot give i. Set C has an AB father, and sets D and E give the wrong group to the father or child.', '{"a": "In set C the father is AB, and in set B neither parent carries i.", "b": "In set D the father is group A and the child A; in set E the child is AB.", "d": "Homozygous IᴮIᴮ × IᴬIᴬ parents can only have AB children."}'::jsonb, 'Iᴬ and Iᴮ are codominant and both are dominant over i.', 'med', true, 2024, NULL, 'NEET UG 2024 (NTA) · answer verified by UG Prep', NULL),
('1bb45e2c-8fbe-5f7c-8ed7-999d1753c33b', 'neet_ug', 'Zoology', 'Organisms and Populations', 'Given below are two statements:
Statement I: Gause''s competitive exclusive principle states that two closely related species competing for different resources cannot exist indefinitely.
Statement II: According to Gause''s principle, during competition, the inferior will be eliminated. This may be true if resources are limiting.
In the light of the above statements, choose the most approriate answer from the options given below:', '[{"id": "a", "text": "Statement I is true but Statement II is false."}, {"id": "b", "text": "Statement I is false but statement II is true."}, {"id": "c", "text": "Both statement I and Statement II are true."}, {"id": "d", "text": "Both statement I and Statement II are false."}]'::jsonb, 'b', 'Gause''s principle concerns species competing for the same resources, not different ones.', 'Gause''s competitive exclusion principle states that two closely related species competing for the same resources cannot co-exist indefinitely, and the competitively inferior one is eventually eliminated. Saying ''different resources'' makes Statement I false. Statement II matches NCERT, which adds that this may be true when resources are limiting.', '{"a": "Statement I is false because it says different resources.", "c": "Statement I is false.", "d": "Statement II is correct."}'::jsonb, 'Resource partitioning, as in MacArthur''s warblers, lets competing species co-exist.', 'med', true, 2024, NULL, 'NEET UG 2024 (NTA) · answer verified by UG Prep', NULL),
('071fad41-caff-5760-829f-b1afa0680f09', 'neet_ug', 'Zoology', 'Biomolecules', 'Regarding catalytic cycle of an enzyme action, selecte the correct sequential steps:
A. Substrate enzyme complex formation.
B. Free enzyme ready to bind with another substrate.
C. Release fo products.
D. Chemical bonds of the substrate broken.
E. Substrate bindig to active site.
Choose the correct answer from the options given below:', '[{"id": "a", "text": "B, A, C, D, E"}, {"id": "b", "text": "E, D, C, B, A"}, {"id": "c", "text": "E, A, D, C, B"}, {"id": "d", "text": "A, E, B, D, C"}]'::jsonb, 'c', 'Binding → ES complex → bonds broken → products released → free enzyme.', 'The substrate first binds the active site, forming the enzyme–substrate complex, and the enzyme then grips it more tightly. Next, the active site breaks chemical bonds in the substrate to form products. The products are released, and the free enzyme is ready to bind another substrate. So the order is E, A, D, C, B.', '{"a": "Cannot start with the free enzyme step and end with binding.", "b": "Bonds cannot be broken before the ES complex forms.", "d": "The ES complex cannot form before binding, and the free enzyme is the last step."}'::jsonb, 'Enzymes lower activation energy; the ES complex is short-lived (transient).', 'easy', true, 2024, NULL, 'NEET UG 2024 (NTA) · answer verified by UG Prep', NULL),
('7512c8f9-2b40-5bee-9fb7-27b191720a0c', 'neet_ug', 'Zoology', 'Cell: The Unit of Life', 'Given below are two statements:
Statement I: Mitochondria and chloroplasts are both double membrane bound organelles.
Statement II: Inner membrane of mitochondria is relatively less permeable, as compared to chloroplast.
In the light of the above statements, choose the most approriate answer from the options given below:', '[{"id": "a", "text": "Statement I is correct but statement II is incorrect."}, {"id": "b", "text": "Statement I is incorrect but statement II is correct."}, {"id": "c", "text": "Both statement I and Statement II are correct."}, {"id": "d", "text": "Both statement I and Statement II are incorrect."}]'::jsonb, 'a', 'Both organelles have double membranes, but the inner chloroplast membrane is the relatively less permeable one in NCERT.', 'Mitochondria and chloroplasts are both bounded by two membranes, so Statement I is correct. In the chloroplast section, NCERT says the inner membrane of the chloroplast is relatively less permeable. Statement II turns this comparison around, so it is taken as incorrect.', '{"b": "Statement I is correct.", "c": "Statement II reverses the NCERT comparison.", "d": "Statement I is correct."}'::jsonb, 'Both mitochondria and chloroplasts contain their own circular DNA and 70S ribosomes.', 'hard', true, 2024, NULL, 'NEET UG 2024 (NTA) · answer verified by UG Prep', NULL)
